controlled_review_v3.adapter_add(p_state.source:
declare
 state jsonb:=p_state; identity text; prior jsonb; item jsonb; rank integer; old_rank integer;
 roles text[]:=array['reviewed_target','correction_target','case_report','ordinary_source','original_intake','original_pickup','amendment_predecessor','original_dispense','resolution_correction','opening_basis','retained_context'];
 expected_key jsonb; count_rows integer;
begin
 if jsonb_typeof(state) is distinct from 'object' or jsonb_typeof(state->'rows') is distinct from 'object'
 or jsonb_typeof(p_key) is distinct from 'object' or jsonb_typeof(p_row) is distinct from 'object'
 or p_relation is null or p_role is null or not(p_role=any(roles)) then
  raise exception 'adapter_source_integrity' using errcode='23514';
 end if;
 if octet_length(state::text)>1048576 or octet_length(p_row::text)>1048576 then
  raise exception 'evidence_limit_exceeded' using errcode='54000';
 end if;
 expected_key:=case p_relation
 when 'public.stock_movement_sources' then jsonb_build_object('movement_id',p_row->'movement_id')
 when 'public.stock_custody_sources' then jsonb_build_object('event_id',p_row->'event_id')
 when 'public.stock_pickup_sources' then jsonb_build_object('event_id',p_row->'event_id')
 when 'public.stock_discrepancy_sources' then jsonb_build_object('event_id',p_row->'event_id')
 when 'public.stock_correction_sources' then jsonb_build_object('event_id',p_row->'event_id')
 when 'public.controlled_stock_opening_movements' then jsonb_build_object('opening_id',p_row->'opening_id','movement_id',p_row->'movement_id')
 else jsonb_build_object('id',p_row->'id') end;
 if p_key is distinct from expected_key or exists(select 1 from jsonb_each(p_key) x where jsonb_typeof(x.value)<>'string')
 or p_relation<>all(array[
 'public.controlled_stock_events','public.controlled_stock_actions','public.controlled_stock_preparations',
 'public.controlled_stock_policy_versions','public.controlled_stock_openings','public.controlled_stock_source_links',
 'public.controlled_stock_event_lines','public.controlled_stock_container_transitions','public.controlled_stock_cells',
 'public.controlled_stock_containers','public.inventory_movements','public.stock_movement_sources','public.inventory_lots',
 'public.patient_treatments','public.billing_invoice_items','public.treatment_alert_reviews','public.anesthesia_drug_administrations',
 'public.native_dispenses','public.native_fulfillment_operations','public.native_dispense_allocations','public.native_pickups',
 'public.stock_pickup_sources','public.native_return_events','public.native_return_operations','public.stock_custody_sources',
 'public.native_return_stock_links','public.native_return_compensation_links','public.native_return_discrepancy_events',
 'public.native_return_discrepancy_operations','public.stock_discrepancy_sources','public.native_return_discrepancy_correction_links',
 'public.native_dispense_correction_events','public.native_dispense_correction_operations','public.stock_correction_sources',
 'public.controlled_stock_opening_movements']) then
  raise exception 'adapter_source_integrity' using errcode='23514';
 end if;
 identity:=jsonb_build_array(p_relation,p_key)::text;
 prior:=state->'rows'->identity;
 rank:=array_position(roles,p_role);
 item:=jsonb_build_object('relation',p_relation,'key',p_key,'row',p_row,'row_hash',public.controlled_stock_hash(p_row),'role',p_role);
 if prior is not null then
  if prior->'row' is distinct from p_row or prior->>'row_hash' is distinct from item->>'row_hash' then
   raise exception 'adapter_source_role_conflict' using errcode='23514';
  end if;
  old_rank:=array_position(roles,prior->>'role');
  if old_rank is null then raise exception 'adapter_source_role_conflict' using errcode='23514';end if;
  if old_rank<=rank then return state;end if;
 else
  select count(*) into count_rows from jsonb_object_keys(state->'rows');
  if count_rows>=512 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
  if p_relation=any(array['public.native_dispenses','public.native_pickups','public.native_return_events',
   'public.native_return_discrepancy_events','public.native_dispense_correction_events']) then
   if jsonb_array_length(state->'documents')>=100 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
   state:=jsonb_set(state,'{documents}',(state->'documents')||jsonb_build_array(identity));
  end if;
  if p_relation='public.native_dispense_allocations' then
   if jsonb_array_length(state->'allocations')>=100 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
   state:=jsonb_set(state,'{allocations}',(state->'allocations')||jsonb_build_array(p_row->'id'));
  end if;
 end if;
 state:=jsonb_set(state,array['rows',identity],item);
 if octet_length(state::text)>1048576 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
 return state;
end

controlled_review_v3.adapter_clinical(p_.source:
declare state jsonb:=p_state; e public.controlled_stock_events; p public.controlled_stock_preparations;
 m public.inventory_movements; t public.patient_treatments; i public.billing_invoice_items;
 a public.treatment_alert_reviews; link public.anesthesia_drug_administrations; n integer;
begin
 select * into e from public.controlled_stock_events where id=p_event_id;
 select * into p from public.controlled_stock_preparations where id=p_event_id;
 if e.id is null or e.writer<>all(array['receive_inventory','adjust_inventory','record_patient_treatment','record_anesthesia_drug_administration']) then
  raise exception 'unsupported_event_kind' using errcode='22023';end if;
 select count(*) into n from(select movement_id from public.stock_movement_sources where writer=e.writer and source_id=e.id limit 2)q;
 if n<>1 or not exists(select 1 from public.stock_movement_sources where writer=e.writer and source_id=e.id and movement_id=e.id) then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 state:=controlled_review_v3.adapter_movement(state,e.id,e.writer,e.id,e.actor_id,'reviewed_target',true);
 select * into m from public.inventory_movements where id=e.id;
 if e.writer='receive_inventory' then
  if m.kind<>'receive' or m.quantity<=0 then raise exception 'adapter_source_integrity' using errcode='23514';end if;
 elsif e.writer='adjust_inventory' then
  if m.kind<>'adjust' then raise exception 'adapter_source_integrity' using errcode='23514';end if;
 else
  select * into t from public.patient_treatments where id=e.id;
  select * into i from public.billing_invoice_items where id=e.id;
  select * into a from public.treatment_alert_reviews where treatment_id=e.id;
  if t.id is null or i.id is null or a.id is null or t.historical or t.product_id<>e.product_id or t.lot_id<>m.lot_id
  or t.created_by<>e.actor_id or i.created_by<>e.actor_id or a.reviewed_by<>e.actor_id
  or t.invoice_id<>i.invoice_id or t.pet_id is distinct from i.pet_id or t.pet_id<>a.pet_id or i.product_id<>e.product_id
  or m.quantity<>-t.quantity or i.quantity<>t.quantity or m.kind<>'dispense'
  or t.administered_at is distinct from e.observed_at
  or t.administered_at is distinct from(p.canonical_arguments#>>'{request,administered_at}')::timestamptz
  or a.source_hash is distinct from public.controlled_stock_hash(a.snapshot)
  or a.source_hash is distinct from t.request#>>'{alert_review,source_hash}' then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  state:=controlled_review_v3.adapter_add(state,'public.patient_treatments',jsonb_build_object('id',t.id),to_jsonb(t),'reviewed_target');
  state:=controlled_review_v3.adapter_add(state,'public.billing_invoice_items',jsonb_build_object('id',i.id),to_jsonb(i),'reviewed_target');
  state:=controlled_review_v3.adapter_add(state,'public.treatment_alert_reviews',jsonb_build_object('id',a.id),to_jsonb(a),'reviewed_target');
  if e.writer='record_anesthesia_drug_administration' then
   select * into link from public.anesthesia_drug_administrations where id=e.id;
   if link.id is null or link.created_by<>e.actor_id or link.pet_id<>t.pet_id
   or link.record_id::text is distinct from p.canonical_arguments->>'record_id'
   or link.pet_id::text is distinct from p.canonical_arguments->>'pet_id'
   or link.request is distinct from((p.canonical_arguments->'request')||jsonb_build_object('pet_id',link.pet_id,'source','Anesthesia record '||link.record_id::text))
   or link.request is distinct from t.request then
    raise exception 'adapter_source_integrity' using errcode='23514';end if;
   state:=controlled_review_v3.adapter_add(state,'public.anesthesia_drug_administrations',jsonb_build_object('id',link.id),to_jsonb(link),'reviewed_target');
  end if;
 end if;
 return state;
end

controlled_review_v3.adapter_context(p_s.source:
declare state jsonb:=p_state; e public.controlled_stock_events; target jsonb; source jsonb;
 row_value jsonb; operation jsonb; provenance jsonb; managed jsonb; did uuid; selected_id uuid; role_name text;
 selected_ids uuid[]; predecessor uuid; original_source uuid; selected_case_id uuid; selected_correction_id uuid;
 correction public.native_return_events; link public.native_return_discrepancy_correction_links;
 n integer:=0; count_links integer; last_id text:='';
begin
 select * into e from public.controlled_stock_events where id=p_event_id;
 if e.id is null then raise exception 'adapter_parent_integrity' using errcode='23514';end if;
 if e.writer='append_native_dispense_correction' then
  select to_jsonb(r) into target from public.native_dispense_correction_events r where r.id=e.id;
  if target is null then raise exception 'adapter_source_integrity' using errcode='23514';end if;
  did:=(target->>'dispense_id')::uuid;
  predecessor:=(target#>>'{document,amends_event_id}')::uuid;
  selected_ids:=array[e.id];
  if predecessor is not null then
   select to_jsonb(r) into source from public.native_dispense_correction_events r where r.id=predecessor;
   if source is null or predecessor=e.id or source->>'dispense_id' is distinct from did::text
   or source->>'kind' is distinct from target->>'kind' or(source->>'sequence')::integer>=(target->>'sequence')::integer then
    raise exception 'adapter_source_integrity' using errcode='23514';end if;
   selected_ids:=selected_ids||predecessor;
  end if;
  foreach selected_id in array selected_ids loop
   role_name:=case when selected_id=e.id then 'reviewed_target' else 'amendment_predecessor' end;
   select to_jsonb(r) into row_value from public.native_dispense_correction_events r where r.id=selected_id;
   select to_jsonb(r) into operation from public.native_dispense_correction_operations r where r.id=selected_id;
   select to_jsonb(r) into provenance from public.stock_correction_sources r where r.event_id=selected_id;
   managed:=controlled_review_v3.managed_source_event(jsonb_build_object('source_kind','correction','source_id',selected_id,'product_id',e.product_id));
   if operation is null or operation->>'actor_id' is distinct from row_value->>'actor_id'
   or operation->'result' is distinct from row_value->'document'
   or row_value->>'record_hash' is distinct from public.native_fulfillment_hash((row_value->'document')-'record_hash')
   or(provenance is null and managed is not null)
   or(provenance is not null and provenance->>'actor_id' is distinct from row_value->>'actor_id') then
    raise exception 'adapter_source_integrity' using errcode='23514';end if;
   -- Membership is validated above; these context-only roles declare no parent/physical edge.
   state:=controlled_review_v3.adapter_add(state,'public.native_dispense_correction_events',jsonb_build_object('id',selected_id),row_value,role_name);
   state:=controlled_review_v3.adapter_add(state,'public.native_dispense_correction_operations',jsonb_build_object('id',selected_id),operation,role_name);
   if provenance is not null then state:=controlled_review_v3.adapter_add(state,'public.stock_correction_sources',jsonb_build_object('event_id',selected_id),provenance,role_name);end if;
  end loop;
  state:=controlled_review_v3.adapter_dispense(state,did,e.product_id,'original_dispense',1);
  if target->>'kind'='pickup_amendment' then
   selected_id:=(target#>>'{document,pickup_amendment,original_pickup_id}')::uuid;
   if selected_id is null or not exists(select 1 from public.native_pickups where id=selected_id and dispense_id=did) then
    raise exception 'adapter_source_integrity' using errcode='23514';end if;
   state:=controlled_review_v3.adapter_pickup(state,selected_id,e.product_id,'original_pickup',1);
  end if;
 elsif e.writer='record_native_return_discrepancy' then
  select to_jsonb(r) into target from public.native_return_discrepancy_events r where r.id=e.id;
  if target is null then raise exception 'adapter_source_integrity' using errcode='23514';end if;
  did:=(target->>'dispense_id')::uuid;selected_case_id:=(target->>'case_id')::uuid;
  original_source:=(target#>>'{document,source,event_id}')::uuid;
  select to_jsonb(r) into source from public.native_return_events r where r.id=original_source;
  if source is null or source->>'dispense_id' is distinct from did::text
  or source->>'record_hash' is distinct from target#>>'{document,source,record_hash}'
  or source->>'action'<>all(array['intake','dispose','restock']) then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  selected_ids:=array[e.id];if selected_case_id<>e.id then selected_ids:=selected_ids||selected_case_id;end if;
  foreach selected_id in array selected_ids loop
   role_name:=case when selected_id=e.id then 'reviewed_target' else 'case_report' end;
   select to_jsonb(r) into row_value from public.native_return_discrepancy_events r where r.id=selected_id;
   select to_jsonb(r) into operation from public.native_return_discrepancy_operations r where r.id=selected_id;
   select to_jsonb(r) into provenance from public.stock_discrepancy_sources r where r.event_id=selected_id;
   if row_value is null or operation is null or row_value->>'dispense_id' is distinct from did::text
   or operation->>'actor_id' is distinct from row_value->>'actor_id' or operation->'result' is distinct from row_value->'document'
   or row_value->>'record_hash' is distinct from public.native_fulfillment_hash((row_value->'document')-'record_hash')
   or row_value#>'{document,source}' is distinct from target#>'{document,source}'
   or row_value#>'{document,allocations}' is distinct from target#>'{document,allocations}'
   or(selected_id<>e.id and(row_value->>'action'<>'report' or(row_value->>'sequence')::integer>=(target->>'sequence')::integer)) then
    raise exception 'adapter_source_integrity' using errcode='23514';end if;
   managed:=controlled_review_v3.managed_source_event(jsonb_build_object('source_kind','discrepancy','source_id',selected_id,'product_id',e.product_id));
   if(provenance is null and managed is not null) or(provenance is not null and provenance->>'actor_id' is distinct from row_value->>'actor_id') then
    raise exception 'adapter_source_integrity' using errcode='23514';end if;
   -- Membership is validated above; these context-only roles declare no parent/physical edge.
   state:=controlled_review_v3.adapter_add(state,'public.native_return_discrepancy_events',jsonb_build_object('id',selected_id),row_value,role_name);
   state:=controlled_review_v3.adapter_add(state,'public.native_return_discrepancy_operations',jsonb_build_object('id',selected_id),operation,role_name);
   if provenance is not null then state:=controlled_review_v3.adapter_add(state,'public.stock_discrepancy_sources',jsonb_build_object('event_id',selected_id),provenance,role_name);end if;
  end loop;
  state:=controlled_review_v3.adapter_return(state,original_source,e.product_id,'ordinary_source',1);
  if jsonb_typeof(target#>'{document,correction_ids}') is distinct from 'array' then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  if jsonb_array_length(target#>'{document,correction_ids}')>100 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
  if target->>'action'='resolve_corrected' then
   if jsonb_array_length(target#>'{document,correction_ids}')=0 then raise exception 'adapter_source_integrity' using errcode='23514';end if;
   for row_value in select value from jsonb_array_elements(target#>'{document,correction_ids}') loop
    if jsonb_typeof(row_value)<>'string' or row_value#>>'{}'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or (row_value#>>'{}') collate "C"<=last_id collate "C" then raise exception 'adapter_source_integrity' using errcode='23514';end if;
    last_id:=row_value#>>'{}';selected_correction_id:=last_id::uuid;
    select * into correction from public.native_return_events where id=selected_correction_id;
    select * into link from public.native_return_discrepancy_correction_links l where l.correction_id=selected_correction_id;
    if correction.id is null or link.id is null or link.case_id<>selected_case_id or link.resolution_id<>e.id
    or correction.dispense_id<>did or correction.document->>'version'<>'2'
    or correction.action<>all(array['retract_intake','retract_disposal','retract_restock'])
    or correction.document#>'{correction_target}' is distinct from target#>'{document,source}'
    or correction.document->>'discrepancy_id' is distinct from selected_case_id::text then
     raise exception 'adapter_source_integrity' using errcode='23514';end if;
    n:=n+1;
    state:=controlled_review_v3.adapter_add(state,'public.native_return_discrepancy_correction_links',jsonb_build_object('id',link.id),to_jsonb(link),'reviewed_target');
    state:=controlled_review_v3.adapter_return(state,correction.id,e.product_id,'resolution_correction',1);
   end loop;
  elsif target#>'{document,correction_ids}'<>'[]'::jsonb then raise exception 'adapter_source_integrity' using errcode='23514';end if;
  select count(*) into count_links from(select id from public.native_return_discrepancy_correction_links where resolution_id=e.id limit 101) q;
  if count_links>100 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
  if count_links<>n then raise exception 'adapter_source_integrity' using errcode='23514';end if;
 else raise exception 'unsupported_event_kind' using errcode='22023';end if;
 return state;
end

controlled_review_v3.adapter_dispense(p_.source:
declare state jsonb:=p_state; d public.native_dispenses; op public.native_fulfillment_operations;
 item public.billing_invoice_items; a record; m public.inventory_movements; managed jsonb;
 n integer:=0; source_count integer; total numeric:=0; unit text;
begin
 if p_role is null or p_role<>all(array['reviewed_target','original_dispense']) then
  raise exception 'adapter_source_role_conflict' using errcode='23514';end if;
 if p_depth is null or p_depth<0 or p_depth>4 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
 select * into d from public.native_dispenses where id=p_dispense_id;
 select * into op from public.native_fulfillment_operations where id=p_dispense_id;
 select * into item from public.billing_invoice_items where id=d.invoice_item_id;
 select stock_unit into unit from public.controlled_stock_policy_versions where id=(select policy_version_id from public.controlled_stock_events where id=(state->>'target_event_id')::uuid);
 if d.id is null or op.id is null or item.id is null or op.operation<>'dispense' or op.actor_id<>d.actor_id
 or op.result->'dispense' is distinct from d.document or item.product_id<>p_product_id or item.quantity<>d.quantity
 or item.created_by<>d.actor_id or item.invoice_id<>d.invoice_id or item.pet_id is distinct from d.pet_id
 or d.document->>'unit' is distinct from unit or state->>'product_id' is distinct from p_product_id::text then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 managed:=controlled_review_v3.managed_source_event(jsonb_build_object('source_kind','dispense','source_id',d.id,'product_id',p_product_id));
 if managed is not null then state:=controlled_review_v3.adapter_parent(state,(managed->>'event_id')::uuid,p_role);end if;
 state:=controlled_review_v3.adapter_add(state,'public.native_dispenses',jsonb_build_object('id',d.id),to_jsonb(d),p_role);
 state:=controlled_review_v3.adapter_add(state,'public.native_fulfillment_operations',jsonb_build_object('id',op.id),to_jsonb(op),p_role);
 state:=controlled_review_v3.adapter_add(state,'public.billing_invoice_items',jsonb_build_object('id',item.id),to_jsonb(item),p_role);
 for a in select * from public.native_dispense_allocations where dispense_id=d.id order by lot_id limit 101 loop
  n:=n+1;if n>100 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
  select * into m from public.inventory_movements where id=a.movement_id;
  if m.id is null or m.lot_id<>a.lot_id or m.quantity<>-a.quantity or m.kind<>'dispense' then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  total:=total+a.quantity;
  state:=controlled_review_v3.adapter_add(state,'public.native_dispense_allocations',jsonb_build_object('id',a.id),to_jsonb(a),p_role);
  state:=controlled_review_v3.adapter_movement(state,a.movement_id,'record_native_dispense',d.id,d.actor_id,p_role,managed is not null);
 end loop;
 if n=0 or total<>d.quantity then raise exception 'adapter_source_integrity' using errcode='23514';end if;
 select count(*) into source_count from(select movement_id from public.stock_movement_sources where writer='record_native_dispense' and source_id=d.id limit 101) q;
 if source_count>100 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
 if source_count not in(0,n) or(managed is not null and source_count<>n)
 or exists(select 1 from public.stock_movement_sources s where writer='record_native_dispense' and source_id=d.id
  and not exists(select 1 from public.native_dispense_allocations allocation_row where allocation_row.dispense_id=d.id and allocation_row.movement_id=s.movement_id)) then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 return state;
end

controlled_review_v3.adapter_event_site(.source:
declare e public.controlled_stock_events; site uuid; unit text; r record; n integer:=0;
begin
 select * into e from public.controlled_stock_events where id=p_event_id;
 if e.id is null then raise exception 'adapter_parent_integrity' using errcode='23514';end if;
 select stock_unit into unit from public.controlled_stock_policy_versions where id=e.policy_version_id;
 for r in select c.controlling_site_id,c.product_id,c.stock_unit from public.controlled_stock_container_transitions t
  join public.controlled_stock_containers c on c.id=t.container_id where t.event_id=e.id order by t.container_id limit 513 loop
  n:=n+1;
  if n>512 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
  if r.product_id<>e.product_id or r.stock_unit is distinct from unit or(site is not null and site<>r.controlling_site_id) then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  site:=r.controlling_site_id;
 end loop;
 if e.basis in('physical_record','correction_assertion') and(site is null or not exists(select 1 from public.controlled_stock_event_lines where event_id=e.id)) then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 return jsonb_build_object('site_id',site);
end

controlled_review_v3.adapter_movement(p_.source:
declare state jsonb:=p_state; m public.inventory_movements; l public.inventory_lots;
 s public.stock_movement_sources; boundary public.controlled_stock_opening_movements;
begin
 select * into m from public.inventory_movements where id=p_movement_id;
 select * into l from public.inventory_lots where id=m.lot_id;
 select * into s from public.stock_movement_sources where movement_id=m.id;
 if m.id is null or l.id is null or l.product_id::text is distinct from state->>'product_id'
 or m.created_by is distinct from p_actor_id or p_managed is null then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 if s.movement_id is not null then
  if s.writer is distinct from p_source_writer or s.source_id is distinct from p_source_id or s.actor_id is distinct from p_actor_id then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  perform public.stock_source_validate_movement(m.id);
  state:=controlled_review_v3.adapter_add(state,'public.stock_movement_sources',jsonb_build_object('movement_id',s.movement_id),to_jsonb(s),p_role);
 elsif p_managed then raise exception 'adapter_source_integrity' using errcode='23514';end if;
 select * into boundary from public.controlled_stock_opening_movements where movement_id=m.id;
 if p_managed then
  if boundary.movement_id is not null or not exists(select 1 from public.controlled_stock_source_links where movement_id=m.id and event_id=p_source_id) then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
 else
  if boundary.movement_id is null or boundary.opening_id::text is distinct from state->>'opening_id'
  or boundary.source_snapshot is distinct from to_jsonb(m) or boundary.lot_id<>m.lot_id or boundary.quantity<>m.quantity
  or exists(select 1 from public.controlled_stock_source_links where movement_id=m.id) then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  state:=controlled_review_v3.adapter_add(state,'public.controlled_stock_opening_movements',
   jsonb_build_object('opening_id',boundary.opening_id,'movement_id',boundary.movement_id),to_jsonb(boundary),'opening_basis');
 end if;
 state:=controlled_review_v3.adapter_add(state,'public.inventory_movements',jsonb_build_object('id',m.id),to_jsonb(m),p_role);
 state:=controlled_review_v3.adapter_add(state,'public.inventory_lots',jsonb_build_object('id',l.id),to_jsonb(l),p_role);
 return state;
end

controlled_review_v3.adapter_opening_sit.source:
declare
 state jsonb:=p_state; target_event public.controlled_stock_events;
 target_correction public.native_dispense_correction_events; original_dispense public.native_dispenses;
 retained_opening public.controlled_stock_openings; selected_cell public.controlled_stock_cells;
 selected_container public.controlled_stock_containers; original_allocation record;
 entry jsonb; entry_candidate jsonb; projected jsonb; boundary_allocation jsonb;
 allocation_map jsonb:='{}'; prepared_sums jsonb:='{}'; retained_node jsonb;
 opening_container_map jsonb:='{}'; opening_container_ids jsonb;
 positive_sites jsonb:='{}'; zero_sites jsonb:='{}'; site_key text; retained_site uuid; selected_site uuid;
 opening_unit text; target_unit text; selected_pickup uuid;
 return_version integer; correction_version integer; discrepancy_version integer;
 entry_count integer:=0; allocation_count integer:=0; cell_count integer:=0;
 fully_prepared boolean:=true; reason text; expected_prepared numeric; actual_prepared numeric;
begin
 if p_dispense_id is null or p_product_id is null or jsonb_typeof(state) is distinct from 'object'
 or jsonb_typeof(state->'rows') is distinct from 'object' then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 if octet_length(state::text)>1048576 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
 select * into target_event from public.controlled_stock_events
 where id=public.controlled_stock_uuid(state->'target_event_id');
 select * into target_correction from public.native_dispense_correction_events where id=target_event.id;
 select * into original_dispense from public.native_dispenses where id=p_dispense_id;
 if target_event.id is null or target_event.writer is distinct from 'append_native_dispense_correction'
 or target_event.event_kind<>all(array['append_native_dispense_correction:clinical_annotation','append_native_dispense_correction:operational_annotation'])
 or target_event.product_id is distinct from p_product_id or state->>'product_id' is distinct from p_product_id::text
 or target_event.opening_id::text is distinct from state->>'opening_id'
 or target_correction.id is null or original_dispense.id is null
 or target_correction.dispense_id is distinct from p_dispense_id
 or target_correction.kind is distinct from split_part(target_event.event_kind,':',2)
 or target_correction.authorization_id is distinct from original_dispense.authorization_id
 or target_correction.pet_id is distinct from original_dispense.pet_id
 or target_correction.actor_id is distinct from target_event.actor_id then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 select * into retained_opening from public.controlled_stock_openings where id=target_event.opening_id;
 select stock_unit into opening_unit from public.controlled_stock_policy_versions
 where id=retained_opening.policy_version_id and product_id=p_product_id;
 select stock_unit into target_unit from public.controlled_stock_policy_versions
 where id=target_event.policy_version_id and product_id=p_product_id;
 if retained_opening.id is null or retained_opening.product_id is distinct from p_product_id
 or opening_unit is null or target_unit is distinct from opening_unit then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 if octet_length(retained_opening.native_custody_boundary::text)>1048576
 or jsonb_array_length(retained_opening.native_custody_boundary)>200 then
  raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
 -- The immutable parent keeps all its reciprocal, prefix and later-link checks.
 perform public.controlled_stock_validate_opening(retained_opening.id);
 if controlled_review_v3.managed_source_event(jsonb_build_object(
  'source_kind','dispense','source_id',p_dispense_id,'product_id',p_product_id)) is not null then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 -- This validates complete original allocations/provenance even for direct private
 -- helper calls; re-adding the existing rows obeys the unchanged role precedence.
 state:=controlled_review_v3.adapter_dispense(state,p_dispense_id,p_product_id,'original_dispense',1);
 for entry_candidate in select value from jsonb_array_elements(retained_opening.native_custody_boundary) loop
  if entry_candidate->>'dispense_id'=p_dispense_id::text then
   entry_count:=entry_count+1;entry:=entry_candidate;
  end if;
 end loop;
 if entry_count<>1 then raise exception 'adapter_source_integrity' using errcode='23514';end if;
 return_version:=public.controlled_stock_opening_selector(entry->'return_head');
 correction_version:=public.controlled_stock_opening_selector(entry->'correction_head');
 discrepancy_version:=public.controlled_stock_opening_selector(entry->'discrepancy_head');
 if entry->'pickup'<>'null'::jsonb then selected_pickup:=public.controlled_stock_uuid(entry#>'{pickup,id}');end if;
 projected:=public.controlled_stock_opening_native_entry(retained_opening.id,p_dispense_id,
  return_version,correction_version,discrepancy_version,selected_pickup);
 if entry is distinct from projected or target_correction.sequence<=correction_version
 or public.controlled_stock_opening_later_source(retained_opening.id,'correction',target_event.id) is distinct from target_event.id then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 if jsonb_array_length(entry->'allocations')>100 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
 fully_prepared:=return_version=0 and discrepancy_version=0 and selected_pickup is null
  and not exists(select 1 from public.native_dispense_correction_events prefix_correction
   where prefix_correction.dispense_id=p_dispense_id and prefix_correction.sequence<=correction_version
   and prefix_correction.kind<>all(array['clinical_annotation','operational_annotation']));
 for original_allocation in select * from public.native_dispense_allocations
 where dispense_id=p_dispense_id order by id limit 101 loop
  allocation_count:=allocation_count+1;
  if allocation_count>100 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
  select value into boundary_allocation from jsonb_array_elements(entry->'allocations')
   where value->>'allocation_id'=original_allocation.id::text;
  if boundary_allocation is null or boundary_allocation->>'lot_id' is distinct from original_allocation.lot_id::text
  or original_allocation.quantity<=0
  or (boundary_allocation->>'dispensed_quantity')::numeric is distinct from original_allocation.quantity then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  expected_prepared:=(boundary_allocation->>'prepared_quantity')::numeric;
  if expected_prepared is null or expected_prepared<0 then raise exception 'adapter_source_integrity' using errcode='23514';end if;
  if expected_prepared<>original_allocation.quantity or boundary_allocation->'held'<>'[]'::jsonb then fully_prepared:=false;end if;
  allocation_map:=allocation_map||jsonb_build_object(original_allocation.id::text,boundary_allocation);
 end loop;
 if allocation_count=0 or allocation_count<>jsonb_array_length(entry->'allocations') then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 -- Preserve assertion/managed cross-set agreement even when O is unsupported.
 for retained_node in select value from jsonb_each(state->'rows') loop
  if retained_node->>'relation'='public.controlled_stock_containers' then
   selected_site:=(retained_node#>>'{row,controlling_site_id}')::uuid;
   if selected_site is null or(retained_site is not null and retained_site<>selected_site) then
    raise exception 'adapter_source_integrity' using errcode='23514';end if;
   retained_site:=selected_site;
  end if;
 end loop;
 for selected_cell in select * from public.controlled_stock_cells
 where opening_id=retained_opening.id and dispense_id=p_dispense_id and channel='prepared'
 order by id limit 513 loop
  cell_count:=cell_count+1;if cell_count>512 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
  boundary_allocation:=allocation_map->selected_cell.allocation_id::text;
  select * into selected_container from public.controlled_stock_containers where id=selected_cell.container_id;
  if boundary_allocation is null or selected_cell.lot_id::text is distinct from boundary_allocation->>'lot_id'
  or selected_cell.intake_id is not null or selected_cell.created_event_id is not null or selected_cell.opening_quantity<0
  or selected_container.id is null or selected_container.opening_id is distinct from retained_opening.id
  or selected_container.product_id is distinct from p_product_id or selected_container.stock_unit is distinct from opening_unit
  or selected_container.kind is distinct from 'prepared' or selected_container.stock_lot_id is not null
  or selected_container.created_event_id is not null or selected_container.controlling_site_id is null then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  selected_site:=selected_container.controlling_site_id;
  if retained_site is not null and selected_site<>retained_site then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  state:=controlled_review_v3.adapter_add(state,'public.controlled_stock_cells',jsonb_build_object('id',selected_cell.id),to_jsonb(selected_cell),'opening_basis');
  state:=controlled_review_v3.adapter_add(state,'public.controlled_stock_containers',jsonb_build_object('id',selected_container.id),to_jsonb(selected_container),'opening_basis');
  -- Private same-phase canonical membership, never a role/authorization flag.
  opening_container_map:=opening_container_map||jsonb_build_object(selected_container.id::text,true);
  actual_prepared:=coalesce((prepared_sums->>selected_cell.allocation_id::text)::numeric,0)+selected_cell.opening_quantity;
  prepared_sums:=prepared_sums||jsonb_build_object(selected_cell.allocation_id::text,actual_prepared);
  if selected_cell.opening_quantity>0 then positive_sites:=positive_sites||jsonb_build_object(selected_site::text,true);
  else zero_sites:=zero_sites||jsonb_build_object(selected_site::text,true);end if;
 end loop;
 for boundary_allocation in select value from jsonb_each(allocation_map) loop
  actual_prepared:=coalesce((prepared_sums->>(boundary_allocation->>'allocation_id'))::numeric,0);
  if actual_prepared is distinct from (boundary_allocation->>'prepared_quantity')::numeric then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
 end loop;
 if positive_sites<>'{}'::jsonb then
  for site_key in select jsonb_object_keys(zero_sites) loop
   if not(positive_sites?site_key) then raise exception 'adapter_source_integrity' using errcode='23514';end if;
  end loop;
 end if;
 selected_site:=null;
 if not fully_prepared or positive_sites='{}'::jsonb then reason:='opening_package_incomplete';
 elsif(select count(*) from jsonb_object_keys(positive_sites))<>1 then reason:='opening_package_multisite';
 else select jsonb_object_keys(positive_sites)::uuid into selected_site;end if;
 select coalesce(jsonb_agg(selected_ids.key order by selected_ids.key collate "C"),'[]'::jsonb)into opening_container_ids
 from jsonb_object_keys(opening_container_map)as selected_ids(key);
 return jsonb_build_object('state',state,'site_id',selected_site,'reason',reason,'opening_container_ids',opening_container_ids);
end

controlled_review_v3.adapter_parent(p_st.source:
declare state jsonb:=p_state; e public.controlled_stock_events; r record; row_value jsonb;
begin
 if p_role is null or p_role<>all(array['reviewed_target','correction_target','ordinary_source','original_dispense','original_pickup']) then
  raise exception 'adapter_source_role_conflict' using errcode='23514';end if;
 select * into e from public.controlled_stock_events where id=p_event_id;
 if e.id is null or e.product_id::text is distinct from state->>'product_id'
 or e.opening_id::text is distinct from state->>'opening_id' then
  raise exception 'adapter_parent_integrity' using errcode='23514';end if;
 perform public.controlled_stock_validate_event(e.id);
 state:=controlled_review_v3.adapter_add(state,'public.controlled_stock_events',jsonb_build_object('id',e.id),to_jsonb(e),p_role);
 select to_jsonb(a) into row_value from public.controlled_stock_actions a where a.id=e.id;
 state:=controlled_review_v3.adapter_add(state,'public.controlled_stock_actions',jsonb_build_object('id',e.id),row_value,p_role);
 select to_jsonb(a) into row_value from public.controlled_stock_preparations a where a.id=e.id;
 state:=controlled_review_v3.adapter_add(state,'public.controlled_stock_preparations',jsonb_build_object('id',e.id),row_value,p_role);
 select to_jsonb(a) into row_value from public.controlled_stock_policy_versions a where a.id=e.policy_version_id;
 state:=controlled_review_v3.adapter_add(state,'public.controlled_stock_policy_versions',jsonb_build_object('id',e.policy_version_id),row_value,p_role);
 select to_jsonb(a) into row_value from public.controlled_stock_openings a where a.id=e.opening_id;
 state:=controlled_review_v3.adapter_add(state,'public.controlled_stock_openings',jsonb_build_object('id',e.opening_id),row_value,p_role);
 for r in select * from public.controlled_stock_source_links where event_id=e.id order by id limit 513 loop
  state:=controlled_review_v3.adapter_add(state,'public.controlled_stock_source_links',jsonb_build_object('id',r.id),to_jsonb(r),p_role);
 end loop;
 for r in select * from public.controlled_stock_event_lines where event_id=e.id order by cell_id,source_link_id limit 513 loop
  state:=controlled_review_v3.adapter_add(state,'public.controlled_stock_event_lines',jsonb_build_object('id',r.id),to_jsonb(r),p_role);
  select to_jsonb(c) into row_value from public.controlled_stock_cells c where c.id=r.cell_id;
  state:=controlled_review_v3.adapter_add(state,'public.controlled_stock_cells',jsonb_build_object('id',r.cell_id),row_value,p_role);
  select to_jsonb(c) into row_value from public.controlled_stock_containers c where c.id=(row_value->>'container_id')::uuid;
  state:=controlled_review_v3.adapter_add(state,'public.controlled_stock_containers',jsonb_build_object('id',row_value->'id'),row_value,p_role);
 end loop;
 for r in select * from public.controlled_stock_container_transitions where event_id=e.id order by container_id limit 513 loop
  state:=controlled_review_v3.adapter_add(state,'public.controlled_stock_container_transitions',jsonb_build_object('id',r.id),to_jsonb(r),p_role);
  select to_jsonb(c) into row_value from public.controlled_stock_containers c where c.id=r.container_id;
  state:=controlled_review_v3.adapter_add(state,'public.controlled_stock_containers',jsonb_build_object('id',r.container_id),row_value,p_role);
 end loop;
 return state;
end

controlled_review_v3.adapter_pickup(p_st.source:
declare state jsonb:=p_state; p public.native_pickups; op public.native_fulfillment_operations;
 provenance public.stock_pickup_sources; managed jsonb;
begin
 if p_role is null or p_role<>all(array['reviewed_target','original_pickup']) then
  raise exception 'adapter_source_role_conflict' using errcode='23514';end if;
 if p_depth is null or p_depth<0 or p_depth>4 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
 select * into p from public.native_pickups where id=p_pickup_id;
 select * into op from public.native_fulfillment_operations where id=p_pickup_id;
 select * into provenance from public.stock_pickup_sources where event_id=p_pickup_id;
 if p.id is null or op.id is null or op.operation<>'pickup' or op.actor_id<>p.actor_id or op.result is distinct from p.document then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 managed:=controlled_review_v3.managed_source_event(jsonb_build_object('source_kind','pickup','source_id',p.id,'product_id',p_product_id));
 if managed is not null then state:=controlled_review_v3.adapter_parent(state,(managed->>'event_id')::uuid,p_role);end if;
 if provenance.event_id is null and managed is not null then raise exception 'adapter_source_integrity' using errcode='23514';end if;
 if provenance.event_id is not null then
  if provenance.actor_id<>p.actor_id then raise exception 'adapter_source_integrity' using errcode='23514';end if;
  state:=controlled_review_v3.adapter_add(state,'public.stock_pickup_sources',jsonb_build_object('event_id',p.id),to_jsonb(provenance),p_role);
 end if;
 state:=controlled_review_v3.adapter_add(state,'public.native_pickups',jsonb_build_object('id',p.id),to_jsonb(p),p_role);
 state:=controlled_review_v3.adapter_add(state,'public.native_fulfillment_operations',jsonb_build_object('id',op.id),to_jsonb(op),p_role);
 state:=controlled_review_v3.adapter_dispense(state,p.dispense_id,p_product_id,'original_dispense',p_depth+1);
 return state;
end

controlled_review_v3.adapter_return(p_st.source:
declare state jsonb:=p_state; r public.native_return_events; op public.native_return_operations;
 provenance public.stock_custody_sources; original public.native_return_events;
 stock public.native_return_stock_links; movement public.inventory_movements; a public.native_dispense_allocations;
 x record; managed jsonb; source_writer text; n integer:=0; source_count integer; target_id uuid;
begin
 if p_role is null or p_role<>all(array['reviewed_target','correction_target','ordinary_source','original_intake','resolution_correction']) then
  raise exception 'adapter_source_role_conflict' using errcode='23514';end if;
 if p_depth is null or p_depth<0 or p_depth>4 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
 select * into r from public.native_return_events where id=p_return_id;
 select * into op from public.native_return_operations where id=p_return_id;
 select * into provenance from public.stock_custody_sources where event_id=p_return_id;
 source_writer:=case r.document->>'version' when '1' then 'record_native_dispense_return' when '2' then 'record_native_dispense_return_v2' end;
 if r.id is null or op.id is null or source_writer is null or op.actor_id<>r.actor_id or op.result is distinct from r.document
 or r.document->>'record_hash' is distinct from r.record_hash or public.native_fulfillment_hash(r.document-'record_hash') is distinct from r.record_hash then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 managed:=controlled_review_v3.managed_source_event(jsonb_build_object('source_kind','return','source_id',r.id,'product_id',p_product_id));
 -- Only these return roles declare parent/physical reference edges.
 if managed is not null and p_role in('reviewed_target','correction_target','ordinary_source') then
  state:=controlled_review_v3.adapter_parent(state,(managed->>'event_id')::uuid,p_role);end if;
 if provenance.event_id is null and managed is not null then raise exception 'adapter_source_integrity' using errcode='23514';end if;
 if provenance.event_id is not null then
  if provenance.actor_id<>r.actor_id or provenance.writer<>source_writer then raise exception 'adapter_source_integrity' using errcode='23514';end if;
  state:=controlled_review_v3.adapter_add(state,'public.stock_custody_sources',jsonb_build_object('event_id',r.id),to_jsonb(provenance),p_role);
 end if;
 state:=controlled_review_v3.adapter_add(state,'public.native_return_events',jsonb_build_object('id',r.id),to_jsonb(r),p_role);
 state:=controlled_review_v3.adapter_add(state,'public.native_return_operations',jsonb_build_object('id',op.id),to_jsonb(op),p_role);
 state:=controlled_review_v3.adapter_dispense(state,r.dispense_id,p_product_id,'original_dispense',p_depth+1);
 if r.intake_id is not null then
  select * into original from public.native_return_events where id=r.intake_id;
  if original.id is null or original.id=r.id or original.action<>'intake' or original.dispense_id<>r.dispense_id or original.sequence>=r.sequence then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  state:=controlled_review_v3.adapter_return(state,original.id,p_product_id,'original_intake',p_depth+1);
 end if;
 if r.action in('retract_intake','retract_disposal','retract_restock') then
  target_id:=(r.document#>>'{correction_target,event_id}')::uuid;
  select * into original from public.native_return_events where id=target_id;
  if original.id is null or original.id=r.id or original.dispense_id<>r.dispense_id or original.sequence>=r.sequence
  or original.record_hash is distinct from r.document#>>'{correction_target,record_hash}'
  or original.action is distinct from(case r.action when 'retract_intake' then 'intake' when 'retract_disposal' then 'dispose' else 'restock' end)
  or controlled_review_v3.managed_source_event(jsonb_build_object('source_kind','return','source_id',target_id,'product_id',p_product_id)) is null then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  state:=controlled_review_v3.adapter_return(state,target_id,p_product_id,'correction_target',p_depth+1);
 end if;
 if r.action='restock' then
  for x in select * from public.native_return_stock_links where event_id=r.id order by allocation_id limit 101 loop
   n:=n+1;if n>100 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
   select * into a from public.native_dispense_allocations where id=x.allocation_id;
   select * into movement from public.inventory_movements where id=x.movement_id;
   if a.id is null or movement.id is null or a.dispense_id<>r.dispense_id or a.lot_id<>x.lot_id or movement.lot_id<>x.lot_id or movement.quantity<>x.quantity
   or not exists(select 1 from jsonb_array_elements(r.document->'allocations') d where d->>'allocation_id'=x.allocation_id::text
    and d->>'movement_id'=x.movement_id::text and(d->>'quantity')::numeric=x.quantity and d->>'lot_id'=x.lot_id::text) then
    raise exception 'adapter_source_integrity' using errcode='23514';end if;
   state:=controlled_review_v3.adapter_add(state,'public.native_return_stock_links',jsonb_build_object('id',x.id),to_jsonb(x),p_role);
   state:=controlled_review_v3.adapter_movement(state,x.movement_id,source_writer,r.id,r.actor_id,p_role,managed is not null);
  end loop;
 elsif r.action='retract_restock' then
  for x in select * from public.native_return_compensation_links where event_id=r.id order by allocation_id limit 101 loop
   n:=n+1;if n>100 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
   select * into stock from public.native_return_stock_links where event_id=target_id and allocation_id=x.allocation_id;
   select * into movement from public.inventory_movements where id=x.movement_id;
   if stock.id is null or movement.id is null or x.target_event_id<>target_id or x.original_movement_id<>stock.movement_id or x.lot_id<>stock.lot_id
   or movement.lot_id<>x.lot_id or movement.quantity<>-x.quantity
   or not exists(select 1 from jsonb_array_elements(r.document->'allocations') d where d->>'allocation_id'=x.allocation_id::text
    and d->>'movement_id'=x.movement_id::text and(d->>'quantity')::numeric=x.quantity and d->>'lot_id'=x.lot_id::text) then
    raise exception 'adapter_source_integrity' using errcode='23514';end if;
   state:=controlled_review_v3.adapter_add(state,'public.native_return_compensation_links',jsonb_build_object('id',x.id),to_jsonb(x),p_role);
   state:=controlled_review_v3.adapter_add(state,'public.native_return_stock_links',jsonb_build_object('id',stock.id),to_jsonb(stock),'correction_target');
   -- adapter_return(target) already retained/checked the original positive movement.
   -- Its exact stock link above binds original_movement_id; retain the distinct negative movement now.
   state:=controlled_review_v3.adapter_movement(state,x.movement_id,source_writer,r.id,r.actor_id,p_role,managed is not null);
  end loop;
 end if;
 if r.action in('restock','retract_restock') and(n=0 or n<>jsonb_array_length(r.document->'allocations')) then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
