controlled_review_v3.ops_overdue_record(.source:
declare evidence_value jsonb;stamp timestamptz;due_value timestamptz;row_value jsonb;field text;
begin
 if jsonb_typeof(p_row)is distinct from 'object'or octet_length(p_row::text)>131072 then raise exception 'review_overdue_record_invalid'using errcode='23514';end if;
 perform public.controlled_stock_keys(p_row,array['id','event_id','reason','routing_snapshot','first_detected_at','evidence','record_hash']);
 perform public.controlled_stock_uuid(p_row->'id');perform public.controlled_stock_uuid(p_row->'event_id');
 if p_row->'reason'is distinct from '"overdue"'::jsonb or jsonb_typeof(p_row->'first_detected_at')is distinct from 'string'then raise exception 'review_overdue_record_invalid'using errcode='23514';end if;
 stamp:=(p_row->>'first_detected_at')::timestamptz;perform controlled_review_v3.protocol_utc(stamp);
 evidence_value:=p_row->'evidence';perform public.controlled_stock_keys(evidence_value,array['version','reason','event_id','target_hash','due_at','detected_at','terminal_operation_id','terminal_receipt_hash','maintenance_operation_id']);
 if evidence_value->'version'is distinct from '1'::jsonb or evidence_value->'reason'is distinct from '"overdue"'::jsonb
  or evidence_value->'event_id'is distinct from p_row->'event_id'then raise exception 'review_overdue_record_invalid'using errcode='23514';end if;
 due_value:=controlled_review_v3.protocol_instant(evidence_value->'due_at');
 if controlled_review_v3.protocol_instant(evidence_value->'detected_at')is distinct from stamp or stamp<=due_value then raise exception 'review_overdue_record_invalid'using errcode='23514';end if;
 if jsonb_typeof(evidence_value->'target_hash')is distinct from 'string'or(evidence_value->>'target_hash')!~'^[0-9a-f]{64}$'then raise exception 'review_overdue_record_invalid'using errcode='23514';end if;
 if evidence_value->'terminal_operation_id'='null'::jsonb then
  if evidence_value->'terminal_receipt_hash'is distinct from 'null'::jsonb then raise exception 'review_overdue_record_invalid'using errcode='23514';end if;
 else
  perform public.controlled_stock_uuid(evidence_value->'terminal_operation_id');
  if jsonb_typeof(evidence_value->'terminal_receipt_hash')is distinct from 'string'or(evidence_value->>'terminal_receipt_hash')!~'^[0-9a-f]{64}$'then raise exception 'review_overdue_record_invalid'using errcode='23514';end if;
 end if;
 perform controlled_review_v3.protocol_validate_rejection_routing(p_row->'routing_snapshot',p_row#>'{routing_snapshot,historical}',stamp);
 if evidence_value->'terminal_operation_id'='null'::jsonb then
  perform public.controlled_stock_uuid(evidence_value->'maintenance_operation_id');
 else
  if evidence_value->'maintenance_operation_id'is distinct from 'null'::jsonb then raise exception 'review_overdue_record_invalid'using errcode='23514';end if;
 end if;
 row_value:=jsonb_build_object('id',p_row->'id','event_id',p_row->'event_id','reason','overdue','routing_snapshot',p_row->'routing_snapshot',
  'first_detected_at',controlled_review_v3.protocol_utc(stamp),'evidence',evidence_value);
 if jsonb_typeof(p_row->'record_hash')is distinct from 'string'or p_row->>'record_hash'is distinct from public.controlled_stock_hash(row_value)then raise exception 'review_overdue_record_invalid'using errcode='23514';end if;
 return row_value||jsonb_build_object('record_hash',p_row->'record_hash');
exception when invalid_text_representation or datetime_field_overflow then raise exception 'review_overdue_record_invalid'using errcode='23514';
end

controlled_review_v3.ops_publication_rea.source:
declare request_value jsonb:=controlled_review_v3.protocol_operation_request(p_request);actor_value uuid;operation_value uuid;
 publication_value controlled_review_v3.publications;record_value jsonb;result_value jsonb;keys_value jsonb;
begin
 actor_value:=(request_value->>'actor_id')::uuid;operation_value:=(request_value->>'operation_id')::uuid;
 perform controlled_review_v3.ops_admin_preflight();perform controlled_review_v3.read_prelude(actor_value);
 keys_value:=jsonb_build_array(jsonb_build_object('class_id',90271101,'key','review-v3-publication-operation:'||operation_value::text,'mode','exclusive'));
 perform controlled_review_v3.protocol_acquire_advisory(keys_value,actor_value);
 perform controlled_review_v3.ops_admin_read_tail(actor_value);
 select *into publication_value from controlled_review_v3.publications where operation_id=operation_value;
 if not found or publication_value.actor_id is distinct from actor_value then
  result_value:=jsonb_build_object('version',3,'state','not_found','data',jsonb_build_object('operation_id',operation_value));
 else
  record_value:=controlled_review_v3.protocol_validate_publication_record(publication_value.record_id);
  if record_value->>'publication_operation_id'is distinct from operation_value::text then raise exception 'review_history_integrity'using errcode='23514';end if;
  result_value:=jsonb_build_object('version',3,'state','published','data',jsonb_build_object('operation_id',operation_value,'record',record_value,'receipt',publication_value.receipt));
 end if;
 -- Recovery is owned, before CURRENT administration entitlement, but never
 -- before actual identity/session and both installation seal checks.
 perform controlled_review_v3.required();perform controlled_review_v3.protocol_identity(actor_value);
 return result_value;
end

controlled_review_v3.ops_read_history(p_.source:
declare event_value uuid:=(p_base#>>'{target,event_id}')::uuid;d controlled_review_v3.decisions;p controlled_review_v3.preparations;c controlled_review_v3.operation_claims;
 receipt_value jsonb;terminal_value jsonb;escalations_value jsonb:='[]'::jsonb;x controlled_review_v3.escalations;row_value jsonb;n integer:=0;
 has_rejected boolean:=false;has_overdue boolean:=false;ack_value boolean;resolution_value boolean;obligation_value jsonb:=p_base->'obligation';
begin
 select *into d from controlled_review_v3.decisions where event_id=event_value;
 if found then
  select *into p from controlled_review_v3.preparations where operation_id=d.operation_id;
  select *into c from controlled_review_v3.operation_claims where operation_id=d.operation_id;
  if p.operation_id is null or c.operation_id is null or c.actor_id<>p.actor_id or d.actor_id<>p.actor_id
   or d.event_id<>p.event_id or c.claimed_at>p.created_at or exists(select 1 from controlled_review_v3.cancellations where operation_id=d.operation_id)then raise exception 'review_history_integrity'using errcode='23514';end if;
  perform controlled_review_v3.read_validate_retained_packet(to_jsonb(p),p_base);
  receipt_value:=controlled_review_v3.protocol_receipt_from_rows(to_jsonb(p),to_jsonb(d));
  if receipt_value is distinct from d.receipt then raise exception 'review_history_integrity'using errcode='23514';end if;
  terminal_value:=jsonb_build_object('decision',d.decision,'meaning',receipt_value->'meaning','meaning_text',receipt_value->'meaning_text','meaning_version',receipt_value->'meaning_version',
   'actor_id',d.actor_id,'actor_name',d.actor_name,'recorded_at',receipt_value->'recorded_at','reason',d.reason,'receipt_hash',public.controlled_stock_hash(receipt_value),'target_hash',d.target_hash,'packet_hash',d.packet_hash);
 end if;
 for x in select *from controlled_review_v3.escalations where event_id=event_value order by reason collate "C" limit 7 loop
  n:=n+1;if n>6 then raise exception 'review_history_integrity'using errcode='23514';end if;
  row_value:=controlled_review_v3.ops_escalation_record(to_jsonb(x));
  if x.routing_snapshot->'historical'is distinct from obligation_value#>'{historical,routing_snapshot}'then raise exception 'review_history_integrity'using errcode='23514';end if;
  if x.reason='rejected'then
   has_rejected:=true;
   if d.operation_id is null or d.decision<>'reject'or x.id::text is distinct from controlled_review_v3.protocol_escalation_ids(d.operation_id,d.event_id)->>'rejected'
    or x.first_detected_at is distinct from d.recorded_at or x.evidence is distinct from controlled_review_v3.protocol_rejection_evidence(to_jsonb(p),to_jsonb(d))then raise exception 'review_history_integrity'using errcode='23514';end if;
  elsif x.reason='overdue'then
   has_overdue:=true;
   if obligation_value is null or obligation_value='null'::jsonb or x.evidence->'target_hash'is distinct from obligation_value->'target_hash'
    or x.evidence->'due_at'is distinct from obligation_value->'due_at'then raise exception 'review_history_integrity'using errcode='23514';end if;
   if x.evidence->'terminal_operation_id'<>'null'::jsonb then
    if d.operation_id is null or receipt_value->>'deadline_state'<>'completed_late'or x.evidence->>'terminal_operation_id'is distinct from d.operation_id::text
     or x.first_detected_at is distinct from d.recorded_at or x.evidence->>'terminal_receipt_hash'is distinct from public.controlled_stock_hash(receipt_value)
     or x.id::text is distinct from controlled_review_v3.protocol_escalation_ids(d.operation_id,event_value)->>'overdue'then raise exception 'review_history_integrity'using errcode='23514';end if;
   else
    perform controlled_review_v3.ops_validate_worker_escalation(row_value);
   end if;
  else
   perform controlled_review_v3.ops_validate_worker_escalation(row_value);
   perform controlled_review_v3.ops_validate_worker_assessment(row_value#>'{evidence,assessment}',p_base);
  end if;
  -- The explicit v3-only(escalation_id,kind,operation_id)index permits exact
  -- bounded existence probes without scanning unlimited other-kind comments.
  select exists(select 1 from controlled_review_v3.escalation_actions a where a.escalation_id=x.id and a.kind='acknowledge'),
   exists(select 1 from controlled_review_v3.escalation_actions a where a.escalation_id=x.id and a.kind='resolution_note')into ack_value,resolution_value;
  escalations_value:=escalations_value||jsonb_build_array(jsonb_build_object('reason',x.reason,'first_detected_at',controlled_review_v3.protocol_utc(x.first_detected_at),
   'has_acknowledgment',ack_value,'has_resolution_note',resolution_value));
 end loop;
 if(d.operation_id is not null and d.decision='reject')is distinct from has_rejected
  or(d.operation_id is not null and receipt_value->>'deadline_state'='completed_late'and not has_overdue)then raise exception 'review_history_integrity'using errcode='23514';end if;
 if p_base#>'{event,secondary_review_required}'='false'::jsonb and(terminal_value is not null or n<>0)then raise exception 'review_history_integrity'using errcode='23514';end if;
 return jsonb_build_object('terminal_review',terminal_value,'escalations',escalations_value);
end

controlled_review_v3.ops_record_scan(p_r.source:
declare request_value jsonb;row_value controlled_review_v3.scan_receipts;
begin
 if octet_length(p_request::text)>8192 then raise exception 'review_request_invalid'using errcode='23514';end if;
 request_value:=controlled_review_v3.protocol_validate_wire(p_request,'record_scan');perform controlled_review_v3.ops_worker_prelude();
 select *into row_value from controlled_review_v3.scan_receipts where operation_id=(request_value->>'operation_id')::uuid;
 if found then
  perform controlled_review_v3.ops_scan_record(to_jsonb(row_value));
  if row_value.result->>'request_hash'is distinct from public.controlled_stock_hash(request_value)then raise exception 'review_operation_mismatch'using errcode='PT409';end if;
  return row_value.result;
 end if;
 perform controlled_review_v3.ops_worker_enter('scan',request_value);
 -- Concurrent same-operation winner: exact recovery before current checkpoint.
 select *into row_value from controlled_review_v3.scan_receipts where operation_id=(request_value->>'operation_id')::uuid;
 if found then
  perform controlled_review_v3.ops_scan_record(to_jsonb(row_value));
  if row_value.result->>'request_hash'is distinct from public.controlled_stock_hash(request_value)then raise exception 'review_operation_mismatch'using errcode='PT409';end if;
  return row_value.result;
 end if;
 perform controlled_review_v3.protocol_acquire_relation_tail('scan','[]','[]',null);
 insert into controlled_review_v3.scan_receipts(operation_id,product_id,from_sequence,through_sequence,high_water,recorded_at,result)
 values((request_value->>'operation_id')::uuid,(request_value->>'product_id')::uuid,(request_value->>'from_sequence')::bigint,
  (request_value->>'through_sequence')::bigint,(request_value->>'high_water')::bigint,null,null)returning *into row_value;
 perform controlled_review_v3.required();perform controlled_review_v3.protocol_principal(null);return row_value.result;
end

controlled_review_v3.ops_reserved_escala.source:
declare ids_value jsonb:=controlled_review_v3.protocol_escalation_ids(p_operation_id,p_event_id);s controlled_review_v3.escalations;keys_value jsonb;
begin
 keys_value:=jsonb_build_array(jsonb_build_object('class_id',90271105,'key','review-v3-unique:escalations:'||(ids_value->>'rejected'),'mode','exclusive'),
  jsonb_build_object('class_id',90271105,'key','review-v3-unique:escalations:'||(ids_value->>'overdue'),'mode','exclusive'));
 perform controlled_review_v3.protocol_assert_advisory(keys_value);
 for s in select *from controlled_review_v3.escalations where id in((ids_value->>'rejected')::uuid,(ids_value->>'overdue')::uuid)loop
  -- A prior valid worker detection for this SAME event/reason is reusable,
  -- even if maintenance and review independently chose the same logical UUID.
  -- Every mismatched occupied reserved UUID still refuses under class105.
  if s.id::text is distinct from ids_value->>'overdue'or s.event_id<>p_event_id or s.reason<>'overdue'then raise exception 'review_unique_uuid_collision'using errcode='23514';end if;
  perform controlled_review_v3.ops_validate_overdue(to_jsonb(s));
 end loop;
end

controlled_review_v3.ops_scan_record(p_r.source:
declare r controlled_review_v3.scan_receipts:=jsonb_populate_record(null::controlled_review_v3.scan_receipts,p_row);request_value jsonb;item jsonb;prior bigint;required_value integer:=0;
begin
 perform public.controlled_stock_keys(p_row,array['operation_id','product_id','from_sequence','through_sequence','high_water','recorded_at','result']);
 request_value:=controlled_review_v3.protocol_validate_wire(jsonb_build_object('operation_id',r.operation_id,'product_id',r.product_id,
  'from_sequence',r.from_sequence::text,'through_sequence',r.through_sequence::text,'high_water',r.high_water::text),'record_scan');
 if r.through_sequence<=r.from_sequence then raise exception 'review_scan_empty_range'using errcode='23514';end if;
 perform public.controlled_stock_keys(r.result,array['version','operation_id','product_id','from_sequence','through_sequence','high_water','recorded_at','request_hash','examined','required','not_required','witnesses']);
 if r.result->'version'is distinct from '1'::jsonb or r.result-array['version','request_hash','examined','required','not_required','witnesses']is distinct from request_value||jsonb_build_object('recorded_at',controlled_review_v3.protocol_utc(r.recorded_at))
 or r.result->>'request_hash'is distinct from public.controlled_stock_hash(request_value)
 or jsonb_typeof(r.result->'witnesses')is distinct from 'array'or jsonb_array_length(r.result->'witnesses')not between 1 and 100
 or octet_length(r.result::text)>65536 then raise exception 'review_scan_history_invalid'using errcode='23514';end if;
 prior:=r.from_sequence;
 for item in select value from jsonb_array_elements(r.result->'witnesses')loop
  perform public.controlled_stock_keys(item,array['event_id','event_sequence','materialization_operation_id','materialization_hash','state']);
  perform public.controlled_stock_uuid(item->'event_id');perform public.controlled_stock_uuid(item->'materialization_operation_id');if jsonb_typeof(item->'materialization_hash')is distinct from 'string'or(item->>'materialization_hash')!~'^[0-9a-f]{64}$'then raise exception 'review_scan_history_invalid'using errcode='23514';end if;
  if controlled_review_v3.protocol_bigint_wire(item->'event_sequence')<=prior or(item->>'event_sequence')::bigint>r.through_sequence
   or item->>'state'not in('required','not_required')or item->>'state'is null then raise exception 'review_scan_history_invalid'using errcode='23514';end if;
  prior:=(item->>'event_sequence')::bigint;if item->>'state'='required'then required_value:=required_value+1;end if;
 end loop;
 if prior<>r.through_sequence or r.result->'examined'is distinct from to_jsonb(jsonb_array_length(r.result->'witnesses'))
 or r.result->'required'is distinct from to_jsonb(required_value)or r.result->'not_required'is distinct from to_jsonb(jsonb_array_length(r.result->'witnesses')-required_value)then
  raise exception 'review_scan_history_invalid'using errcode='23514';end if;
 return r.result;
end

controlled_review_v3.ops_scan_witnesses(.source:
declare request_value jsonb:=controlled_review_v3.protocol_validate_wire(p_request,'record_scan');
 product_value uuid:=(request_value->>'product_id')::uuid;from_value bigint;through_value bigint;high_value bigint;checkpoint bigint;
 e public.controlled_stock_events;m controlled_review_v3.materializations;witnesses jsonb:='[]';n integer:=0;required_value integer:=0;
begin
 from_value:=(request_value->>'from_sequence')::bigint;through_value:=(request_value->>'through_sequence')::bigint;high_value:=(request_value->>'high_water')::bigint;
 if through_value<=from_value then raise exception 'review_scan_empty_range'using errcode='23514';end if;
 select through_sequence into checkpoint from controlled_review_v3.scan_receipts where product_id=product_value order by through_sequence desc limit 1;
 if coalesce(checkpoint,0)<>from_value then raise exception 'review_scan_checkpoint_changed'using errcode='PT409';end if;
 if not exists(select 1 from public.controlled_stock_events where product_id=product_value and sequence=through_value)
 or not exists(select 1 from public.controlled_stock_events where product_id=product_value and sequence=high_value)then
  raise exception 'review_scan_endpoint_invalid'using errcode='23514';end if;
 for e in select *from public.controlled_stock_events where product_id=product_value and sequence>from_value and sequence<=through_value order by sequence limit 101 loop
  n:=n+1;if n>100 then raise exception 'review_scan_limit_exceeded'using errcode='54000';end if;
  select *into m from controlled_review_v3.materializations where product_id=product_value and event_id=e.id order by operation_id limit 1;
  if not found then raise exception 'review_scan_materialization_missing'using errcode='23514';end if;
  perform controlled_review_v3.ops_materialization_record(to_jsonb(m));
  if m.result->'target_hash'is distinct from to_jsonb(public.controlled_stock_hash(jsonb_build_object('event_id',e.id,'product_id',e.product_id,
   'sequence',e.sequence,'record_hash',e.record_hash,'original_actor_id',e.actor_id,'policy_version_id',e.policy_version_id,'opening_id',e.opening_id,'engine_revision',e.engine_revision)))then
   raise exception 'review_scan_materialization_mismatch'using errcode='23514';end if;
  if e.secondary_review_required then
   if m.result->>'state'<>'required'or m.result->'obligation_hash'is distinct from controlled_review_v3.protocol_obligation_dto(e.id)->'binding_hash'then
    raise exception 'review_scan_obligation_mismatch'using errcode='23514';end if;
   required_value:=required_value+1;
  elsif m.result->>'state'<>'not_required'or exists(select 1 from controlled_review_v3.obligations where event_id=e.id)then
   raise exception 'review_scan_not_required_mismatch'using errcode='23514';end if;
  witnesses:=witnesses||jsonb_build_array(jsonb_build_object('event_id',e.id,'event_sequence',e.sequence::text,'materialization_operation_id',m.operation_id,
   'materialization_hash',public.controlled_stock_hash(m.result),'state',m.result->'state'));
 end loop;
 if n=0 then raise exception 'review_scan_empty_range'using errcode='23514';end if;
 return jsonb_build_object('examined',n,'required',required_value,'not_required',n-required_value,'witnesses',witnesses);
end

controlled_review_v3.ops_terminal_action.source:
begin
 if TG_OP<>'INSERT'or TG_TABLE_SCHEMA<>'controlled_review_v3'or TG_TABLE_NAME<>'escalation_actions'then raise exception 'review_insert_invalid'using errcode='23514';end if;
 perform controlled_review_v3.required();perform controlled_review_v3.ops_validate_action(to_jsonb(NEW));return null;
end

controlled_review_v3.ops_terminal_worker.source:
begin
 if TG_OP<>'INSERT'or TG_TABLE_SCHEMA<>'controlled_review_v3'or TG_TABLE_NAME not in('materializations','scan_receipts')then raise exception 'review_insert_invalid'using errcode='23514';end if;
 perform controlled_review_v3.required();
 if TG_TABLE_NAME='materializations'then perform controlled_review_v3.ops_validate_materialization(to_jsonb(NEW));
 else perform controlled_review_v3.ops_validate_scan(to_jsonb(NEW));end if;
 return null;
end

controlled_review_v3.ops_validate_action.source:
declare row_value jsonb:=controlled_review_v3.ops_action_record(p_row);receipt_value jsonb:=row_value->'receipt';escalation_value controlled_review_v3.escalations;obligation_value controlled_review_v3.obligations;administration_value jsonb;member_value jsonb;
begin
 select *into strict escalation_value from controlled_review_v3.escalations where id=(row_value->>'escalation_id')::uuid;
 select *into strict obligation_value from controlled_review_v3.obligations where event_id=escalation_value.event_id;
 perform controlled_review_v3.ops_escalation_record(to_jsonb(escalation_value));
 administration_value:=controlled_review_v3.protocol_validate_publication_record((receipt_value->>'administration_id')::uuid);
 select value into member_value from jsonb_array_elements(administration_value#>'{body,members}')where value->'actor_id'=row_value->'actor_id';
 if receipt_value->>'escalation_hash'is distinct from escalation_value.record_hash or administration_value->>'kind'<>'administration'
  or administration_value->'enabled'is distinct from 'true'::jsonb or administration_value#>>'{scope,product_id}'is distinct from obligation_value.product_id::text
  or administration_value->>'record_hash'is distinct from receipt_value->>'administration_hash'or member_value is null
  or not(member_value->'capabilities'?'manage_escalation')or member_value->'roles'is distinct from receipt_value->'configured_roles'
  or(administration_value->>'published_at')::timestamptz>(row_value->>'recorded_at')::timestamptz
  or(row_value->>'recorded_at')::timestamptz<escalation_value.first_detected_at then raise exception 'review_action_history_invalid'using errcode='23514';end if;
 -- Historical roles/session/name are retained at recording; do not reauthorize
 -- against today's rosters/profiles/Auth state in a deferred/restore check.
end

controlled_review_v3.ops_validate_materi.source:
declare result_value jsonb:=controlled_review_v3.ops_materialization_record(p_row);e public.controlled_stock_events;o jsonb;item jsonb;s controlled_review_v3.escalations;base_value jsonb;family_value jsonb;
begin
 select *into strict e from public.controlled_stock_events where id=(result_value->>'event_id')::uuid;
 if e.product_id::text is distinct from result_value->>'product_id'or result_value->>'target_hash'is distinct from public.controlled_stock_hash(jsonb_build_object('event_id',e.id,'product_id',e.product_id,'sequence',e.sequence,
  'record_hash',e.record_hash,'original_actor_id',e.actor_id,'policy_version_id',e.policy_version_id,'opening_id',e.opening_id,'engine_revision',e.engine_revision))then raise exception 'review_materialization_history_invalid'using errcode='23514';end if;
 o:=controlled_review_v3.protocol_obligation_dto(e.id);
 perform controlled_review_v3.read_clinical_dependencies_required();
 base_value:=controlled_review_v3.ops_worker_projection(controlled_review_v3.ops_worker_collect(e.id));
 if result_value#>'{availability,provenance_state}'is distinct from base_value#>'{adapter,provenance_state}'then raise exception 'review_materialization_history_invalid'using errcode='23514';end if;
 if e.secondary_review_required then
  if result_value->>'state'<>'required'or o is null or result_value->'obligation_hash'is distinct from o->'binding_hash'then raise exception 'review_materialization_history_invalid'using errcode='23514';end if;
  if result_value->'family_hash'is distinct from o#>'{historical,family_binding_hash}'or result_value->'availability'is distinct from jsonb_build_object('provenance_state',o#>'{adapter,provenance_state}','deadline_basis',o#>'{historical,deadline_basis}','unavailable_reason',o#>'{historical,unavailable_reason}')then raise exception 'review_materialization_history_invalid'using errcode='23514';end if;
  if o->'family_dispense_id'<>'null'::jsonb then
   family_value:=controlled_review_v3.protocol_family_dto((o->>'family_dispense_id')::uuid);
   if family_value is null or family_value->'binding_hash'is distinct from result_value->'family_hash'then raise exception 'review_materialization_history_invalid'using errcode='23514';end if;
  end if;
  perform controlled_review_v3.ops_validate_worker_assessment(result_value->'assessment',base_value);
 elsif result_value->>'state'<>'not_required'or o is not null then raise exception 'review_materialization_history_invalid'using errcode='23514';end if;
 for item in select value from jsonb_array_elements(result_value->'escalations')loop
  select *into strict s from controlled_review_v3.escalations where id=(item->>'id')::uuid;
  if s.event_id<>e.id or s.reason is distinct from item->>'reason'or s.record_hash is distinct from item->>'record_hash'or s.first_detected_at>(result_value->>'recorded_at')::timestamptz then raise exception 'review_materialization_history_invalid'using errcode='23514';end if;
  perform controlled_review_v3.ops_escalation_record(to_jsonb(s));
  if s.evidence->'target_hash'is distinct from o->'target_hash'
   or(s.reason='overdue'and s.evidence->'due_at'is distinct from o->'due_at')then raise exception 'review_materialization_history_invalid'using errcode='23514';end if;
  perform controlled_review_v3.protocol_validate_rejection_routing(s.routing_snapshot,o#>'{historical,routing_snapshot}',s.first_detected_at);
  if s.reason in('no_eligible_reviewer','routing_unavailable','evidence_unavailable','discrepancy_report')then perform controlled_review_v3.ops_validate_worker_assessment(s.evidence->'assessment',base_value);end if;
 end loop;
end

controlled_review_v3.ops_validate_overdu.source:
declare row_value jsonb:=controlled_review_v3.ops_overdue_record(p_row);evidence_value jsonb:=row_value->'evidence';
 obligation_value controlled_review_v3.obligations;decision_value controlled_review_v3.decisions;preparation_value controlled_review_v3.preparations;expected_ids jsonb;
begin
 select *into strict obligation_value from controlled_review_v3.obligations where event_id=(row_value->>'event_id')::uuid;
 if obligation_value.due_at is null or evidence_value->>'target_hash'is distinct from obligation_value.target_hash
  or evidence_value->>'due_at'is distinct from controlled_review_v3.protocol_utc(obligation_value.due_at)then raise exception 'review_overdue_history_invalid'using errcode='23514';end if;
 perform controlled_review_v3.protocol_validate_rejection_routing(row_value->'routing_snapshot',obligation_value.historical->'routing_snapshot',(row_value->>'first_detected_at')::timestamptz);
 if evidence_value->'terminal_operation_id'='null'::jsonb then
  perform controlled_review_v3.ops_validate_worker_source(row_value);return;
 end if;
 select *into strict decision_value from controlled_review_v3.decisions where operation_id=(evidence_value->>'terminal_operation_id')::uuid;
 select *into strict preparation_value from controlled_review_v3.preparations where operation_id=decision_value.operation_id;
 expected_ids:=controlled_review_v3.protocol_escalation_ids(decision_value.operation_id,decision_value.event_id);
 if row_value->>'id'is distinct from expected_ids->>'overdue'or decision_value.event_id is distinct from obligation_value.event_id
  or decision_value.receipt->>'deadline_state'is distinct from 'completed_late'
  or(row_value->>'first_detected_at')::timestamptz is distinct from decision_value.recorded_at
  or evidence_value->>'terminal_receipt_hash'is distinct from public.controlled_stock_hash(decision_value.receipt)
  or controlled_review_v3.protocol_receipt_from_rows(to_jsonb(preparation_value),to_jsonb(decision_value))is distinct from decision_value.receipt then raise exception 'review_overdue_history_invalid'using errcode='23514';end if;
 perform controlled_review_v3.protocol_validate_retained_packet(to_jsonb(preparation_value));
 if preparation_value.packet->'obligation'is distinct from controlled_review_v3.protocol_obligation_dto(obligation_value.event_id)then raise exception 'review_overdue_history_invalid'using errcode='23514';end if;
end

controlled_review_v3.ops_validate_scan(p.source:
declare result_value jsonb:=controlled_review_v3.ops_scan_record(p_row);item jsonb;m controlled_review_v3.materializations;e public.controlled_stock_events;n integer;
begin
 if(result_value->>'from_sequence')::bigint<>0 and not exists(select 1 from controlled_review_v3.scan_receipts where product_id=(result_value->>'product_id')::uuid and through_sequence=(result_value->>'from_sequence')::bigint)then raise exception 'review_scan_prior_checkpoint_missing'using errcode='23514';end if;
 if not exists(select 1 from public.controlled_stock_events where product_id=(result_value->>'product_id')::uuid and sequence=(result_value->>'high_water')::bigint)then raise exception 'review_scan_endpoint_invalid'using errcode='23514';end if;
 select count(*)into n from(select 1 from public.controlled_stock_events where product_id=(result_value->>'product_id')::uuid
  and sequence>(result_value->>'from_sequence')::bigint and sequence<=(result_value->>'through_sequence')::bigint order by sequence limit 101)bounded;
 if n<>jsonb_array_length(result_value->'witnesses')then raise exception 'review_scan_prefix_mismatch'using errcode='23514';end if;
 for item in select value from jsonb_array_elements(result_value->'witnesses')loop
  select *into strict e from public.controlled_stock_events where id=(item->>'event_id')::uuid;
  select *into strict m from controlled_review_v3.materializations where operation_id=(item->>'materialization_operation_id')::uuid;
  if m.event_id<>e.id or m.product_id<>e.product_id or m.product_id::text is distinct from result_value->>'product_id'
  or e.sequence::text is distinct from item->>'event_sequence'or public.controlled_stock_hash(m.result)is distinct from item->>'materialization_hash'
  or m.result->'state'is distinct from item->'state'or m.recorded_at>(result_value->>'recorded_at')::timestamptz then raise exception 'review_scan_witness_mismatch'using errcode='23514';end if;
  perform controlled_review_v3.ops_validate_materialization(to_jsonb(m));
 end loop;
end

controlled_review_v3.ops_validate_worker.source:
declare configs jsonb;facts jsonb;field text;record_value jsonb;actual_record jsonb;fact record;role_value jsonb;prior_role text;ids jsonb;recomputed jsonb;stamp timestamptz;
begin
 if jsonb_typeof(p_assessment)is distinct from 'object'or octet_length(p_assessment::text)>262144 then raise exception 'review_worker_assessment_invalid'using errcode='23514';end if;
 perform public.controlled_stock_keys(p_assessment,array['version','assessed_at','terminal_at_assessment','configurations','member_facts','capacity','routing','reasons']);
 if p_assessment->'version'is distinct from '1'::jsonb or jsonb_typeof(p_assessment->'terminal_at_assessment')is distinct from 'boolean'then raise exception 'review_worker_assessment_invalid'using errcode='23514';end if;
 stamp:=controlled_review_v3.protocol_instant(p_assessment->'assessed_at');configs:=p_assessment->'configurations';facts:=p_assessment->'member_facts';
 perform public.controlled_stock_keys(configs,array['policy','read','review']);
 foreach field in array array['policy','read','review']loop
  record_value:=configs->field;
  if record_value<>'null'::jsonb then
   perform controlled_review_v3.validate_configuration_record(record_value);
   actual_record:=controlled_review_v3.read_configuration_record((record_value->>'id')::uuid);
   if actual_record is distinct from record_value or record_value#>'{scope,product_id}'is distinct from p_base#>'{target,product_id}'or record_value#>'{scope,site_id}'is distinct from p_base#>'{adapter,site_id}'
   or(field='policy'and record_value->>'kind'<>'policy')or(field<>'policy'and(record_value->>'kind'<>'eligibility'or record_value#>>'{scope,capability}'<>field or record_value#>'{scope,event_kind}'is distinct from p_base#>'{adapter,event_kind}'))then raise exception 'review_worker_assessment_invalid'using errcode='23514';end if;
  end if;
 end loop;
 if jsonb_typeof(facts)is distinct from 'object'or octet_length(facts::text)>65536 then raise exception 'review_worker_assessment_invalid'using errcode='23514';end if;
 select coalesce(jsonb_agg(to_jsonb(id_value)),'[]')into ids from(
  select value->>'actor_id'id_value from jsonb_array_elements(coalesce(configs#>'{read,body,members}','[]'))
  union select value->>'actor_id'from jsonb_array_elements(coalesce(p_base#>'{obligation,historical,routing_snapshot,members}','[]')))u;
 if jsonb_array_length(ids)>200 then raise exception 'review_worker_assessment_invalid'using errcode='23514';end if;
 for fact in select key,value from jsonb_each(facts)loop
  perform public.controlled_stock_uuid(to_jsonb(fact.key));perform public.controlled_stock_keys(fact.value,array['active','roles']);
  if not(ids?fact.key)or jsonb_typeof(fact.value->'active')is distinct from 'boolean'or jsonb_typeof(fact.value->'roles')is distinct from 'array'or jsonb_array_length(fact.value->'roles')>4 then raise exception 'review_worker_assessment_invalid'using errcode='23514';end if;
  prior_role:=null;
  for role_value in select value from jsonb_array_elements(fact.value->'roles')loop
   if jsonb_typeof(role_value)is distinct from 'string'or role_value#>>'{}'not in('ADMIN','DVM','STAFF','TECH')or(prior_role is not null and(role_value#>>'{}')collate "C"<=prior_role collate "C")then raise exception 'review_worker_assessment_invalid'using errcode='23514';end if;prior_role:=role_value#>>'{}';
  end loop;
 end loop;
 -- Reuse retained named facts, NEVER today's profiles/roles/session. This
 -- reconstructs capacity, each separate intersection, route and reason set.
 recomputed:=controlled_review_v3.ops_worker_assess(p_base,configs,facts,(p_assessment->>'terminal_at_assessment')::boolean,stamp);
 if recomputed is distinct from p_assessment then raise exception 'review_worker_assessment_invalid'using errcode='23514';end if;
end

declare row_value jsonb:=controlled_review_v3.ops_escalation_record(p_row);operation_value uuid;materialization_value controlled_review_v3.materializations;ids_value jsonb;obligation_value jsonb;
begin
 operation_value:=public.controlled_stock_uuid(row_value#>'{evidence,maintenance_operation_id}');
 select *into strict materialization_value from controlled_review_v3.materializations where operation_id=operation_value;
 perform controlled_review_v3.ops_materialization_record(to_jsonb(materialization_value));ids_value:=controlled_review_v3.ops_worker_ids(operation_value,materialization_value.event_id);
 obligation_value:=controlled_review_v3.read_obligation_dto(materialization_value.event_id);
 if row_value->'id'is distinct from ids_value->(row_value->>'reason')or materialization_value.event_id::text is distinct from row_value->>'event_id'
 or materialization_value.result->>'state'<>'required'or obligation_value is null
 or row_value#>'{evidence,target_hash}'is distinct from obligation_value->'target_hash'
 or controlled_review_v3.protocol_instant(row_value->'first_detected_at')>materialization_value.recorded_at
 or not exists(select 1 from jsonb_array_elements(materialization_value.result->'escalations')v where v->'id'=row_value->'id'and v->'record_hash'=row_value->'record_hash'and v->'reason'=row_value->'reason')then raise exception 'review_worker_escalation_unpaired'using errcode='23514';end if;
 perform controlled_review_v3.protocol_validate_rejection_routing(row_value->'routing_snapshot',obligation_value#>'{historical,routing_snapshot}',controlled_review_v3.protocol_instant(row_value->'first_detected_at'));
end

declare row_value jsonb:=controlled_review_v3.ops_escalation_record(p_row);projection_value jsonb;
begin
 perform controlled_review_v3.ops_validate_worker_escalation(row_value);
 perform controlled_review_v3.read_clinical_dependencies_required();
 projection_value:=controlled_review_v3.ops_worker_projection(controlled_review_v3.ops_worker_collect((row_value->>'event_id')::uuid));
 if projection_value->'obligation'='null'::jsonb
  or row_value#>'{evidence,target_hash}'is distinct from projection_value#>'{obligation,target_hash}'then
  raise exception 'review_history_integrity'using errcode='23514';end if;
 if row_value->>'reason'='overdue'then
  if row_value#>'{evidence,due_at}'is distinct from projection_value#>'{obligation,due_at}'
   or controlled_review_v3.protocol_instant(row_value->'first_detected_at')<=controlled_review_v3.protocol_instant(projection_value#>'{obligation,due_at}')then
   raise exception 'review_overdue_history_invalid'using errcode='23514';end if;
 else
  perform controlled_review_v3.ops_validate_worker_assessment(row_value#>'{evidence,assessment}',projection_value);
 end if;
end

controlled_review_v3.ops_worker_assert(p.source:
declare markers jsonb:=controlled_review_v3.ops_worker_markers();keys_value jsonb;other_value jsonb;unsigned_value bigint;
begin
 if p_kind not in('materialize','scan')or p_kind is null then raise exception 'review_worker_kind_invalid'using errcode='23514';end if;
 perform controlled_review_v3.protocol_principal(null);
 if p_kind='materialize'then
  other_value:=markers->'scan';
  keys_value:=jsonb_build_array(markers->'materialize',jsonb_build_object('class_id',90271101,'key','review-v3-materialization-operation:'||(p_request->>'operation_id'),'mode','exclusive'));
 else
  other_value:=markers->'materialize';
  keys_value:=jsonb_build_array(markers->'scan',jsonb_build_object('class_id',90271106,'key','review-v3-scan-operation:'||(p_request->>'operation_id'),'mode','exclusive'),
   jsonb_build_object('class_id',90271106,'key','review-v3-product-scan:'||(p_request->>'product_id'),'mode','exclusive'));
 end if;
 unsigned_value:=(hashtext(other_value->>'key')::bigint+4294967296)%4294967296;
 if exists(select 1 from pg_catalog.pg_locks where pid=pg_backend_pid()and locktype='advisory'and granted and objsubid=2
  and classid=(other_value->>'class_id')::oid and objid=unsigned_value::oid)then
  raise exception 'review_worker_separate_transaction_required'using errcode='23514';end if;
 perform controlled_review_v3.protocol_assert_advisory(keys_value);
 -- Raw INSERT may arrive with compatible session locks. Assert FIRST (never
 -- acquire a missing earlier resource behind the raw target's relation), then
 -- adopt ALL marker/logical/product gates for this transaction before any wait.
 perform controlled_review_v3.protocol_acquire_advisory(keys_value,null);
end

controlled_review_v3.ops_worker_assess(p.source:
declare o jsonb:=p_base->'obligation';route jsonb:=o#>'{historical,routing_snapshot}';a jsonb;candidates jsonb:='[]';capacity jsonb;
 member jsonb;fact jsonb;facts jsonb:='[]';eligible boolean:=false;status_value text;reasons text[]:='{}';routing_value jsonb;actor_value uuid;
begin
 if jsonb_typeof(p_facts)is distinct from 'object'or octet_length(p_facts::text)>65536 or p_terminal is null then raise exception 'review_worker_assessment_invalid'using errcode='23514';end if;
 perform public.controlled_stock_keys(p_configs,array['policy','read','review']);perform controlled_review_v3.protocol_utc(p_at);
 for member in select value from jsonb_array_elements(coalesce(p_configs#>'{read,body,members}','[]'))loop
  actor_value:=(member->>'actor_id')::uuid;
  if actor_value::text<>p_base#>>'{target,original_actor_id}'then
   a:=controlled_review_v3.read_authorizations(p_configs,actor_value,p_base#>>'{adapter,event_kind}',p_facts);
   if a->'policy'<>'null'::jsonb and a->'read'<>'null'::jsonb and a->'review'<>'null'::jsonb then candidates:=candidates||jsonb_build_array(a);end if;
  end if;
 end loop;
 if p_base#>'{adapter,provenance_state}'='"supported"'::jsonb then
  capacity:=controlled_review_v3.protocol_packet_capacity(case when p_base?'packet_base'then p_base->'packet_base'else p_base end,candidates);
 else
  capacity:=jsonb_build_object('version',1,'source_state',case when p_base->>'source_state'='collector_limit'then 'collector_limit'else 'unsupported'end,
   'packet_available',false,'reason',p_base#>'{adapter,reason}');
 end if;
 if route is not null and route<>'null'::jsonb then
  for member in select value from jsonb_array_elements(route->'members')loop
   fact:=coalesce(p_facts->(member->>'actor_id'),jsonb_build_object('active',false,'roles','[]'::jsonb));
   facts:=facts||jsonb_build_array(jsonb_build_object('actor_id',member->'actor_id','configured_roles',member->'roles','profile_active',fact->'active','live_roles',fact->'roles'));
   if fact->'active'='true'::jsonb and exists(select 1 from jsonb_array_elements(member->'roles')c(value)join jsonb_array_elements(fact->'roles')l(value)using(value))then eligible:=true;end if;
  end loop;
 end if;
 status_value:=case when route is null or route='null'::jsonb then 'missing_route'when route->'enabled'='false'::jsonb then 'disabled_route'when eligible then 'eligible_recipients'else 'no_eligible_recipient'end;
 routing_value:=jsonb_build_object('version',1,'historical',coalesce(route,'null'::jsonb),'assessment',jsonb_build_object('version',1,'recorded_at',controlled_review_v3.protocol_utc(p_at),'status',status_value,'member_facts',facts));
 perform controlled_review_v3.protocol_validate_rejection_routing(routing_value,route,p_at);
 if o is not null and o<>'null'::jsonb then
  if not p_terminal then
   if o->'due_at'<>'null'::jsonb and p_at>controlled_review_v3.protocol_instant(o->'due_at')then reasons:=array_append(reasons,'overdue');end if;
   if jsonb_array_length(candidates)=0 or(capacity->>'within_limit')::integer=0 then reasons:=array_append(reasons,'no_eligible_reviewer');end if;
   if status_value<>'eligible_recipients'then reasons:=array_append(reasons,'routing_unavailable');end if;
   if p_base#>'{adapter,provenance_state}'is distinct from '"supported"'::jsonb or capacity->'base_alone_exceeds_limit'='true'::jsonb or capacity->'all_candidates_exceed_limit'='true'::jsonb then reasons:=array_append(reasons,'evidence_unavailable');end if;
  end if;
  if p_base#>>'{event,event_kind}'='record_native_return_discrepancy:report'and o#>'{historical,rule,enabled}'='true'::jsonb and o#>>'{historical,rule,escalation_mode}'='immediate_on_record'then reasons:=array_append(reasons,'discrepancy_report');end if;
 end if;
 if p_base#>'{adapter,site_id}'='null'::jsonb then
  -- Unproved scope is not proof of missing signers/route. No P or potential
  -- signer projection may be rendered from this worker-only exception.
  if p_terminal or p_configs is distinct from jsonb_build_object('policy',null,'read',null,'review',null)
   or p_facts is distinct from '{}'::jsonb or p_base->'packet_base'is distinct from 'null'::jsonb then
   raise exception 'review_worker_assessment_invalid'using errcode='23514';end if;
  reasons:=case when o is not null and o<>'null'::jsonb then array['evidence_unavailable']else '{}'::text[]end;
 end if;
 select coalesce(array_agg(value order by value collate "C"),'{}'::text[])into reasons from unnest(reasons)r(value);
 return jsonb_build_object('version',1,'assessed_at',controlled_review_v3.protocol_utc(p_at),'terminal_at_assessment',p_terminal,
  'configurations',p_configs,'member_facts',p_facts,'capacity',capacity,'routing',routing_value,'reasons',to_jsonb(reasons));
end

controlled_review_v3.ops_worker_base(p_c.source:
declare request_value jsonb:=p_context->'request';keys_value jsonb;rows_value jsonb;collected jsonb;base_value jsonb;actual_rows jsonb;ids_value jsonb;reserved_value record;existing_value controlled_review_v3.escalations;
begin
 perform controlled_review_v3.ops_worker_assert('materialize',request_value);
 keys_value:=controlled_review_v3.ops_worker_plan(request_value,p_context->'route');
 -- Input-only adapter hint gets NO authority: assert the entire hinted union
 -- BEFORE canonical collection; only alreadyheld resources may be adopted.
 perform controlled_review_v3.protocol_assert_advisory(keys_value);
 rows_value:=controlled_review_v3.protocol_row_targets(p_context->'rows');
 perform controlled_review_v3.protocol_assert_relation_tail('materialize',rows_value);
 perform controlled_review_v3.protocol_acquire_advisory(keys_value,null);
 perform controlled_review_v3.protocol_acquire_fk_tail('materialize',rows_value,null);
 perform controlled_review_v3.required();
 ids_value:=controlled_review_v3.ops_worker_ids((request_value->>'operation_id')::uuid,(request_value->>'event_id')::uuid);
 for reserved_value in select key,value from jsonb_each_text(ids_value)loop
  select *into existing_value from controlled_review_v3.escalations where id=reserved_value.value::uuid;
  if found then
   if existing_value.event_id::text is distinct from request_value->>'event_id'or existing_value.reason is distinct from reserved_value.key
    or existing_value.evidence->'maintenance_operation_id'is distinct from request_value->'operation_id'then
    raise exception 'review_unique_uuid_collision'using errcode='23514';end if;
   perform controlled_review_v3.ops_escalation_record(to_jsonb(existing_value));
  end if;
 end loop;
 perform controlled_review_v3.read_clinical_dependencies_required();
 collected:=controlled_review_v3.ops_worker_collect((request_value->>'event_id')::uuid);
 if jsonb_build_object('event_id',collected#>'{adapter,target,event_id}','product_id',collected#>'{adapter,target,product_id}','event_kind',collected#>'{adapter,event_kind}','site_id',collected#>'{adapter,site_id}','native_family_dispense_id',collected#>'{adapter,native_family_dispense_id}')is distinct from p_context->'route'then raise exception 'review_worker_route_stale'using errcode='23514';end if;
 base_value:=controlled_review_v3.ops_worker_projection(collected);
 actual_rows:=controlled_review_v3.ops_worker_rows_from_projection(base_value);
 if exists(select 1 from((select value-'local'from jsonb_array_elements(actual_rows)except select value-'local'from jsonb_array_elements(rows_value))
  union all(select value-'local'from jsonb_array_elements(rows_value)except select value-'local'from jsonb_array_elements(actual_rows)))changed)
  or exists(select 1 from jsonb_array_elements(rows_value)i join jsonb_array_elements(actual_rows)c
   on i->'relation'=c->'relation'and i->'key'=c->'key'where i->'local'='false'::jsonb and c->'local'='true'::jsonb)then
  raise exception 'review_worker_route_stale'using errcode='23514';end if;
 perform controlled_review_v3.protocol_assert_relation_tail('materialize',actual_rows);
 perform controlled_review_v3.protocol_acquire_fk_tail('materialize',actual_rows,null);
 perform controlled_review_v3.protocol_principal(null);
 if base_value#>'{target,product_id}'is distinct from request_value->'product_id'then raise exception 'review_worker_product_mismatch'using errcode='23514';end if;
 return base_value;
end

controlled_review_v3.ops_worker_capture(.source:
declare configs jsonb;final_configs jsonb;ids jsonb;facts jsonb;terminal_value boolean;stamp timestamptz;
begin
 configs:=case when p_base#>'{adapter,site_id}'='null'::jsonb then jsonb_build_object('policy',null,'read',null,'review',null)else controlled_review_v3.read_current_configs(p_base->'adapter',clock_timestamp())end;
 select coalesce(jsonb_agg(to_jsonb(id_value)order by id_value),'[]'::jsonb)into ids from(
  select value->>'actor_id'id_value from jsonb_array_elements(coalesce(configs#>'{read,body,members}','[]'))
  union select value->>'actor_id'from jsonb_array_elements(coalesce(p_base#>'{obligation,historical,routing_snapshot,members}','[]')))u;
 -- <=100 read members +100 historical route members, all from one command.
 facts:=controlled_review_v3.read_named_facts(ids);
 select exists(select 1 from controlled_review_v3.decisions where event_id=(p_base#>>'{target,event_id}')::uuid)into terminal_value;
 stamp:=clock_timestamp();final_configs:=case when p_base#>'{adapter,site_id}'='null'::jsonb then jsonb_build_object('policy',null,'read',null,'review',null)else controlled_review_v3.read_current_configs(p_base->'adapter',stamp)end;
 if final_configs is distinct from configs then raise exception 'configuration_changed'using errcode='PT409';end if;
 return controlled_review_v3.ops_worker_assess(p_base,configs,facts,terminal_value,stamp);
end

controlled_review_v3.ops_worker_context(.source:
declare raw_value text;decoded json;value jsonb;
begin
 raw_value:=current_setting('controlled_review_v3.maintenance_request',true);
 if raw_value is null or octet_length(raw_value)>131072 then raise exception 'review_worker_context_invalid'using errcode='23514';end if;
 begin decoded:=raw_value::json;exception when invalid_text_representation then raise exception 'review_worker_context_invalid'using errcode='23514';end;
 perform controlled_review_v3.protocol_context_unique(decoded,0);value:=decoded::jsonb;
 perform public.controlled_stock_keys(value,array['request','route','rows']);perform controlled_review_v3.ops_worker_plan(value->'request',value->'route');perform controlled_review_v3.protocol_row_targets(value->'rows');return value;
