 perform public.controlled_stock_keys(assessment_value,array['version','assessed_at','terminal_at_assessment','configurations','member_facts','capacity','routing','reasons']);
 if assessment_value->'version'is distinct from '1'::jsonb or controlled_review_v3.protocol_instant(assessment_value->'assessed_at')is distinct from stamp
 or jsonb_typeof(assessment_value->'terminal_at_assessment')is distinct from 'boolean'or jsonb_typeof(assessment_value->'member_facts')is distinct from 'object'
 or not(assessment_value->'reasons'? (p_row->>'reason'))or assessment_value->'routing'is distinct from p_row->'routing_snapshot'
 or jsonb_typeof(assessment_value->'reasons')is distinct from 'array'or jsonb_array_length(assessment_value->'reasons')>5 then raise exception 'review_worker_escalation_invalid'using errcode='23514';end if;
 if p_row->>'reason'<>'discrepancy_report'and assessment_value->'terminal_at_assessment'<>'false'::jsonb then raise exception 'review_worker_escalation_invalid'using errcode='23514';end if;
