controlled_review_v3.ops_worker_plan(p_r.source:
declare request_value jsonb:=controlled_review_v3.protocol_validate_wire(p_request,'materialize_one');keys_value jsonb;rows_value jsonb;stream_value jsonb;kind_value text;cap_value text;ids_value jsonb;item jsonb;field_value text;
