 keys_value:=keys_value||jsonb_build_array(jsonb_build_object('class_id',90271103,'key','review-v3-event:'||(request_value->>'event_id'),'mode','exclusive'));
 if p_adapter->'site_id'<>'null'::jsonb then
  foreach kind_value in array array['policy','calendar','routing']loop
