   stream_value:=controlled_review_v3.protocol_stream_key(jsonb_build_object('kind','eligibility','product_id',request_value->'product_id','site_id',p_adapter->'site_id','event_kind',p_adapter->'event_kind','capability',cap_value));
   keys_value:=keys_value||jsonb_build_array(jsonb_build_object('class_id',90271104,'key','review-v3-config:'||stream_value::text,'mode','shared'));
