declare adapter_value jsonb:=p_visible->'adapter';event_value jsonb;family_value jsonb;
 obligation_value jsonb;packet_base jsonb;target_value jsonb;stored_value jsonb;
begin
 perform public.controlled_stock_keys(p_visible,array['state','adapter','source_rows']);
 if p_visible->>'state'not in('complete','collector_limit')or p_visible->>'state'is null then
  raise exception 'review_history_integrity'using errcode='23514';end if;
 if p_visible->>'state'='complete'then
  if jsonb_typeof(p_visible->'source_rows')is distinct from 'array'then raise exception 'review_history_integrity'using errcode='23514';end if;
  select value->'row'into strict event_value from jsonb_array_elements(p_visible->'source_rows')
   where value->>'relation'='public.controlled_stock_events'and value#>'{key,id}'=adapter_value#>'{target,event_id}';
  if adapter_value->>'native_family_dispense_id'is not null then
   family_value:=controlled_review_v3.read_native_family_captured(p_visible-'state',
    (adapter_value->>'native_family_dispense_id')::uuid,(adapter_value#>>'{target,product_id}')::uuid);
  end if;
  if adapter_value->'provenance_state'='"supported"'::jsonb then
   packet_base:=controlled_review_v3.read_scalar_base(p_visible-'state');
  end if;
 else
  perform public.controlled_stock_keys(adapter_value,array['version','event_kind','adapter_id','target','site_basis','site_id','source_refs','native_family_dispense_id','provenance_state','reason']);
  if p_visible->'source_rows'is distinct from 'null'::jsonb or adapter_value->'version'is distinct from '1'::jsonb
   or adapter_value->'site_basis'is distinct from '"unproven"'::jsonb or adapter_value->'site_id'is distinct from 'null'::jsonb
   or adapter_value->'native_family_dispense_id'is distinct from 'null'::jsonb or adapter_value->'source_refs'is distinct from '[]'::jsonb
   or adapter_value->'provenance_state'is distinct from '"unsupported"'::jsonb or adapter_value->'reason'is distinct from '"evidence_limit_exceeded"'::jsonb then
   raise exception 'review_history_integrity'using errcode='23514';end if;
  -- No source traversal/family/site fallback after the cold leaf. The target
  -- was validated outside its catch. Only the immutable parent header is read.
  select jsonb_build_object('id',id,'product_id',product_id,'sequence',sequence,'record_hash',record_hash,
   'actor_id',actor_id,'policy_version_id',policy_version_id,'opening_id',opening_id,'engine_revision',engine_revision,
   'event_kind',event_kind,'basis',basis,'observed_at',observed_at,'recorded_at',recorded_at,
   'secondary_review_required',secondary_review_required)into strict event_value
   from public.controlled_stock_events where id=(adapter_value#>>'{target,event_id}')::uuid;
 end if;
 target_value:=jsonb_build_object('event_id',event_value->'id','product_id',event_value->'product_id','sequence',event_value->'sequence',
  'record_hash',event_value->'record_hash','original_actor_id',event_value->'actor_id','policy_version_id',event_value->'policy_version_id',
  'opening_id',event_value->'opening_id','engine_revision',event_value->'engine_revision');
 if adapter_value->'target'is distinct from target_value or adapter_value->'event_kind'is distinct from event_value->'event_kind'then
  raise exception 'review_history_integrity'using errcode='23514';end if;
 obligation_value:=controlled_review_v3.read_obligation_captured(event_value,adapter_value,family_value);
 stored_value:=controlled_review_v3.protocol_obligation_dto((event_value->>'id')::uuid);
 if stored_value is not null and stored_value is distinct from obligation_value then raise exception 'review_history_integrity'using errcode='23514';end if;
 if obligation_value is null and(exists(select 1 from controlled_review_v3.decisions where event_id=(event_value->>'id')::uuid)
  or exists(select 1 from controlled_review_v3.escalations where event_id=(event_value->>'id')::uuid))then
  raise exception 'review_history_integrity'using errcode='23514';end if;
 if packet_base is null and exists(select 1 from controlled_review_v3.decisions where event_id=(event_value->>'id')::uuid)then
  raise exception 'review_history_integrity'using errcode='23514';end if;
 return jsonb_build_object('source_state',p_visible->'state','target',target_value,'adapter',adapter_value,'event',event_value,
  'obligation',obligation_value,'family',family_value,'packet_base',packet_base);
end

