declare rows_value jsonb;event_value uuid:=(p_projection#>>'{target,event_id}')::uuid;
 family_value jsonb:=p_projection->'family';id_value uuid;field_value text;
begin
 rows_value:=jsonb_build_array(jsonb_build_object('relation','public.controlled_stock_events','key',jsonb_build_object('id',event_value),'local',false));
 if p_projection->'obligation'is not null and p_projection->'obligation'<>'null'::jsonb then
  rows_value:=rows_value||jsonb_build_array(jsonb_build_object('relation','controlled_review_v3.obligations','key',jsonb_build_object('event_id',event_value),
   'local',not exists(select 1 from controlled_review_v3.obligations where event_id=event_value)));
 end if;
 if p_projection->'obligation'is not null and p_projection->'obligation'<>'null'::jsonb
  and family_value is not null and family_value<>'null'::jsonb then
  id_value:=(family_value->>'dispense_id')::uuid;
  rows_value:=rows_value||jsonb_build_array(
   jsonb_build_object('relation','public.controlled_stock_events','key',jsonb_build_object('id',id_value),'local',false),
   jsonb_build_object('relation','controlled_review_v3.families','key',jsonb_build_object('dispense_id',id_value),
    'local',not exists(select 1 from controlled_review_v3.families where dispense_id=id_value)));
 end if;
 -- Reserve all retained configuration FK targets. No current configuration is
 -- substituted for a family's original selection or an obligation's anchor.
 foreach field_value in array array['policy_id','calendar_id','routing_id']loop
  for id_value in select distinct id_text::uuid from(
   select p_projection#>>array['obligation','historical',field_value]id_text
   union select family_value#>>array['selection',field_value])refs where id_text is not null loop
   rows_value:=rows_value||jsonb_build_array(jsonb_build_object('relation','controlled_review_v3.configuration',
    'key',jsonb_build_object('id',id_value),'local',false));
  end loop;
 end loop;
 return controlled_review_v3.protocol_row_targets(rows_value);
end

controlled_review_v3.protocol_acquire_ad.source:
declare planned jsonb:=controlled_review_v3.protocol_lock_keys(p_keys);item jsonb;unsigned_key bigint;class_value integer;key_value integer;
begin
 perform controlled_review_v3.protocol_assert_advisory('[]'::jsonb);
 -- pg_locks cannot distinguish session-owned from transaction-owned locks.
 -- Reentrant xact acquisition adopts the already compatible barrier for this
 -- transaction; a later session unlock cannot release this ownership.
 perform pg_advisory_xact_lock_shared(90271040,0);
 -- Refuse caller-held strong locks on ANY finite path dependency BEFORE
 -- the first table-reading principal command or missing earlier advisory key.
 -- The raw target's initial ordinary ROW EXCLUSIVE is deliberately compatible.
 if exists(select 1 from pg_locks as held where held.pid=pg_backend_pid()and held.locktype='relation'and held.granted
  and held.mode not in('AccessShareLock','RowShareLock','RowExclusiveLock')
  and held.relation in(select to_regclass(resource.value->>'relation')from
   unnest(array['prepare','decision','prepared_cancel','eventless_cancel','publication','materialize','scan','escalation_action','raw_family','raw_obligation'])as path(name)
   cross join lateral jsonb_array_elements(controlled_review_v3.protocol_path_tables(path.name))as resource(value)))then
  raise exception 'review_lock_order_invalid'using errcode='23514';end if;
 perform controlled_review_v3.protocol_principal(p_actor_id);
 for item in select value from jsonb_array_elements(planned)loop
  class_value:=(item->>'class_id')::integer;key_value:=(item->>'lock_id')::integer;
  unsigned_key:=(key_value::bigint+4294967296)%4294967296;
  if not exists(select 1 from pg_locks where pid=pg_backend_pid()and locktype='advisory'and granted
   and classid=class_value::oid and objid=unsigned_key::oid and objsubid=2
   and(mode='ExclusiveLock'or(mode='ShareLock'and item->>'mode'='shared')))then
   -- Do not upgrade a shared collision, append an earlier key, or introduce an
   -- earlier class behind a later phase. Raw guards must assert the full union.
   if exists(select 1 from pg_locks where pid=pg_backend_pid()and locktype='advisory'and granted and objsubid=2
    and classid between 90271101::oid and 90271106::oid
    and(classid>class_value::oid or(classid=class_value::oid and(
     (objid::bigint>2147483647 and objid::bigint-4294967296>=key_value)
     or(objid::bigint<=2147483647 and objid::bigint>=key_value)))))then
    raise exception 'review_lock_order_invalid'using errcode='23514';end if;
  end if;
  -- Always acquire xact ownership, including a compatible existing session
  -- lock. Raw insert guards must use this adoption helper, never assert alone.
  if item->>'mode'='exclusive'then perform pg_advisory_xact_lock(class_value,key_value);
  else perform pg_advisory_xact_lock_shared(class_value,key_value);end if;
  -- A fresh command after each possibly blocking lock, including reentrant use.
  perform controlled_review_v3.protocol_principal(p_actor_id);
 end loop;
 perform controlled_review_v3.protocol_principal(p_actor_id);
 perform controlled_review_v3.protocol_assert_advisory(p_keys);
end

