declare rows_value jsonb:=controlled_review_v3.protocol_row_targets(p_rows);item jsonb;key_value uuid;
begin
 perform controlled_review_v3.protocol_assert_relation_tail(p_path,rows_value);
 perform controlled_review_v3.protocol_principal(p_actor_id);
 for item in select value from jsonb_array_elements(rows_value)loop
  if item->'local'='true'::jsonb then continue;end if;
  select(value#>>'{}')::uuid into key_value from jsonb_each(item->'key');
  case item->>'relation'
  when 'controlled_review_v3.configuration'then perform 1 from controlled_review_v3.configuration where id=key_value for key share;
  when 'controlled_review_v3.publications'then perform 1 from controlled_review_v3.publications where operation_id=key_value for key share;
  when 'controlled_review_v3.operation_claims'then perform 1 from controlled_review_v3.operation_claims where operation_id=key_value for key share;
  when 'controlled_review_v3.families'then perform 1 from controlled_review_v3.families where dispense_id=key_value for key share;
