  when 'controlled_review_v3.preparations'then perform 1 from controlled_review_v3.preparations where operation_id=key_value for key share;
  when 'controlled_review_v3.escalations'then perform 1 from controlled_review_v3.escalations where id=key_value for key share;
  when 'public.controlled_stock_events'then perform 1 from public.controlled_stock_events where id=key_value for key share;
  else raise exception 'review_lock_plan_invalid'using errcode='23514';end case;
  if not found then raise exception 'review_history_integrity'using errcode='23514';end if;
  perform controlled_review_v3.protocol_principal(p_actor_id);
 end loop;
