controlled_review_v3.protocol_family_pre.source:
declare managed_value jsonb;event_value public.controlled_stock_events;adapter_value jsonb;policy_value jsonb;references_value jsonb;
 selection_value jsonb;result_value jsonb;reason_value text;
begin
 managed_value:=controlled_review_v3.managed_source_event(jsonb_build_object('source_kind','dispense','source_id',p_dispense_id,'product_id',p_product_id));
 if managed_value is null then return null;end if;
 select *into strict event_value from public.controlled_stock_events where id=(managed_value->>'event_id')::uuid;
 if event_value.id<>p_dispense_id or event_value.product_id<>p_product_id or event_value.event_kind<>'record_native_dispense'
  or event_value.observed_at is null then raise exception 'review_history_integrity'using errcode='23514';end if;
 adapter_value:=controlled_review_v3.adapt_event(event_value.id);
 policy_value:=controlled_review_v3.protocol_policy_at(p_product_id,(adapter_value->>'site_id')::uuid,event_value.observed_at);
 references_value:=case when policy_value is null then jsonb_build_object('calendar',null,'routing',null)
  else controlled_review_v3.protocol_policy_references(policy_value)end;
 reason_value:=case when adapter_value->>'site_id'is null then 'family_site_unproven'
  when policy_value is null then 'no_policy_at_anchor'
  when policy_value->'enabled'is distinct from 'true'::jsonb then 'policy_disabled_at_anchor'else null end;
 selection_value:=jsonb_build_object('version',1,'original_dispense_target',adapter_value->'target',
  'original_dispense_target_hash',public.controlled_stock_hash(adapter_value->'target'),
  'selection_anchor',to_char(event_value.observed_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
  'policy_id',policy_value->'id','policy_hash',policy_value->'record_hash',
  'native_deadline_kind',policy_value#>'{body,native_deadline_kind}',
  'calendar_id',references_value#>'{calendar,id}','calendar_hash',references_value#>'{calendar,record_hash}',
  'routing_id',references_value#>'{routing,id}','routing_hash',references_value#>'{routing,record_hash}','unavailable_reason',reason_value);
 result_value:=jsonb_build_object('dispense_id',p_dispense_id,'target',adapter_value->'target',
  'target_hash',public.controlled_stock_hash(adapter_value->'target'),'product_id',p_product_id,
  'site_id',adapter_value->'site_id','selection',selection_value);
 return result_value||jsonb_build_object('binding_hash',public.controlled_stock_hash(result_value));
end

controlled_review_v3.protocol_guard_canc.source:
declare preparation_value controlled_review_v3.preparations;claim_value controlled_review_v3.operation_claims;preparation_exists boolean;
context_value jsonb;context_text text;decoded_context json;path_value text:='prepared_cancel';keys_value jsonb;rows_value jsonb;identity_value jsonb;at_value timestamptz;
begin
 if TG_OP<>'INSERT'or TG_TABLE_SCHEMA<>'controlled_review_v3'or TG_TABLE_NAME<>'cancellations'then raise exception 'review_insert_invalid'using errcode='23514';end if;
 if pg_catalog.pg_my_temp_schema()<>0 then raise exception 'review_temp_namespace_forbidden'using errcode='42501';end if;
 if NEW.session_id is not null or NEW.kind is not null or NEW.transport_digest is not null or NEW.recorded_at is not null then
  raise exception 'review_server_field_supplied'using errcode='23514';end if;
 perform public.controlled_stock_uuid(to_jsonb(NEW.operation_id));perform public.controlled_stock_uuid(to_jsonb(NEW.actor_id));
 keys_value:=jsonb_build_array(jsonb_build_object('class_id',90271101,'key','review-v3-operation:'||NEW.operation_id::text,'mode','exclusive'));
 context_text:=current_setting('controlled_review_v3.claim_request',true);
 if context_text is not null and context_text<>''then
  if octet_length(context_text)>65536 then raise exception 'review_claim_context_invalid'using errcode='23514';end if;
  begin decoded_context:=context_text::json;perform controlled_review_v3.protocol_context_unique(decoded_context,0);context_value:=decoded_context::jsonb;
  exception when invalid_text_representation then raise exception 'review_claim_context_invalid'using errcode='23514';end;
  context_value:=controlled_review_v3.protocol_claim_context(context_value);
  if context_value->>'path'='eventless_cancel'then
   if session_user<>'authenticator'or current_user<>'postgres'or context_value#>>'{request,actor_id}'is distinct from NEW.actor_id::text
    or context_value#>>'{request,operation_id}'is distinct from NEW.operation_id::text then raise exception 'review_claim_native_route_required'using errcode='42501';end if;
   path_value:='eventless_cancel';
  end if;
 end if;
 rows_value:=controlled_review_v3.protocol_row_targets(jsonb_build_array(jsonb_build_object('relation','controlled_review_v3.operation_claims',
  'key',jsonb_build_object('operation_id',NEW.operation_id),'local',false)));
 perform controlled_review_v3.protocol_assert_advisory(keys_value);
 perform controlled_review_v3.protocol_assert_relation_tail(path_value,rows_value);
 select *into strict claim_value from controlled_review_v3.operation_claims where operation_id=NEW.operation_id;
 if claim_value.actor_id is distinct from NEW.actor_id then raise exception 'operation_not_found'using errcode='PT404';end if;
 select *into preparation_value from controlled_review_v3.preparations where operation_id=NEW.operation_id;preparation_exists:=found;
 if preparation_exists then
  if path_value<>'prepared_cancel'then raise exception 'review_claim_context_stale'using errcode='23514';end if;
  perform controlled_review_v3.protocol_retained_preparation(to_jsonb(preparation_value));
  keys_value:=controlled_review_v3.protocol_review_keys(jsonb_build_object('path','prepared_cancel','operation_id',NEW.operation_id,
   'adapter',preparation_value.packet->'adapter','escalation_ids','{}'::jsonb));
  perform controlled_review_v3.protocol_assert_advisory(keys_value);
 elsif path_value<>'eventless_cancel'then raise exception 'review_claim_context_invalid'using errcode='23514';end if;
 perform controlled_review_v3.protocol_acquire_advisory(keys_value,NEW.actor_id);
 perform controlled_review_v3.protocol_acquire_fk_tail(path_value,rows_value,NEW.actor_id);perform controlled_review_v3.required();
 if exists(select 1 from controlled_review_v3.decisions where operation_id=NEW.operation_id)
  or exists(select 1 from controlled_review_v3.cancellations where operation_id=NEW.operation_id)then raise exception 'review_already_terminal'using errcode='PT409';end if;
 if preparation_exists then
  perform controlled_review_v3.required();perform controlled_review_v3.read_clinical_dependencies_required();
  if controlled_review_v3.adapt_event(preparation_value.event_id)is distinct from preparation_value.packet->'adapter'then
   raise exception 'review_history_integrity'using errcode='23514';end if;
 end if;
 identity_value:=controlled_review_v3.protocol_identity(NEW.actor_id);at_value:=clock_timestamp();perform controlled_review_v3.protocol_utc(at_value);
 if at_value<claim_value.claimed_at then raise exception 'review_clock_invalid'using errcode='23514';end if;
 NEW.session_id:=(identity_value->>'session_id')::uuid;NEW.kind:=case when preparation_exists then 'prepared'else 'unprepared'end;
 NEW.transport_digest:=case when preparation_exists then preparation_value.transport_digest else null end;NEW.recorded_at:=at_value;
 if pg_catalog.pg_my_temp_schema()<>0 then raise exception 'review_temp_namespace_forbidden'using errcode='42501';end if;
 return NEW;
end

controlled_review_v3.protocol_guard_clai.source:
declare raw_context text;decoded_context json;context_value jsonb;request_value jsonb;keys_value jsonb;expected_keys jsonb;rows_value jsonb;expected_rows jsonb;
adapter_value jsonb;collected_value jsonb;route_value jsonb;packet_value jsonb;actor_value uuid;at_value timestamptz;path_value text;
begin
 -- Source/ACL closure is a separate REQUIRED admission gate: the actual app
 -- transport may reach a claim INSERT only through sealed prepare/cancel
 -- SECURITY DEFINER bodies holding a local validated request and full union.
 -- Native backend identity, never a GUC/callstack/JWT role alone, restricts the
 -- origin. Unsupported raw owner claim creation refuses before any reads.
 if session_user<>'authenticator'or current_user<>'postgres'then
  raise exception 'review_claim_native_route_required'using errcode='42501';end if;
 if pg_catalog.pg_my_temp_schema()<>0 then raise exception 'review_claim_temp_namespace_forbidden'using errcode='42501';end if;
 if TG_OP<>'INSERT'or TG_TABLE_SCHEMA<>'controlled_review_v3'or TG_TABLE_NAME<>'operation_claims'then
  raise exception 'review_insert_invalid'using errcode='23514';end if;
 if NEW.claimed_at is not null then raise exception 'review_server_field_supplied'using errcode='23514';end if;
 raw_context:=current_setting('controlled_review_v3.claim_request',true);
 if raw_context is null or octet_length(raw_context)>65536 or raw_context=''then
  raise exception 'review_claim_context_invalid'using errcode='23514';end if;
 begin decoded_context:=raw_context::json;
  perform controlled_review_v3.protocol_context_unique(decoded_context,0);
  context_value:=decoded_context::jsonb;
 exception when invalid_text_representation then
  raise exception 'review_claim_context_invalid'using errcode='23514';end;
 context_value:=controlled_review_v3.protocol_claim_context(context_value);request_value:=context_value->'request';
 actor_value:=public.controlled_stock_uuid(request_value->'actor_id');path_value:=context_value->>'path';rows_value:=context_value->'rows';
 if NEW.operation_id is distinct from(request_value->>'operation_id')::uuid or NEW.actor_id is distinct from actor_value then
  raise exception 'review_claim_context_invalid'using errcode='23514';end if;
 if path_value='prepare'then
  keys_value:=controlled_review_v3.protocol_review_route_keys(jsonb_build_object('path','prepare','operation_id',request_value->'operation_id',
   'route',context_value->'route','escalation_ids','{}'::jsonb));
 else keys_value:=jsonb_build_array(jsonb_build_object('class_id',90271101,'key','review-v3-operation:'||NEW.operation_id::text,'mode','exclusive'));end if;
 -- FIRST actual-held proofs. No canonical source/identity/config queries or
 -- missing earlier lock acquisition precede these complete candidate proofs.
 perform controlled_review_v3.protocol_assert_advisory(keys_value);
 perform controlled_review_v3.protocol_assert_relation_tail(path_value,rows_value);
 -- Reentrant adoption cannot turn a missing key into an admitted earlier phase.
 perform controlled_review_v3.protocol_acquire_advisory(keys_value,actor_value);
 perform controlled_review_v3.required();
 if path_value='prepare'then
  perform controlled_review_v3.read_clinical_dependencies_required();
  collected_value:=controlled_review_v3.collect_event_sources((request_value->>'event_id')::uuid);adapter_value:=collected_value->'adapter';
  route_value:=jsonb_build_object('target',adapter_value->'target','event_kind',adapter_value->'event_kind','site_id',adapter_value->'site_id',
   'native_family_dispense_id',adapter_value->'native_family_dispense_id','provenance_state',adapter_value->'provenance_state');
  expected_keys:=controlled_review_v3.protocol_review_keys(jsonb_build_object('path','prepare','operation_id',request_value->'operation_id',
   'adapter',adapter_value,'escalation_ids','{}'::jsonb));
  expected_rows:=controlled_review_v3.protocol_review_rows(jsonb_build_object('path','prepare','operation_id',request_value->'operation_id',
   'event_id',request_value->'event_id','configuration_ids',jsonb_build_object('policy',request_value->'policy_id','read',request_value->'read_eligibility_id','review',request_value->'review_eligibility_id')));
  if route_value is distinct from context_value->'route'or expected_keys is distinct from keys_value then
   raise exception 'review_claim_context_stale'using errcode='23514';end if;
 else
  expected_rows:=controlled_review_v3.protocol_review_rows(jsonb_build_object('path','eventless_cancel','operation_id',request_value->'operation_id','event_id',null,'configuration_ids','{}'::jsonb));
 end if;
 if expected_rows is distinct from rows_value then raise exception 'review_claim_context_stale'using errcode='23514';end if;
 -- No newly discovered key/relation/row is acquired on mismatch. The full exact
 -- row union is now independently bound to canonical data and earlier gates.
 perform controlled_review_v3.protocol_acquire_fk_tail(path_value,rows_value,actor_value);
 perform controlled_review_v3.protocol_identity(actor_value);
 at_value:=clock_timestamp();
 if path_value='prepare'then
  packet_value:=controlled_review_v3.protocol_packet_from_collected(jsonb_build_object('actor_id',actor_value,'event_id',request_value->'event_id'),at_value,collected_value);
  perform controlled_review_v3.protocol_signing_packet(request_value,packet_value);
  perform controlled_review_v3.protocol_identity(actor_value);at_value:=clock_timestamp();
  packet_value:=packet_value||jsonb_build_object('current_authorization',controlled_review_v3.protocol_authorization_route(packet_value->'adapter',actor_value,at_value));
  perform controlled_review_v3.protocol_signing_packet(request_value,packet_value);
 end if;
 -- claimed_at is never caller authority: the guard overwrites it with the
 -- accepted post-tail server instant. Facades use INSERT RETURNING this value.
 if pg_catalog.pg_my_temp_schema()<>0 then raise exception 'review_claim_temp_namespace_forbidden'using errcode='42501';end if;
 NEW.claimed_at:=at_value;
 return NEW;
end

controlled_review_v3.protocol_guard_conf.source:
declare context_value jsonb;request_value jsonb;document_value jsonb;owner_value boolean;actor_value uuid;keys_value jsonb;rows_value jsonb;
identity_value jsonb;authority_value jsonb;authority_id uuid;stream_value jsonb;previous_value controlled_review_v3.configuration;
previous_exists boolean;mode_value text;name_value text;calendar_value jsonb:='null'::jsonb;record_value jsonb;row_value jsonb;
member_value jsonb;member_name text;at_value timestamptz;
begin
 if TG_OP<>'INSERT'or TG_TABLE_SCHEMA<>'controlled_review_v3'or TG_TABLE_NAME<>'configuration'then raise exception 'review_insert_invalid'using errcode='23514';end if;
 if pg_catalog.pg_my_temp_schema()<>0 then raise exception 'review_temp_namespace_forbidden'using errcode='42501';end if;
 if NEW.document is not null or NEW.record_hash is not null or NEW.published_at is not null or NEW.publisher_actor_id is not null
  or NEW.publisher_session_id is not null or NEW.publisher_name is not null or NEW.authorization_id is not null or NEW.publication_mode is not null or NEW.effective_from is not null then
  raise exception 'review_server_field_supplied'using errcode='23514';end if;
 context_value:=controlled_review_v3.protocol_read_publication_context();request_value:=context_value->'request';document_value:=request_value->'document';
 owner_value:=document_value->>'kind'='administration';actor_value:=case when owner_value then null else(request_value->>'actor_id')::uuid end;
 authority_id:=(context_value->>'authority_id')::uuid;stream_value:=(document_value->'scope')||jsonb_build_object('kind',document_value->'kind');
 if NEW.id is distinct from(request_value->>'record_id')::uuid or NEW.publication_operation_id is distinct from(request_value->>'operation_id')::uuid
  or NEW.kind is distinct from document_value->>'kind'or NEW.stream_key is distinct from stream_value or NEW.version is distinct from(document_value->>'version')::integer
  or NEW.predecessor_id is distinct from(document_value->>'predecessor_id')::uuid or NEW.predecessor_hash is distinct from document_value->>'predecessor_hash'
  or NEW.enabled is distinct from(document_value->>'enabled')::boolean then raise exception 'operation_request_mismatch'using errcode='PT409';end if;
 keys_value:=controlled_review_v3.protocol_publication_candidate_keys(request_value);
 rows_value:=controlled_review_v3.protocol_publication_rows(request_value,authority_id);
 perform controlled_review_v3.protocol_assert_advisory(keys_value);
 perform controlled_review_v3.protocol_assert_relation_tail('publication',rows_value);
 perform controlled_review_v3.protocol_acquire_advisory(keys_value,actor_value);
 perform controlled_review_v3.protocol_publication_input(request_value,owner_value);perform controlled_review_v3.required();
 if exists(select 1 from controlled_review_v3.configuration where id=NEW.id)
  or exists(select 1 from controlled_review_v3.publications where operation_id=NEW.publication_operation_id or record_id=NEW.id)then
  raise exception 'review_unique_uuid_collision'using errcode='23514';end if;
 select *into previous_value from controlled_review_v3.configuration where stream_key=stream_value order by version desc limit 1;previous_exists:=found;
 if previous_exists then
  perform controlled_review_v3.protocol_validate_publication_record(previous_value.id);
  if NEW.version<>previous_value.version+1 or NEW.predecessor_id is distinct from previous_value.id or NEW.predecessor_hash is distinct from previous_value.record_hash then
   raise exception 'review_configuration_predecessor_mismatch'using errcode='23514';end if;
 elsif NEW.version<>1 or NEW.predecessor_id is not null or NEW.predecessor_hash is not null then raise exception 'review_configuration_predecessor_mismatch'using errcode='23514';end if;
 if not exists(select 1 from public.catalog_products where id=(document_value#>>'{scope,product_id}')::uuid)
  or(document_value#>'{scope,site_id}'is distinct from 'null'::jsonb and not exists(select 1 from public.controlled_stock_sites where id=(document_value#>>'{scope,site_id}')::uuid))then
  raise exception 'review_configuration_reference_missing'using errcode='23514';end if;
 if document_value->>'kind'in('administration','eligibility','routing')then
  for member_value in select value from jsonb_array_elements(document_value#>'{body,members}')loop
   select full_name into strict member_name from public.profiles where id=(member_value->>'actor_id')::uuid;
   perform public.controlled_stock_text(to_jsonb(member_name),200,false);
  end loop;
 end if;
 perform controlled_review_v3.protocol_acquire_fk_tail('publication',rows_value,actor_value);
 if document_value->>'kind'='calendar'then calendar_value:=controlled_review_v3.resolve_calendar(document_value->'body')->'observation';end if;
 if owner_value then
  perform controlled_review_v3.protocol_principal(null);identity_value:='null'::jsonb;name_value:='Database owner (postgres)';
  mode_value:=case when previous_exists then 'owner_recovery'else 'owner_bootstrap'end;
 else
  identity_value:=controlled_review_v3.protocol_identity(actor_value);select full_name into strict name_value from public.profiles where id=actor_value;
  perform public.controlled_stock_text(to_jsonb(name_value),200,false);mode_value:='staff';
 end if;
 at_value:=clock_timestamp();
 if not owner_value then
  authority_value:=controlled_review_v3.protocol_publication_authority(request_value,at_value);
  if authority_value->>'id'is distinct from authority_id::text then raise exception 'review_publication_authority_changed'using errcode='PT409';end if;
 end if;
 record_value:=controlled_review_v3.protocol_publication_record_at(request_value,identity_value,name_value,authority_id,mode_value,at_value,calendar_value);
 if NEW.kind='policy'then
  perform controlled_review_v3.protocol_policy_references(record_value);
  if previous_exists and controlled_review_v3.protocol_instant(record_value#>'{body,effective_from}')<=previous_value.effective_from then
   raise exception 'review_policy_effective_time_invalid'using errcode='23514';end if;
 end if;
 row_value:=controlled_review_v3.protocol_configuration_row_value(record_value);
 NEW.document:=row_value->'document';NEW.record_hash:=row_value->>'record_hash';NEW.published_at:=at_value;
