 -- One fresh command observes profile activity and relevant LIVE roles together.
 -- DTO configuredroles never replace this authoritative database lookup.
 select p.is_active,(select coalesce(jsonb_agg(role_name order by role_name collate "C"),'[]'::jsonb)from(
  select distinct r.role::text as role_name from public.user_roles r where r.user_id=p_actor_id and r.role::text in('ADMIN','DVM','STAFF','TECH'))q)
 into active_value,roles_value from public.profiles p where p.id=p_actor_id;
 if not found then active_value:=false;roles_value:='[]'::jsonb;end if;
 return controlled_review_v3.protocol_member_conditions(jsonb_build_object('record',p_record,'actor_id',p_actor_id,
  'capability',p_capability,'active',active_value,'live_roles',roles_value));
end

controlled_review_v3.protocol_lock_keys(.source:
declare item jsonb;class_value integer;key_value text;mode_value text;stream_value jsonb;raw_stream text;result_value jsonb;
begin
 if jsonb_typeof(p_keys)is distinct from 'array'or octet_length(p_keys::text)>131072 then
  raise exception 'review_lock_plan_invalid'using errcode='23514';end if;
 if jsonb_array_length(p_keys)>128 then raise exception 'review_lock_plan_invalid'using errcode='23514';end if;
 for item in select value from jsonb_array_elements(p_keys)loop
  perform public.controlled_stock_keys(item,array['class_id','key','mode']);
  if jsonb_typeof(item->'class_id')is distinct from 'number'or(item->>'class_id')!~'^9027110[1-6]$'
   or jsonb_typeof(item->'key')is distinct from 'string'or jsonb_typeof(item->'mode')is distinct from 'string'then
   raise exception 'review_lock_plan_invalid'using errcode='23514';end if;
  class_value:=(item->>'class_id')::integer;key_value:=item->>'key';mode_value:=item->>'mode';
  if mode_value not in('shared','exclusive')or octet_length(key_value)not between 1 and 4096
   or(class_value<>90271104 and mode_value<>'exclusive')then
   raise exception 'review_lock_plan_invalid'using errcode='23514';end if;
  if class_value=90271101 then
   if key_value!~'^review-v3-(operation|publication-operation|materialization-operation|escalation-operation):[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'then
    raise exception 'review_lock_plan_invalid'using errcode='23514';end if;
   perform public.controlled_stock_uuid(to_jsonb(substring(key_value from '[0-9a-f-]{36}$')));
  elsif class_value in(90271102,90271103)then
   if key_value!~(case class_value when 90271102 then '^review-v3-family:[0-9a-f-]{36}$'else '^review-v3-event:[0-9a-f-]{36}$'end)then
    raise exception 'review_lock_plan_invalid'using errcode='23514';end if;
   perform public.controlled_stock_uuid(to_jsonb(substring(key_value from '[0-9a-f-]{36}$')));
  elsif class_value=90271104 then
   if left(key_value,17)<>'review-v3-config:'then raise exception 'review_lock_plan_invalid'using errcode='23514';end if;
   raw_stream:=substring(key_value from 18);stream_value:=raw_stream::jsonb;
   perform controlled_review_v3.protocol_stream_key(stream_value);
   if raw_stream<>stream_value::text then raise exception 'review_lock_plan_invalid'using errcode='23514';end if;
  elsif class_value=90271105 then
   if key_value!~'^review-v3-unique:(configuration|escalations):[0-9a-f-]{36}$'then
    raise exception 'review_lock_plan_invalid'using errcode='23514';end if;
   perform public.controlled_stock_uuid(to_jsonb(substring(key_value from '[0-9a-f-]{36}$')));
  elsif class_value=90271106 then
   if key_value!~'^review-v3-(scan-operation|product-scan):[0-9a-f-]{36}$'then
    raise exception 'review_lock_plan_invalid'using errcode='23514';end if;
   perform public.controlled_stock_uuid(to_jsonb(substring(key_value from '[0-9a-f-]{36}$')));
  end if;
 end loop;
 -- Hash collisions/repetitions collapse to the strongest mode BEFORE taking
 -- any lock. Actual signed int32 hash order, not lexical prefix order, rules.
 with planned as(select(value->>'class_id')::integer as class_id,value->>'key'as canonical_key,
  hashtext(value->>'key')as lock_id,value->>'mode'as requested_mode from jsonb_array_elements(p_keys)),
 collapsed as(select class_id,lock_id,min(canonical_key collate "C")as first_key,
  case when bool_or(requested_mode='exclusive')then 'exclusive'else 'shared'end as mode,
  jsonb_agg(distinct canonical_key collate "C" order by canonical_key collate "C")as keys from planned group by class_id,lock_id)
 select coalesce(jsonb_agg(jsonb_build_object('class_id',class_id,'lock_id',lock_id,'mode',mode,'keys',keys)
  order by class_id,lock_id,first_key collate "C"),'[]'::jsonb)into result_value from collapsed;
 return result_value;
exception when check_violation or invalid_text_representation then
 raise exception 'review_lock_plan_invalid'using errcode='23514';
end

controlled_review_v3.protocol_member_con.source:
declare record_value jsonb;member_value jsonb;kind_value text;actor_value uuid;capability_value text;
 role_value jsonb;previous_role text;matched boolean:=false;
begin
 if jsonb_typeof(p_request)is distinct from 'object'or octet_length(p_request::text)>524288 then
  raise exception 'review_membership_invalid'using errcode='23514';end if;
 perform public.controlled_stock_keys(p_request,array['record','actor_id','capability','active','live_roles']);
 record_value:=controlled_review_v3.validate_configuration_record(p_request->'record');
 actor_value:=public.controlled_stock_uuid(p_request->'actor_id');
 if jsonb_typeof(p_request->'active')is distinct from 'boolean'or jsonb_typeof(p_request->'capability')is distinct from 'string'
  or jsonb_typeof(p_request->'live_roles')is distinct from 'array'then
  raise exception 'review_membership_invalid'using errcode='23514';end if;
 if jsonb_array_length(p_request->'live_roles')>4 then raise exception 'review_membership_invalid'using errcode='23514';end if;
 for role_value in select value from jsonb_array_elements(p_request->'live_roles')loop
  if jsonb_typeof(role_value)is distinct from 'string'or role_value#>>'{}'not in('ADMIN','DVM','STAFF','TECH')
   or(previous_role is not null and(role_value#>>'{}')collate "C"<=previous_role collate "C")then
   raise exception 'review_membership_invalid'using errcode='23514';end if;
  previous_role:=role_value#>>'{}';
 end loop;
 kind_value:=record_value->>'kind';capability_value:=p_request->>'capability';
 if not((kind_value='eligibility'and capability_value in('read','review','exception_read')and record_value#>>'{scope,capability}'=capability_value)
  or(kind_value='administration'and capability_value in('publish_policy','publish_calendar','publish_routing','manage_eligibility','audit','manage_escalation'))
  or(kind_value='routing'and capability_value='recipient'))then
  raise exception 'review_capability_invalid'using errcode='23514';end if;
 if record_value->'enabled'is distinct from 'true'::jsonb or p_request->'active'is distinct from 'true'::jsonb then return null;end if;
 select value into member_value from jsonb_array_elements(record_value#>'{body,members}')where value->>'actor_id'=actor_value::text;
 if member_value is null then return null;end if;
 if kind_value='administration'and not(member_value->'capabilities'?capability_value)then return null;end if;
 select exists(select 1 from jsonb_array_elements_text(p_request->'live_roles')as r(role_name)where member_value->'roles'?r.role_name)into matched;
 if not matched then return null;end if;
 -- Pure conditions only: supplied live facts do not establish authentication.
 -- The permission-reader below obtains those facts from one fresh SQL command.
 return jsonb_build_object('id',record_value->'id','record_hash',record_value->'record_hash','actor_id',actor_value,'roles',member_value->'roles');
end

controlled_review_v3.protocol_native_con.source:
declare raw_value text;decoded_value json;context_value jsonb;
begin
 if session_user<>'authenticator'or current_user<>'postgres'then raise exception 'review_claim_native_route_required'using errcode='42501';end if;
 if pg_catalog.pg_my_temp_schema()<>0 then raise exception 'review_claim_temp_namespace_forbidden'using errcode='42501';end if;
 raw_value:=current_setting('controlled_review_v3.claim_request',true);
 if raw_value is null or raw_value=''or octet_length(raw_value)>65536 then raise exception 'review_claim_context_invalid'using errcode='23514';end if;
 begin decoded_value:=raw_value::json;perform controlled_review_v3.protocol_context_unique(decoded_value,0);context_value:=decoded_value::jsonb;
 exception when invalid_text_representation then raise exception 'review_claim_context_invalid'using errcode='23514';end;
 return controlled_review_v3.protocol_claim_context(context_value);
end

controlled_review_v3.protocol_native_pre.source:
declare context_value jsonb;request_value jsonb;keys_value jsonb;actual_keys jsonb;
rows_value jsonb;actual_rows jsonb;adapter_value jsonb;collected_value jsonb;route_value jsonb;
begin
 if session_user<>'authenticator'or current_user<>'postgres'then raise exception 'review_claim_native_route_required'using errcode='42501';end if;
 if pg_catalog.pg_my_temp_schema()<>0 then raise exception 'review_claim_temp_namespace_forbidden'using errcode='42501';end if;
 context_value:=controlled_review_v3.protocol_claim_context(p_context);request_value:=context_value->'request';rows_value:=context_value->'rows';
 if context_value->>'path'<>'prepare'or request_value->>'operation_id'is distinct from p_operation_id::text
  or request_value->>'actor_id'is distinct from p_actor_id::text then raise exception 'review_claim_context_invalid'using errcode='23514';end if;
 keys_value:=controlled_review_v3.protocol_review_route_keys(jsonb_build_object('path','prepare','operation_id',p_operation_id,'route',context_value->'route','escalation_ids','{}'::jsonb));
 perform controlled_review_v3.protocol_assert_advisory(keys_value);
 perform controlled_review_v3.protocol_assert_relation_tail('prepare',rows_value);
 perform controlled_review_v3.protocol_acquire_advisory(keys_value,p_actor_id);perform controlled_review_v3.required();
 if not exists(select 1 from controlled_review_v3.operation_claims where operation_id=p_operation_id and actor_id=p_actor_id)
  or exists(select 1 from controlled_review_v3.cancellations where operation_id=p_operation_id)
  or exists(select 1 from controlled_review_v3.preparations where operation_id=p_operation_id)then
  raise exception 'review_history_integrity'using errcode='23514';end if;
 perform controlled_review_v3.read_clinical_dependencies_required();
 collected_value:=controlled_review_v3.collect_event_sources((request_value->>'event_id')::uuid);adapter_value:=collected_value->'adapter';
 route_value:=jsonb_build_object('target',adapter_value->'target','event_kind',adapter_value->'event_kind','site_id',adapter_value->'site_id',
  'native_family_dispense_id',adapter_value->'native_family_dispense_id','provenance_state',adapter_value->'provenance_state');
 actual_keys:=controlled_review_v3.protocol_review_keys(jsonb_build_object('path','prepare','operation_id',p_operation_id,'adapter',adapter_value,'escalation_ids','{}'::jsonb));
 actual_rows:=controlled_review_v3.protocol_review_rows(jsonb_build_object('path','prepare','operation_id',p_operation_id,'event_id',request_value->'event_id',
  'configuration_ids',jsonb_build_object('policy',request_value->'policy_id','read',request_value->'read_eligibility_id','review',request_value->'review_eligibility_id')));
 if route_value is distinct from context_value->'route'or actual_keys is distinct from keys_value
  or exists(select 1 from((select value-'local'from jsonb_array_elements(actual_rows)except select value-'local'from jsonb_array_elements(rows_value))
   union all(select value-'local'from jsonb_array_elements(rows_value)except select value-'local'from jsonb_array_elements(actual_rows)))as changed)
  or exists(select 1 from jsonb_array_elements(rows_value)as initial(value)join jsonb_array_elements(actual_rows)as current_rows(value)
   on initial.value->'relation'=current_rows.value->'relation'and initial.value->'key'=current_rows.value->'key'
   where initial.value->'local'='false'::jsonb and current_rows.value->'local'='true'::jsonb)then
  raise exception 'review_claim_context_stale'using errcode='23514';end if;
 -- Initial presence/local flags were independently reconciled before the first
 -- native claim INSERT. All same canonical keys/tables/unique gates remain held.
 -- Now KEY SHARE every present target, including self-inserted local rows: no
 -- new resource/stronger table mode and no external blocking target is added.
 perform controlled_review_v3.protocol_acquire_fk_tail('prepare',actual_rows,p_actor_id);
 perform controlled_review_v3.read_clinical_dependencies_required();
 perform controlled_review_v3.protocol_identity(p_actor_id);
 if pg_catalog.pg_my_temp_schema()<>0 then raise exception 'review_claim_temp_namespace_forbidden'using errcode='42501';end if;
 return jsonb_build_object('request',request_value,'adapter',adapter_value,'collected',collected_value);
end

controlled_review_v3.protocol_obligation.source:
declare row_value controlled_review_v3.obligations;result_value jsonb;
begin
 select *into row_value from controlled_review_v3.obligations where event_id=p_event_id;
 if not found then return null;end if;
 result_value:=jsonb_build_object('event_id',row_value.event_id,'product_id',row_value.product_id,'event_sequence',row_value.event_sequence::text,
  'meaning',row_value.meaning,'target',row_value.target,'target_hash',row_value.target_hash,'adapter',row_value.adapter,'historical',row_value.historical,
  'site_id',row_value.site_id,'due_at',case when row_value.due_at is null then null else controlled_review_v3.protocol_utc(row_value.due_at)end,
  'family_dispense_id',row_value.family_dispense_id);
 if row_value.binding_hash<>public.controlled_stock_hash(result_value)then raise exception 'review_history_integrity'using errcode='23514';end if;
 return result_value||jsonb_build_object('binding_hash',row_value.binding_hash);
end

declare event_value public.controlled_stock_events;adapter_value jsonb;anchor_value timestamptz;anchor_basis text;
 family_value jsonb;policy_value jsonb;references_value jsonb;historical_value jsonb;rule_value jsonb;
 deadline_value jsonb;reason_value text;choice_value text;family_id uuid;result_value jsonb;
begin
 select *into strict event_value from public.controlled_stock_events where id=p_event_id;
 adapter_value:=controlled_review_v3.adapt_event(p_event_id);
 if not event_value.secondary_review_required then return null;end if;
 anchor_basis:=case when event_value.basis='physical_record'then 'observed_at'else 'recorded_at'end;
 anchor_value:=case when anchor_basis='observed_at'then event_value.observed_at else event_value.recorded_at end;
 if anchor_value is null or not isfinite(anchor_value)then raise exception 'review_history_integrity'using errcode='23514';end if;
 historical_value:=jsonb_build_object('version',1,'selection_anchor',to_char(anchor_value at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
  'anchor_basis',anchor_basis,'policy_id',null,'policy_hash',null,'rule',null,'family_binding_hash',null,
  'calendar_id',null,'calendar_hash',null,'anchor_local_date',null,'selected_staffed_date',null,'due_at',null,
  'deadline_basis','historical_policy_unavailable','unavailable_reason',null,'routing_id',null,'routing_hash',null,'routing_snapshot',null);
 if adapter_value->>'site_id'is null then reason_value:='site_unproven';
 elsif event_value.event_kind in('record_native_dispense','record_native_pickup')then
  family_value:=controlled_review_v3.protocol_family_preview((adapter_value->>'native_family_dispense_id')::uuid,event_value.product_id);
  if family_value is null then reason_value:='missing_managed_dispense_family';
  else
   family_id:=(family_value->>'dispense_id')::uuid;
   historical_value:=historical_value||jsonb_build_object('family_binding_hash',family_value->'binding_hash');
   reason_value:=family_value#>>'{selection,unavailable_reason}';
   if family_value->'site_id'is distinct from adapter_value->'site_id'then
    raise exception 'review_history_integrity'using errcode='23514';end if;
   if family_value#>>'{selection,policy_id}'is not null then
    policy_value:=controlled_review_v3.protocol_configuration_record((family_value#>>'{selection,policy_id}')::uuid);
    if policy_value->'record_hash'is distinct from family_value#>'{selection,policy_hash}'then
     raise exception 'review_history_integrity'using errcode='23514';end if;
   end if;
   choice_value:=family_value#>>'{selection,native_deadline_kind}';
  end if;
 else policy_value:=controlled_review_v3.protocol_policy_at(event_value.product_id,(adapter_value->>'site_id')::uuid,anchor_value);
 end if;
 if policy_value is not null then
  rule_value:=policy_value#>array['body','rules',event_value.event_kind];
  if rule_value is null then raise exception 'review_history_integrity'using errcode='23514';end if;
  references_value:=controlled_review_v3.protocol_policy_references(policy_value);
  historical_value:=historical_value||jsonb_build_object('policy_id',policy_value->'id','policy_hash',policy_value->'record_hash','rule',rule_value,
   'calendar_id',references_value#>'{calendar,id}','calendar_hash',references_value#>'{calendar,record_hash}',
   'routing_id',references_value#>'{routing,id}','routing_hash',references_value#>'{routing,record_hash}',
   'routing_snapshot',controlled_review_v3.protocol_routing_snapshot(references_value->'routing'));
  if reason_value is null and policy_value->'enabled'is distinct from 'true'::jsonb then reason_value:='policy_disabled_at_anchor';end if;
 elsif reason_value is null then reason_value:='no_policy_at_anchor';end if;
 if reason_value is null then
  if event_value.event_kind in('record_native_dispense','record_native_pickup')and choice_value is not null and choice_value<>event_value.event_kind then
   historical_value:=historical_value||jsonb_build_object('deadline_basis','not_assigned','unavailable_reason','other_native_kind_selected');
  elsif rule_value->'enabled'is distinct from 'true'::jsonb or rule_value->>'deadline_mode'='not_configured'then
   historical_value:=historical_value||jsonb_build_object('deadline_basis','not_configured','unavailable_reason','kind_not_configured');
  else
   if rule_value->>'deadline_mode'<>'next_staffed_day_close'or references_value#>>'{calendar,id}'is null then
    raise exception 'review_history_integrity'using errcode='23514';end if;
   deadline_value:=controlled_review_v3.protocol_deadline(references_value->'calendar',anchor_value);
   historical_value:=historical_value||deadline_value;
  end if;
 else historical_value:=historical_value||jsonb_build_object('unavailable_reason',reason_value);end if;
 result_value:=jsonb_build_object('event_id',event_value.id,'product_id',event_value.product_id,'event_sequence',event_value.sequence::text,
  'meaning','independent_record_review_v1','target',adapter_value->'target','target_hash',public.controlled_stock_hash(adapter_value->'target'),
  'adapter',adapter_value,'historical',historical_value,'site_id',adapter_value->'site_id','due_at',historical_value->'due_at','family_dispense_id',family_id);
 return result_value||jsonb_build_object('binding_hash',public.controlled_stock_hash(result_value));
end

controlled_review_v3.protocol_operation_.source:
begin
 if jsonb_typeof(p_request)is distinct from 'object'or octet_length(p_request::text)>131072 then
  raise exception 'review_request_invalid'using errcode='23514';end if;
 perform public.controlled_stock_keys(p_request,array['actor_id','operation_id']);
 perform public.controlled_stock_uuid(p_request->'actor_id');
 perform public.controlled_stock_uuid(p_request->'operation_id');
 return p_request;
exception when check_violation or invalid_text_representation then
 raise exception 'review_request_invalid'using errcode='23514';
end

controlled_review_v3.protocol_owned_stat.source:
declare request_value jsonb:=controlled_review_v3.protocol_operation_request(p_request);actor_value uuid;operation_value uuid;
claim_value jsonb;preparation_value jsonb;decision_value jsonb;cancellation_value jsonb;receipt_value jsonb;data_value jsonb;
packet_value jsonb;adapter_value jsonb;policy_value jsonb;read_value jsonb;review_value jsonb;stream_value jsonb;at_value timestamptz;
authorization_value jsonb;reason_value text;message_value text;event_value uuid;response_value jsonb;keys_value jsonb;
begin
 actor_value:=(request_value->>'actor_id')::uuid;operation_value:=(request_value->>'operation_id')::uuid;
 perform controlled_review_v3.read_practice_preflight();
 perform controlled_review_v3.read_relation_preflight();
 perform controlled_review_v3.ops_admin_preflight();
 perform pg_advisory_xact_lock_shared(90271040,0);perform controlled_review_v3.required();
 perform controlled_review_v3.protocol_identity(actor_value);
 perform controlled_review_v3.protocol_acquire_advisory(jsonb_build_array(jsonb_build_object('class_id',90271101,
  'key','review-v3-operation:'||operation_value::text,'mode','exclusive')),actor_value);
 select to_jsonb(c)into claim_value from controlled_review_v3.operation_claims c where operation_id=operation_value;
 -- Identity failures occurred before this indistinguishable absent/other-owner
 -- projection. No ownership/session fields are exposed for a different actor.
 if claim_value is null or claim_value->'actor_id'is distinct from request_value->'actor_id'then
  perform controlled_review_v3.protocol_identity(actor_value);
  return jsonb_build_object('version',3,'state','not_found','data',jsonb_build_object('operation_id',operation_value));end if;
 select to_jsonb(p)into preparation_value from controlled_review_v3.preparations p where operation_id=operation_value;
 select to_jsonb(d)into decision_value from controlled_review_v3.decisions d where operation_id=operation_value;
 select to_jsonb(c)into cancellation_value from controlled_review_v3.cancellations c where operation_id=operation_value;
 if preparation_value is not null then
  perform controlled_review_v3.protocol_validate_retained_packet(preparation_value);
  if preparation_value->'actor_id'is distinct from claim_value->'actor_id'
   or(claim_value->>'claimed_at')::timestamptz>(preparation_value->>'created_at')::timestamptz then
   raise exception 'review_history_integrity'using errcode='23514';end if;
 end if;
 -- Own SAVED wins without current roster/TTL requirements, but only after
 -- current real identity/session and exact retained receipt equality.
 if decision_value is not null then
  if preparation_value is null or cancellation_value is not null then raise exception 'review_history_integrity'using errcode='23514';end if;
  receipt_value:=controlled_review_v3.protocol_receipt_from_rows(preparation_value,decision_value);
  if decision_value->'receipt'is distinct from receipt_value then raise exception 'review_history_integrity'using errcode='23514';end if;
  perform controlled_review_v3.protocol_identity(actor_value);
  perform controlled_review_v3.protocol_identity(actor_value);
  return jsonb_build_object('version',3,'state','saved','data',jsonb_build_object('operation_id',operation_value,
   'receipt',controlled_review_v3.protocol_saved_commitment(receipt_value)));
 end if;
 if cancellation_value is not null then
  data_value:=controlled_review_v3.protocol_cancellation_data(claim_value,coalesce(preparation_value,'null'::jsonb),cancellation_value);
  perform controlled_review_v3.protocol_identity(actor_value);
  perform controlled_review_v3.protocol_identity(actor_value);
  return jsonb_build_object('version',3,'state','cancelled','data',data_value);
 end if;
 if preparation_value is null then raise exception 'review_history_integrity'using errcode='23514';end if;
 event_value:=(preparation_value->>'event_id')::uuid;
 keys_value:='[]'::jsonb;
 if preparation_value#>>'{packet,adapter,native_family_dispense_id}'is not null then
  keys_value:=keys_value||jsonb_build_array(jsonb_build_object('class_id',90271102,'key','review-v3-family:'||
   (preparation_value#>>'{packet,adapter,native_family_dispense_id}'),'mode','exclusive'));end if;
 keys_value:=keys_value||jsonb_build_array(jsonb_build_object('class_id',90271103,'key','review-v3-event:'||event_value::text,'mode','exclusive'));
 perform controlled_review_v3.protocol_acquire_advisory(keys_value,actor_value);
 if exists(select 1 from controlled_review_v3.decisions where event_id=event_value)then
  perform controlled_review_v3.protocol_identity(actor_value);
  return jsonb_build_object('version',3,'state','superseded','data',jsonb_build_object('operation_id',operation_value,'transport_digest',preparation_value->'transport_digest'));end if;
 at_value:=clock_timestamp();
 if at_value>=(preparation_value->>'expires_at')::timestamptz then
  perform controlled_review_v3.protocol_identity(actor_value);
  return jsonb_build_object('version',3,'state','expired','data',jsonb_build_object('operation_id',operation_value,
   'transport_digest',preparation_value->'transport_digest','created_at',controlled_review_v3.protocol_utc((preparation_value->>'created_at')::timestamptz),
   'expires_at',controlled_review_v3.protocol_utc((preparation_value->>'expires_at')::timestamptz)));end if;
 adapter_value:=preparation_value#>'{packet,adapter}';
 stream_value:=jsonb_build_object('kind','policy','product_id',adapter_value#>'{target,product_id}','site_id',adapter_value->'site_id','event_kind',null,'capability',null);
 policy_value:=controlled_review_v3.protocol_select_configuration(jsonb_build_object('stream_key',stream_value,'at',controlled_review_v3.protocol_utc(at_value)));
 stream_value:=stream_value||jsonb_build_object('kind','eligibility','event_kind',adapter_value->'event_kind','capability','read');
 read_value:=controlled_review_v3.protocol_select_configuration(jsonb_build_object('stream_key',stream_value,'at',controlled_review_v3.protocol_utc(at_value)));
 stream_value:=stream_value||jsonb_build_object('capability','review');
 review_value:=controlled_review_v3.protocol_select_configuration(jsonb_build_object('stream_key',stream_value,'at',controlled_review_v3.protocol_utc(at_value)));
 if policy_value->'id'is distinct from preparation_value->'policy_id'then reason_value:='policy_changed';
 elsif read_value->'id'is distinct from preparation_value->'read_eligibility_id'then reason_value:='read_eligibility_changed';
 elsif review_value->'id'is distinct from preparation_value->'review_eligibility_id'then reason_value:='review_eligibility_changed';end if;
 if reason_value is not null then perform controlled_review_v3.protocol_identity(actor_value);
  return jsonb_build_object('version',3,'state','stale','data',jsonb_build_object('operation_id',operation_value,
  'transport_digest',preparation_value->'transport_digest','reason',reason_value));end if;
 if controlled_review_v3.protocol_live_member(read_value,actor_value,'read')is null then reason_value:='no_read_eligibility';
 elsif controlled_review_v3.protocol_live_member(review_value,actor_value,'review')is null then reason_value:='no_review_eligibility';end if;
 if reason_value is not null then perform controlled_review_v3.protocol_identity(actor_value);
  return jsonb_build_object('version',3,'state','blocked','data',jsonb_build_object('operation_id',operation_value,
  'transport_digest',preparation_value->'transport_digest','reason',reason_value));end if;
