controlled_review_v3.protocol_review_row.source:
declare path_value text;event_kind_value text;operation_value uuid;event_value uuid;family_value uuid;obligation_value controlled_review_v3.obligations;
rows_value jsonb:='[]'::jsonb;field text;id_value uuid;claim_exists boolean;obligation_exists boolean;family_exists boolean;
begin
 perform public.controlled_stock_keys(p_request,array['path','operation_id','event_id','configuration_ids']);
 if jsonb_typeof(p_request->'path')is distinct from 'string'or p_request->>'path'not in('prepare','decision','prepared_cancel','eventless_cancel')then
  raise exception 'review_lock_plan_invalid'using errcode='23514';end if;
 path_value:=p_request->>'path';operation_value:=public.controlled_stock_uuid(p_request->'operation_id');
 if path_value='eventless_cancel'then
  if p_request->'event_id'is distinct from 'null'::jsonb or p_request->'configuration_ids'is distinct from '{}'::jsonb then
   raise exception 'review_lock_plan_invalid'using errcode='23514';end if;
  if exists(select 1 from controlled_review_v3.preparations where operation_id=operation_value)then
   raise exception 'review_lock_plan_stale'using errcode='PT409';end if;
  claim_exists:=exists(select 1 from controlled_review_v3.operation_claims where operation_id=operation_value);
  return controlled_review_v3.protocol_row_targets(jsonb_build_array(jsonb_build_object('relation','controlled_review_v3.operation_claims',
   'key',jsonb_build_object('operation_id',operation_value),'local',not claim_exists)));
 end if;
 event_value:=public.controlled_stock_uuid(p_request->'event_id');
 if path_value='decision'then
  if p_request->'configuration_ids'is distinct from '{}'::jsonb then raise exception 'review_lock_plan_invalid'using errcode='23514';end if;
  return controlled_review_v3.protocol_row_targets(jsonb_build_array(
   jsonb_build_object('relation','controlled_review_v3.obligations','key',jsonb_build_object('event_id',event_value),'local',false),
   jsonb_build_object('relation','controlled_review_v3.preparations','key',jsonb_build_object('operation_id',operation_value),'local',false)));
 end if;
 claim_exists:=exists(select 1 from controlled_review_v3.operation_claims where operation_id=operation_value);
 rows_value:=rows_value||jsonb_build_array(jsonb_build_object('relation','controlled_review_v3.operation_claims','key',jsonb_build_object('operation_id',operation_value),'local',not claim_exists));
 if path_value='prepared_cancel'then
  if not claim_exists or p_request->'configuration_ids'is distinct from '{}'::jsonb then raise exception 'review_history_integrity'using errcode='23514';end if;
  return controlled_review_v3.protocol_row_targets(rows_value);
 end if;
 perform public.controlled_stock_keys(p_request->'configuration_ids',array['policy','read','review']);
 for field in select unnest(array['policy','read','review'])loop
  id_value:=public.controlled_stock_uuid(p_request#>array['configuration_ids',field]);
  rows_value:=rows_value||jsonb_build_array(jsonb_build_object('relation','controlled_review_v3.configuration','key',jsonb_build_object('id',id_value),'local',false));
 end loop;
 select *into obligation_value from controlled_review_v3.obligations where event_id=event_value;
 obligation_exists:=found;
 rows_value:=rows_value||jsonb_build_array(jsonb_build_object('relation','controlled_review_v3.obligations','key',jsonb_build_object('event_id',event_value),'local',not obligation_exists));
 -- Full canonical key union is unconditional, including parent and managed
 -- family even when an obligation already exists. Only initial presence flags
 -- vary; no xmin/subtransaction/epoch ownership inference is used.
  rows_value:=rows_value||jsonb_build_array(jsonb_build_object('relation','public.controlled_stock_events','key',jsonb_build_object('id',event_value),'local',false));
  -- Preview is recomputed only while earlier immutable/family/event gates are
  -- held by the caller. It never assumes adapter family equals managed family.
  select event_kind into strict event_kind_value from public.controlled_stock_events where id=event_value;
  -- Source-exact family branch: obligation_preview only assigns family_id for
  -- native dispense/pickup. Other20 kinds cannot yield a family; do not rebuild
  -- their entire immutable adapter merely to rediscover SQL NULL here.
  if event_kind_value in('record_native_dispense','record_native_pickup')then
   family_value:=(controlled_review_v3.protocol_obligation_preview(event_value)->>'family_dispense_id')::uuid;
  else family_value:=null;end if;
  if family_value is not null then
   family_exists:=exists(select 1 from controlled_review_v3.families where dispense_id=family_value);
   rows_value:=rows_value||jsonb_build_array(jsonb_build_object('relation','controlled_review_v3.families','key',jsonb_build_object('dispense_id',family_value),'local',not family_exists));
  end if;
 return controlled_review_v3.protocol_row_targets(rows_value);
end

controlled_review_v3.protocol_review_sta.source:
declare required_value boolean;adapter_value jsonb;authorization_value jsonb;obligation_value jsonb;historical_value jsonb;
 terminal_value jsonb;as_of_value timestamptz;due_value timestamptz;terminal_time timestamptz;result_value jsonb;
 review_value text;deadline_value text;signing_value text;reason_value text;basis_value text;unavailable_value text;
begin
 if jsonb_typeof(p_request)is distinct from 'object'or octet_length(p_request::text)>1048576 then
  raise exception 'review_history_integrity'using errcode='23514';end if;
 perform public.controlled_stock_keys(p_request,array['secondary_review_required','actor_id','original_actor_id','adapter','current_authorization','current_policy_status','terminal_decision','as_of','obligation']);
 perform public.controlled_stock_uuid(p_request->'actor_id');perform public.controlled_stock_uuid(p_request->'original_actor_id');
 if jsonb_typeof(p_request->'secondary_review_required')is distinct from 'boolean'
  or jsonb_typeof(p_request->'current_policy_status')is distinct from 'string'
  or p_request->>'current_policy_status'not in('missing','disabled','enabled')then
  raise exception 'review_history_integrity'using errcode='23514';end if;
 required_value:=(p_request->>'secondary_review_required')::boolean;adapter_value:=p_request->'adapter';
 authorization_value:=p_request->'current_authorization';terminal_value:=p_request->'terminal_decision';
 obligation_value:=p_request->'obligation';as_of_value:=controlled_review_v3.protocol_instant(p_request->'as_of');
 perform public.controlled_stock_keys(authorization_value,array['policy','read','review']);
 if adapter_value#>'{target,original_actor_id}'is distinct from p_request->'original_actor_id'then
  raise exception 'review_history_integrity'using errcode='23514';end if;
 if not required_value then
  if obligation_value is distinct from 'null'::jsonb or terminal_value is distinct from 'null'::jsonb then
   raise exception 'review_history_integrity'using errcode='23514';end if;
  return jsonb_build_object('review_state','not_required','deadline_state','not_required','deadline_basis','not_required',
   'due_at',null,'unavailable_reason',null,'signing_state','blocked','signing_reason','not_required');
 end if;
 if jsonb_typeof(obligation_value)is distinct from 'object'or obligation_value->'adapter'is distinct from adapter_value
  or jsonb_typeof(obligation_value->'historical')is distinct from 'object'then
  raise exception 'review_history_integrity'using errcode='23514';end if;
 historical_value:=obligation_value->'historical';basis_value:=historical_value->>'deadline_basis';unavailable_value:=historical_value->>'unavailable_reason';
 if basis_value is null or basis_value not in('configured','not_configured','not_assigned','historical_policy_unavailable','calendar_unavailable')
  or obligation_value->'due_at'is distinct from historical_value->'due_at'then
  raise exception 'review_history_integrity'using errcode='23514';end if;
 if historical_value->'due_at'is distinct from 'null'::jsonb then due_value:=controlled_review_v3.protocol_instant(historical_value->'due_at');end if;
 if(basis_value='configured')is distinct from(due_value is not null)or(due_value is not null and unavailable_value is not null)then
  raise exception 'review_history_integrity'using errcode='23514';end if;
 review_value:='awaiting_review';signing_value:='blocked';
 if terminal_value is distinct from 'null'::jsonb then
  perform public.controlled_stock_keys(terminal_value,array['decision','recorded_at']);
  if jsonb_typeof(terminal_value->'decision')is distinct from 'string'or terminal_value->>'decision'not in('approve','reject')then
   raise exception 'review_history_integrity'using errcode='23514';end if;
  terminal_time:=controlled_review_v3.protocol_instant(terminal_value->'recorded_at');
  review_value:=case when terminal_value->>'decision'='approve'then 'approved'else 'rejected'end;
  deadline_value:=case when due_value is null then 'completed_time_unassessable'
   when terminal_time<=due_value then 'completed_on_time'else 'completed_late'end;
  signing_value:='terminal';reason_value:='terminal_outcome';
 else
  deadline_value:=case when due_value is null then basis_value when as_of_value>due_value then 'overdue'else 'not_due'end;
  if adapter_value->'provenance_state'is distinct from '"supported"'::jsonb then reason_value:='unsupported_provenance';
  elsif p_request->'actor_id'=p_request->'original_actor_id'then reason_value:='own_record';
  elsif p_request->>'current_policy_status'='missing'then reason_value:='no_current_policy';
  elsif p_request->>'current_policy_status'='disabled'or authorization_value->'policy'='null'::jsonb then reason_value:='disabled_current_policy';
  elsif authorization_value->'read'='null'::jsonb then reason_value:='no_read_eligibility';
  elsif authorization_value->'review'='null'::jsonb then reason_value:='no_review_eligibility';
  else signing_value:='available';reason_value:='none';end if;
 end if;
 return jsonb_build_object('review_state',review_value,'deadline_state',deadline_value,'deadline_basis',basis_value,
  'due_at',historical_value->'due_at','unavailable_reason',historical_value->'unavailable_reason','signing_state',signing_value,'signing_reason',reason_value);
end

controlled_review_v3.protocol_routing_sn.source:
declare record_value jsonb;
begin
 if p_record is null or p_record='null'::jsonb then return null;end if;
 record_value:=controlled_review_v3.validate_configuration_record(p_record);
 if record_value->'kind'is distinct from '"routing"'::jsonb then
  raise exception 'review_history_integrity'using errcode='23514';end if;
 return jsonb_build_object('version',1,'id',record_value->'id','record_hash',record_value->'record_hash',
  'enabled',record_value->'enabled','members',record_value#>'{body,members}');
end

controlled_review_v3.protocol_row_target.source:
declare item jsonb;result_value jsonb;
begin
 if jsonb_typeof(p_rows)is distinct from 'array'or jsonb_array_length(p_rows)>64
  or octet_length(p_rows::text)>32768 then raise exception 'review_lock_plan_invalid'using errcode='23514';end if;
 for item in select value from jsonb_array_elements(p_rows)loop
  perform public.controlled_stock_keys(item,array['relation','key','local']);
  if jsonb_typeof(item->'relation')is distinct from 'string'or jsonb_typeof(item->'local')is distinct from 'boolean'then
   raise exception 'review_lock_plan_invalid'using errcode='23514';end if;
  case item->>'relation'
  when 'controlled_review_v3.configuration'then perform public.controlled_stock_keys(item->'key',array['id']);perform public.controlled_stock_uuid(item#>'{key,id}');
  when 'controlled_review_v3.publications'then perform public.controlled_stock_keys(item->'key',array['operation_id']);perform public.controlled_stock_uuid(item#>'{key,operation_id}');
  when 'controlled_review_v3.operation_claims'then perform public.controlled_stock_keys(item->'key',array['operation_id']);perform public.controlled_stock_uuid(item#>'{key,operation_id}');
  when 'controlled_review_v3.families'then perform public.controlled_stock_keys(item->'key',array['dispense_id']);perform public.controlled_stock_uuid(item#>'{key,dispense_id}');
  when 'controlled_review_v3.obligations'then perform public.controlled_stock_keys(item->'key',array['event_id']);perform public.controlled_stock_uuid(item#>'{key,event_id}');
  when 'controlled_review_v3.preparations'then perform public.controlled_stock_keys(item->'key',array['operation_id']);perform public.controlled_stock_uuid(item#>'{key,operation_id}');
  when 'controlled_review_v3.escalations'then perform public.controlled_stock_keys(item->'key',array['id']);perform public.controlled_stock_uuid(item#>'{key,id}');
  when 'public.controlled_stock_events'then perform public.controlled_stock_keys(item->'key',array['id']);perform public.controlled_stock_uuid(item#>'{key,id}');
  else raise exception 'review_lock_plan_invalid'using errcode='23514';end case;
 end loop;
 if exists(select 1 from jsonb_array_elements(p_rows)as a(value)join jsonb_array_elements(p_rows)as b(value)
  on a.value->'relation'=b.value->'relation'and a.value->'key'=b.value->'key'
  where a.value->'local'is distinct from b.value->'local')then
  raise exception 'review_lock_plan_invalid'using errcode='23514';end if;
 select coalesce(jsonb_agg(value order by value->>'relation'collate "C",(value->'key')::text collate "C"),'[]'::jsonb)
 into result_value from(select distinct value from jsonb_array_elements(p_rows))as deduplicated;
 return result_value;
end

controlled_review_v3.protocol_saved_comm.source:
declare field_name text;recorded_text text;recorded_value timestamp;
begin
 if jsonb_typeof(p_receipt)is distinct from 'object'or octet_length(p_receipt::text)>131072 then
  raise exception 'review_receipt_invalid'using errcode='23514';end if;
 perform public.controlled_stock_keys(p_receipt,array['version','operation_id','event_id','meaning','meaning_text','meaning_version','target','target_hash','adapter_id','site_basis','site_id','request_hash','transport_digest','packet_hash','obligation_binding_hash','historical','policy_id','policy_hash','read_eligibility_id','read_eligibility_hash','review_eligibility_id','review_eligibility_hash','actor_id','session_id','actor_name','decision','reason','recorded_at','review_state','deadline_state']);
 if jsonb_typeof(p_receipt->'version')is distinct from 'number'or p_receipt->>'version'<>'3'
  or jsonb_typeof(p_receipt->'meaning_version')is distinct from 'number'or p_receipt->>'meaning_version'<>'1'
  or p_receipt->'meaning'is distinct from '"independent_record_review_v1"'::jsonb
  or p_receipt->'meaning_text'is distinct from '"Independent record review; no claim of personal physical observation."'::jsonb then
  raise exception 'review_receipt_invalid'using errcode='23514';end if;
 foreach field_name in array array['operation_id','event_id','site_id','policy_id','read_eligibility_id','review_eligibility_id','actor_id','session_id']loop
  perform public.controlled_stock_uuid(p_receipt->field_name);end loop;
 foreach field_name in array array['target_hash','request_hash','transport_digest','packet_hash','obligation_binding_hash','policy_hash','read_eligibility_hash','review_eligibility_hash']loop
  if jsonb_typeof(p_receipt->field_name)is distinct from 'string'or(p_receipt->>field_name)!~'^[0-9a-f]{64}$'then
   raise exception 'review_receipt_invalid'using errcode='23514';end if;end loop;
 perform public.controlled_stock_text(p_receipt->'actor_name',200,false);
 perform public.controlled_stock_text(p_receipt->'reason',4000,true);
 if jsonb_typeof(p_receipt->'decision')is distinct from 'string'or p_receipt->>'decision'not in('approve','reject')
  or jsonb_typeof(p_receipt->'review_state')is distinct from 'string'
  or p_receipt->>'review_state'is distinct from (case p_receipt->>'decision'when 'approve'then 'approved'else 'rejected'end)
  or jsonb_typeof(p_receipt->'deadline_state')is distinct from 'string'
  or p_receipt->>'deadline_state'not in('completed_on_time','completed_late','completed_time_unassessable')
  or jsonb_typeof(p_receipt->'adapter_id')is distinct from 'string'
  or p_receipt->>'adapter_id'not in('movement_v1','treatment_v1','anesthesia_v1','dispense_v1','pickup_v1','return_v1','return_v2','retraction_v1','discrepancy_v1','annotation_v1')
  or jsonb_typeof(p_receipt->'site_basis')is distinct from 'string'
  or p_receipt->>'site_basis'not in('event_transitions','managed_dispense','managed_pickup','managed_return','opening_custody_site')
  or jsonb_typeof(p_receipt->'target')is distinct from 'object'or jsonb_typeof(p_receipt->'historical')is distinct from 'object'
  or jsonb_typeof(p_receipt->'recorded_at')is distinct from 'string'then
  raise exception 'review_receipt_invalid'using errcode='23514';end if;
 recorded_text:=p_receipt->>'recorded_at';
 if recorded_text!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}Z$'then
  raise exception 'review_receipt_invalid'using errcode='23514';end if;
 recorded_value:=left(recorded_text,26)::timestamp;
 if not isfinite(recorded_value)or recorded_value<timestamp '2026-01-01'or recorded_value>=timestamp '2101-01-01'
  or to_char(recorded_value,'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')<>recorded_text then
  raise exception 'review_receipt_invalid'using errcode='23514';end if;
 -- Only a minimal projection. Caller's reciprocal history validator must first
 -- prove this is the exact stored receipt for the owned accepted preparation.
 return jsonb_build_object('version',3,'actor_id',p_receipt->'actor_id','operation_id',p_receipt->'operation_id',
  'transport_digest',p_receipt->'transport_digest','decision',p_receipt->'decision','recorded_at',p_receipt->'recorded_at',
  'receipt_hash',public.controlled_stock_hash(p_receipt));
exception when check_violation or invalid_text_representation or invalid_datetime_format or datetime_field_overflow then
 raise exception 'review_receipt_invalid'using errcode='23514';
end

controlled_review_v3.protocol_select_con.source:
declare stream_value jsonb;at_value timestamptz;selected_id uuid;
begin
 if jsonb_typeof(p_request)is distinct from 'object'or octet_length(p_request::text)>8192 then
  raise exception 'review_selection_invalid'using errcode='23514';end if;
 perform public.controlled_stock_keys(p_request,array['stream_key','at']);
 stream_value:=controlled_review_v3.protocol_stream_key(p_request->'stream_key');
 at_value:=controlled_review_v3.protocol_instant(p_request->'at');
 if stream_value->>'kind'='policy'then
  select id into selected_id from controlled_review_v3.configuration
   where stream_key=stream_value and effective_from<=at_value and published_at<=at_value
   order by effective_from desc,version desc limit 1;
 else
  select id into selected_id from controlled_review_v3.configuration
   where stream_key=stream_value and published_at<=at_value order by version desc limit 1;
 end if;
 if selected_id is null then return null;end if;
 -- No enabled filter: a disabled newest/selected record suppresses prior rows.
 return controlled_review_v3.protocol_configuration_record(selected_id);
end

controlled_review_v3.protocol_signing_pa.source:
declare request_value jsonb:=controlled_review_v3.protocol_request(p_request);authorization_value jsonb;
begin
 authorization_value:=p_packet->'current_authorization';
 if p_packet#>'{adapter,provenance_state}'is distinct from '"supported"'::jsonb then
  raise exception 'unsupported_provenance'using errcode='23514';end if;
 if p_packet#>'{event,secondary_review_required}'is distinct from 'true'::jsonb then
  raise exception 'not_required'using errcode='23514';end if;
 if p_packet#>'{target,original_actor_id}'=request_value->'actor_id'then raise exception 'own_record'using errcode='23514';end if;
 if authorization_value->'policy'is not distinct from 'null'::jsonb then raise exception 'no_current_policy'using errcode='PT409';end if;
 if authorization_value#>'{policy,rule,enabled}'is distinct from 'true'::jsonb then raise exception 'disabled_current_policy'using errcode='PT409';end if;
 if authorization_value->'read'is not distinct from 'null'::jsonb then raise exception 'no_read_eligibility'using errcode='42501';end if;
 if authorization_value->'review'is not distinct from 'null'::jsonb then raise exception 'no_review_eligibility'using errcode='42501';end if;
 if authorization_value#>'{policy,id}'is distinct from request_value->'policy_id'then raise exception 'policy_changed'using errcode='PT409';end if;
 if authorization_value#>'{read,id}'is distinct from request_value->'read_eligibility_id'then raise exception 'read_eligibility_changed'using errcode='PT409';end if;
 if authorization_value#>'{review,id}'is distinct from request_value->'review_eligibility_id'then raise exception 'review_eligibility_changed'using errcode='PT409';end if;
 if p_packet#>'{target,event_id}'is distinct from request_value->'event_id'or p_packet#>'{obligation,event_id}'is distinct from request_value->'event_id'then
  raise exception 'review_history_integrity'using errcode='23514';end if;
 return p_packet;
end

controlled_review_v3.protocol_stream_key.source:
declare kind_value text;capability_value text;
begin
 if jsonb_typeof(p_request)is distinct from 'object'or octet_length(p_request::text)>4096 then
  raise exception 'review_stream_invalid'using errcode='23514';end if;
 perform public.controlled_stock_keys(p_request,array['kind','product_id','site_id','event_kind','capability']);
 perform public.controlled_stock_uuid(p_request->'product_id');
 if jsonb_typeof(p_request->'kind')is distinct from 'string'then
  raise exception 'review_stream_invalid'using errcode='23514';end if;
 kind_value:=p_request->>'kind';
 if kind_value='administration'then
  if p_request->'site_id'is distinct from 'null'::jsonb or p_request->'event_kind'is distinct from 'null'::jsonb
   or p_request->'capability'is distinct from 'null'::jsonb then
   raise exception 'review_stream_invalid'using errcode='23514';end if;
 elsif kind_value in('policy','calendar','routing')then
  perform public.controlled_stock_uuid(p_request->'site_id');
  if p_request->'event_kind'is distinct from 'null'::jsonb or p_request->'capability'is distinct from 'null'::jsonb then
   raise exception 'review_stream_invalid'using errcode='23514';end if;
 elsif kind_value='eligibility'then
  if jsonb_typeof(p_request->'capability')is distinct from 'string'then
   raise exception 'review_stream_invalid'using errcode='23514';end if;
  capability_value:=p_request->>'capability';
  if capability_value='exception_read'then
   if p_request->'site_id'is distinct from 'null'::jsonb or p_request->'event_kind'is distinct from 'null'::jsonb then
    raise exception 'review_stream_invalid'using errcode='23514';end if;
  elsif capability_value in('read','review')then
   perform public.controlled_stock_uuid(p_request->'site_id');
   if jsonb_typeof(p_request->'event_kind')is distinct from 'string'or p_request->>'event_kind'not in(
    'receive_inventory','adjust_inventory','record_patient_treatment','record_anesthesia_drug_administration',
    'record_native_dispense','record_native_pickup','record_native_dispense_return:intake','record_native_dispense_return:dispose','record_native_dispense_return:restock',
    'record_native_dispense_return_v2:intake','record_native_dispense_return_v2:dispose','record_native_dispense_return_v2:restock',
    'record_native_dispense_return_v2:retract_intake','record_native_dispense_return_v2:retract_disposal','record_native_dispense_return_v2:retract_restock',
    'record_native_return_discrepancy:report','record_native_return_discrepancy:note','record_native_return_discrepancy:resolve_corrected','record_native_return_discrepancy:resolve_confirmed_original',
    'append_native_dispense_correction:clinical_annotation','append_native_dispense_correction:operational_annotation','append_native_dispense_correction:pickup_amendment')then
    raise exception 'review_stream_invalid'using errcode='23514';end if;
  else raise exception 'review_stream_invalid'using errcode='23514';end if;
 else raise exception 'review_stream_invalid'using errcode='23514';end if;
 return p_request;
exception when check_violation then
 raise exception 'review_stream_invalid'using errcode='23514';
end

controlled_review_v3.protocol_terminal_l.source:
declare family_value jsonb;product_value uuid;
begin
 if TG_OP<>'INSERT'or TG_TABLE_SCHEMA<>'controlled_review_v3'then raise exception 'review_insert_invalid'using errcode='23514';end if;
 -- These are the alreadyheld dependencies of the mutation tail. This observer
 -- adds no new lock resource, row lock, write, DDL or current permission.
 -- Frozen collectors may reenter the alreadyheld shared practice barrier.
 perform controlled_review_v3.required();
 if TG_TABLE_NAME in('operation_claims','preparations','decisions','cancellations')then
  perform controlled_review_v3.protocol_validate_operation(NEW.operation_id);
 elsif TG_TABLE_NAME='escalations'then
  if NEW.reason='overdue'then
   perform controlled_review_v3.ops_validate_overdue(to_jsonb(NEW));
   if NEW.evidence->'terminal_operation_id'<>'null'::jsonb then perform controlled_review_v3.protocol_validate_operation((NEW.evidence->>'terminal_operation_id')::uuid);end if;
  elsif NEW.reason='rejected'then
   perform controlled_review_v3.protocol_validate_rejection(to_jsonb(NEW));
   perform controlled_review_v3.protocol_validate_operation((NEW.evidence->>'decision_operation_id')::uuid);
  else perform controlled_review_v3.ops_validate_worker_source(to_jsonb(NEW));end if;
 elsif TG_TABLE_NAME='obligations'then
  perform controlled_review_v3.ops_validate_mutation_obligation(NEW.event_id);
  perform controlled_review_v3.protocol_utc(NEW.materialized_at);
 elsif TG_TABLE_NAME='families'then
     family_value:=controlled_review_v3.protocol_family_dto(NEW.dispense_id);
  if family_value is null or family_value is distinct from controlled_review_v3.protocol_family_preview(NEW.dispense_id,NEW.product_id)
   or not exists(select 1 from controlled_review_v3.obligations where family_dispense_id=NEW.dispense_id)then
   raise exception 'review_history_integrity'using errcode='23514';end if;
  perform controlled_review_v3.protocol_utc(NEW.materialized_at);
 else raise exception 'review_lifecycle_table_not_implemented'using errcode='0A000';end if;
 return null;
end

controlled_review_v3.protocol_terminal_p.source:
begin
 if TG_OP<>'INSERT'or TG_TABLE_SCHEMA<>'controlled_review_v3'or TG_TABLE_NAME not in('configuration','publications')then raise exception 'review_insert_invalid'using errcode='23514';end if;
 perform controlled_review_v3.required();
 if TG_TABLE_NAME='configuration'then perform controlled_review_v3.protocol_validate_publication_record(NEW.id);
 else perform controlled_review_v3.protocol_validate_publication_record(NEW.record_id);end if;
 return null;
end

controlled_review_v3.protocol_transport_.source:
declare request_value jsonb:=controlled_review_v3.protocol_request(p_request);field_name text;field_bytes bytea;
 framed bytea:=convert_to(E'lrv-record-review-request-v3\n','UTF8');
begin
 foreach field_name in array array['actor_id','operation_id','event_id','policy_id','read_eligibility_id','review_eligibility_id','decision','reason']loop
  field_bytes:=convert_to(request_value->>field_name,'UTF8');
  framed:=framed||convert_to(octet_length(field_bytes)::text||':','UTF8')||field_bytes;
 end loop;
 return encode(sha256(framed),'hex');
end

controlled_review_v3.protocol_utc(p_valu.source:
begin
 if p_value is null or not isfinite(p_value)or p_value<timestamptz '2026-01-01 00:00:00Z'
  or p_value>=timestamptz '2101-01-01 00:00:00Z'then
  raise exception 'review_timestamp_invalid'using errcode='23514';end if;
 return to_char(p_value at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"');
end

controlled_review_v3.protocol_validate_o.source:
declare expected_value jsonb;actual_value jsonb;family_value jsonb;maintenance_value controlled_review_v3.materializations;
begin
 select *into maintenance_value from controlled_review_v3.materializations where event_id=p_event_id and product_id=(select product_id from controlled_review_v3.obligations where event_id=p_event_id)order by operation_id limit 1;
 if found then perform controlled_review_v3.ops_validate_materialization(to_jsonb(maintenance_value));return;end if;
 expected_value:=controlled_review_v3.protocol_obligation_preview(p_event_id);actual_value:=controlled_review_v3.protocol_obligation_dto(p_event_id);
 if expected_value is null or actual_value is distinct from expected_value then raise exception 'review_history_integrity'using errcode='23514';end if;
 if actual_value->>'family_dispense_id'is not null then
  family_value:=controlled_review_v3.protocol_family_dto((actual_value->>'family_dispense_id')::uuid);
  if family_value is null or family_value is distinct from controlled_review_v3.protocol_family_preview((actual_value->>'family_dispense_id')::uuid,(actual_value->>'product_id')::uuid)then
   raise exception 'review_history_integrity'using errcode='23514';end if;
 end if;
 -- This limited lifecycle candidate has no general worker materialization route.
 -- It refuses an orphan obligation rather than claim full maintenance support.
 if not exists(select 1 from controlled_review_v3.preparations where event_id=p_event_id)then
  raise exception 'review_lifecycle_obligation_unpaired'using errcode='23514';end if;
end

declare claim_value controlled_review_v3.operation_claims;preparation_value controlled_review_v3.preparations;
decision_value controlled_review_v3.decisions;cancellation_value controlled_review_v3.cancellations;
preparation_exists boolean;decision_exists boolean;cancellation_exists boolean;receipt_value jsonb;rejection_value controlled_review_v3.escalations;overdue_value controlled_review_v3.escalations;
begin
 select *into strict claim_value from controlled_review_v3.operation_claims where operation_id=p_operation_id;
 perform public.controlled_stock_uuid(to_jsonb(claim_value.operation_id));perform public.controlled_stock_uuid(to_jsonb(claim_value.actor_id));
 perform controlled_review_v3.protocol_utc(claim_value.claimed_at);
 select *into preparation_value from controlled_review_v3.preparations where operation_id=p_operation_id;preparation_exists:=found;
 select *into decision_value from controlled_review_v3.decisions where operation_id=p_operation_id;decision_exists:=found;
 select *into cancellation_value from controlled_review_v3.cancellations where operation_id=p_operation_id;cancellation_exists:=found;
 if not preparation_exists and not cancellation_exists or decision_exists and cancellation_exists
  or decision_exists and not preparation_exists then raise exception 'review_history_integrity'using errcode='23514';end if;
 if preparation_exists then
  if preparation_value.actor_id<>claim_value.actor_id or preparation_value.created_at<claim_value.claimed_at then
   raise exception 'review_history_integrity'using errcode='23514';end if;
  perform controlled_review_v3.read_clinical_dependencies_required();
  perform controlled_review_v3.read_validate_retained_packet(to_jsonb(preparation_value),controlled_review_v3.read_scalar_base(controlled_review_v3.collect_event_sources(preparation_value.event_id)));
 end if;
 if decision_exists then
  receipt_value:=controlled_review_v3.protocol_receipt_from_rows(to_jsonb(preparation_value),to_jsonb(decision_value));
  if receipt_value is distinct from decision_value.receipt then raise exception 'review_history_integrity'using errcode='23514';end if;
  if receipt_value->>'deadline_state'='completed_late'then
   select *into strict overdue_value from controlled_review_v3.escalations where event_id=decision_value.event_id and reason='overdue';
   perform controlled_review_v3.ops_validate_overdue(to_jsonb(overdue_value));end if;
  if decision_value.decision='reject'then
   select *into strict rejection_value from controlled_review_v3.escalations where event_id=decision_value.event_id and reason='rejected';
   if rejection_value.evidence->>'decision_operation_id'is distinct from decision_value.operation_id::text then raise exception 'review_rejection_history_invalid'using errcode='23514';end if;
   perform controlled_review_v3.protocol_validate_rejection(to_jsonb(rejection_value));
  elsif exists(select 1 from controlled_review_v3.escalations where event_id=decision_value.event_id and reason='rejected')then
   raise exception 'review_rejection_history_invalid'using errcode='23514';end if;
 end if;
 if cancellation_exists then
  perform controlled_review_v3.protocol_cancellation_data(to_jsonb(claim_value),case when preparation_exists then to_jsonb(preparation_value)else 'null'::jsonb end,to_jsonb(cancellation_value));
 end if;
end

controlled_review_v3.protocol_validate_p.source:
declare configuration_value jsonb:=controlled_review_v3.protocol_configuration_dto(p_record_id);publication_value jsonb;pair_value jsonb;
begin
 if configuration_value is null then raise exception 'review_history_integrity'using errcode='23514';end if;
 publication_value:=controlled_review_v3.protocol_publication_dto((configuration_value->>'publication_operation_id')::uuid);
 if publication_value is null then raise exception 'review_history_integrity'using errcode='23514';end if;
 pair_value:=controlled_review_v3.validate_configuration_pair(jsonb_build_object('configuration',configuration_value,'publication',publication_value));
 return controlled_review_v3.configuration_record(pair_value->'configuration');
end

controlled_review_v3.protocol_validate_r.source:
declare row_value jsonb:=controlled_review_v3.protocol_rejection_record(p_row);decision_value controlled_review_v3.decisions;
 preparation_value controlled_review_v3.preparations;obligation_value controlled_review_v3.obligations;expected_ids jsonb;
begin
 select *into strict decision_value from controlled_review_v3.decisions where operation_id=(row_value#>>'{evidence,decision_operation_id}')::uuid;
 select *into strict preparation_value from controlled_review_v3.preparations where operation_id=decision_value.operation_id;
 select *into strict obligation_value from controlled_review_v3.obligations where event_id=decision_value.event_id;
 expected_ids:=controlled_review_v3.protocol_escalation_ids(decision_value.operation_id,decision_value.event_id);
 if row_value->>'id'is distinct from expected_ids->>'rejected'or row_value->>'event_id'is distinct from decision_value.event_id::text
  or(row_value->>'first_detected_at')::timestamptz is distinct from decision_value.recorded_at
  or row_value->'evidence'is distinct from controlled_review_v3.protocol_rejection_evidence(to_jsonb(preparation_value),to_jsonb(decision_value))then raise exception 'review_rejection_history_invalid'using errcode='23514';end if;
 perform controlled_review_v3.protocol_validate_retained_packet(to_jsonb(preparation_value));
 if preparation_value.packet->'obligation'is distinct from controlled_review_v3.protocol_obligation_dto(obligation_value.event_id)then raise exception 'review_rejection_history_invalid'using errcode='23514';end if;
 perform controlled_review_v3.protocol_validate_rejection_routing(row_value->'routing_snapshot',obligation_value.historical->'routing_snapshot',decision_value.recorded_at);
end

declare assessment jsonb;facts jsonb;fact jsonb;members jsonb;member jsonb;configured jsonb;live_value jsonb;role_value jsonb;
 prior_actor text;prior_role text;index_value integer:=0;eligible boolean:=false;status_value text;stamp timestamptz;
begin
 if jsonb_typeof(p_snapshot)is distinct from 'object'or octet_length(p_snapshot::text)>65536 then raise exception 'review_rejection_routing_invalid'using errcode='23514';end if;
 perform public.controlled_stock_keys(p_snapshot,array['version','historical','assessment']);
 if p_snapshot->'version'is distinct from '1'::jsonb or p_snapshot->'historical'is distinct from coalesce(p_historical,'null'::jsonb)then raise exception 'review_rejection_routing_invalid'using errcode='23514';end if;
 assessment:=p_snapshot->'assessment';perform public.controlled_stock_keys(assessment,array['version','recorded_at','status','member_facts']);
 if assessment->'version'is distinct from '1'::jsonb or jsonb_typeof(assessment->'status')is distinct from 'string'then raise exception 'review_rejection_routing_invalid'using errcode='23514';end if;
 stamp:=controlled_review_v3.protocol_instant(assessment->'recorded_at');perform controlled_review_v3.protocol_utc(p_first_detected_at);
 if stamp<p_first_detected_at then raise exception 'review_rejection_routing_invalid'using errcode='23514';end if;
 facts:=assessment->'member_facts';
 if jsonb_typeof(facts)is distinct from 'array'or jsonb_array_length(facts)>100 then raise exception 'review_rejection_routing_invalid'using errcode='23514';end if;
 if p_historical is null or p_historical='null'::jsonb then
  if facts<>'[]'::jsonb or assessment->>'status'<>'missing_route'then raise exception 'review_rejection_routing_invalid'using errcode='23514';end if;
  return p_snapshot;
 end if;
 perform public.controlled_stock_keys(p_historical,array['version','id','record_hash','enabled','members']);
 perform public.controlled_stock_uuid(p_historical->'id');
 if p_historical->'version'is distinct from '1'::jsonb or jsonb_typeof(p_historical->'record_hash')is distinct from 'string'
  or(p_historical->>'record_hash')!~'^[0-9a-f]{64}$'or jsonb_typeof(p_historical->'enabled')is distinct from 'boolean'then raise exception 'review_rejection_routing_invalid'using errcode='23514';end if;
 members:=p_historical->'members';
 if jsonb_typeof(members)is distinct from 'array'or jsonb_array_length(members)>100 or jsonb_array_length(members)<>jsonb_array_length(facts)
  or(p_historical->'enabled'='true'::jsonb and jsonb_array_length(members)=0)then raise exception 'review_rejection_routing_invalid'using errcode='23514';end if;
 for fact in select value from jsonb_array_elements(facts)loop
  member:=members->index_value;index_value:=index_value+1;
  perform public.controlled_stock_keys(member,array['actor_id','roles']);perform public.controlled_stock_uuid(member->'actor_id');
  perform public.controlled_stock_keys(fact,array['actor_id','configured_roles','profile_active','live_roles']);
  if fact->'actor_id'is distinct from member->'actor_id'or fact->'configured_roles'is distinct from member->'roles'
   or jsonb_typeof(fact->'profile_active')is distinct from 'boolean'
   or(prior_actor is not null and (member->>'actor_id')collate "C"<=prior_actor collate "C")then raise exception 'review_rejection_routing_invalid'using errcode='23514';end if;
  prior_actor:=member->>'actor_id';configured:=fact->'configured_roles';live_value:=fact->'live_roles';
  if jsonb_typeof(configured)is distinct from 'array'or jsonb_array_length(configured)not between 1 and 4
   or jsonb_typeof(live_value)is distinct from 'array'or jsonb_array_length(live_value)>4 then raise exception 'review_rejection_routing_invalid'using errcode='23514';end if;
  prior_role:=null;
  for role_value in select value from jsonb_array_elements(configured)loop
   if jsonb_typeof(role_value)is distinct from 'string'or role_value#>>'{}'not in('ADMIN','DVM','STAFF','TECH')
    or(prior_role is not null and(role_value#>>'{}')collate "C"<=prior_role collate "C")then raise exception 'review_rejection_routing_invalid'using errcode='23514';end if;
   prior_role:=role_value#>>'{}';
  end loop;
  prior_role:=null;
  for role_value in select value from jsonb_array_elements(live_value)loop
   if jsonb_typeof(role_value)is distinct from 'string'or role_value#>>'{}'not in('ADMIN','DVM','STAFF','TECH')
    or(prior_role is not null and(role_value#>>'{}')collate "C"<=prior_role collate "C")then raise exception 'review_rejection_routing_invalid'using errcode='23514';end if;
   prior_role:=role_value#>>'{}';
  end loop;
  if fact->'profile_active'='true'::jsonb and exists(select 1 from jsonb_array_elements(configured)c(value)join jsonb_array_elements(live_value)l(value)on c.value=l.value)then eligible:=true;end if;
 end loop;
 status_value:=case when p_historical->'enabled'='false'::jsonb then 'disabled_route'when eligible then 'eligible_recipients'else 'no_eligible_recipient'end;
 if assessment->>'status'is distinct from status_value then raise exception 'review_rejection_routing_invalid'using errcode='23514';end if;
 return p_snapshot;
end

declare row_value jsonb:=controlled_review_v3.protocol_retained_preparation(p_preparation);packet_value jsonb:=row_value->'packet';
base_value jsonb;policy_value jsonb;read_value jsonb;review_value jsonb;authorization_value jsonb;stream_value jsonb;at_value timestamptz;
actor_value uuid;product_value uuid;site_value uuid;kind_value text;member_value jsonb;
begin
 base_value:=controlled_review_v3.protocol_packet_base((row_value->>'event_id')::uuid);
 if packet_value-'current_authorization'is distinct from base_value then raise exception 'review_history_integrity'using errcode='23514';end if;
 actor_value:=(row_value->>'actor_id')::uuid;product_value:=(packet_value#>>'{target,product_id}')::uuid;
 site_value:=(packet_value#>>'{adapter,site_id}')::uuid;kind_value:=packet_value#>>'{adapter,event_kind}';at_value:=(row_value->>'created_at')::timestamptz;
 stream_value:=jsonb_build_object('kind','policy','product_id',product_value,'site_id',site_value,'event_kind',null,'capability',null);
 policy_value:=controlled_review_v3.protocol_select_configuration(jsonb_build_object('stream_key',stream_value,'at',controlled_review_v3.protocol_utc(at_value)));
 stream_value:=stream_value||jsonb_build_object('kind','eligibility','event_kind',kind_value,'capability','read');
 read_value:=controlled_review_v3.protocol_select_configuration(jsonb_build_object('stream_key',stream_value,'at',controlled_review_v3.protocol_utc(at_value)));
 stream_value:=stream_value||jsonb_build_object('capability','review');
 review_value:=controlled_review_v3.protocol_select_configuration(jsonb_build_object('stream_key',stream_value,'at',controlled_review_v3.protocol_utc(at_value)));
 if policy_value is null or read_value is null or review_value is null or policy_value->'id'is distinct from row_value->'policy_id'
