    last_id:=row_value#>>'{}';selected_correction_id:=last_id::uuid;
    select * into correction from public.native_return_events where id=selected_correction_id;
    select * into link from public.native_return_discrepancy_correction_links l where l.correction_id=selected_correction_id;
    if correction.id is null or link.id is null or link.case_id<>selected_case_id or link.resolution_id<>e.id
    or correction.dispense_id<>did or correction.document->>'version'<>'2'
    or correction.action<>all(array['retract_intake','retract_disposal','retract_restock'])
    or correction.document#>'{correction_target}' is distinct from target#>'{document,source}'
    or correction.document->>'discrepancy_id' is distinct from selected_case_id::text then
     raise exception 'adapter_source_integrity' using errcode='23514';end if;
    n:=n+1;
    state:=controlled_review_v3.read_adapter_add(state,'public.native_return_discrepancy_correction_links',jsonb_build_object('id',link.id),to_jsonb(link),'reviewed_target');
    state:=controlled_review_v3.read_adapter_return_v1(state,correction.id,e.product_id,'resolution_correction',1);
   end loop;
  elsif target#>'{document,correction_ids}'<>'[]'::jsonb then raise exception 'adapter_source_integrity' using errcode='23514';end if;
  select count(*) into count_links from(select id from public.native_return_discrepancy_correction_links where resolution_id=e.id limit 101) q;
  if count_links>100 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
  if count_links<>n then raise exception 'adapter_source_integrity' using errcode='23514';end if;
 return state;
end

controlled_review_v3.read_adapter_dispen.source:
declare state jsonb:=p_state; d public.native_dispenses; op public.native_fulfillment_operations;
 item public.billing_invoice_items; a record; m public.inventory_movements; managed jsonb;
 n integer:=0; source_count integer; total numeric:=0; unit text;
begin
 if p_role is null or p_role<>all(array['reviewed_target','original_dispense']) then
  raise exception 'adapter_source_role_conflict' using errcode='23514';end if;
 if p_depth is null or p_depth<0 or p_depth>4 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
 select * into d from public.native_dispenses where id=p_dispense_id;
 select * into op from public.native_fulfillment_operations where id=p_dispense_id;
 select * into item from public.billing_invoice_items where id=d.invoice_item_id;
 select stock_unit into unit from public.controlled_stock_policy_versions where id=(select policy_version_id from public.controlled_stock_events where id=(state->>'target_event_id')::uuid);
 if d.id is null or op.id is null or item.id is null or op.operation<>'dispense' or op.actor_id<>d.actor_id
 or op.result->'dispense' is distinct from d.document or item.product_id<>p_product_id or item.quantity<>d.quantity
 or item.created_by<>d.actor_id or item.invoice_id<>d.invoice_id or item.pet_id is distinct from d.pet_id
 or d.document->>'unit' is distinct from unit or state->>'product_id' is distinct from p_product_id::text then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 managed:=controlled_review_v3.read_native_source_event('dispense',d.id,p_product_id);
 if managed is not null then state:=controlled_review_v3.read_adapter_parent(state,(managed->>'event_id')::uuid,p_role);end if;
 state:=controlled_review_v3.read_adapter_add(state,'public.native_dispenses',jsonb_build_object('id',d.id),to_jsonb(d),p_role);
 state:=controlled_review_v3.read_adapter_add(state,'public.native_fulfillment_operations',jsonb_build_object('id',op.id),to_jsonb(op),p_role);
 state:=controlled_review_v3.read_adapter_add(state,'public.billing_invoice_items',jsonb_build_object('id',item.id),to_jsonb(item),p_role);
 for a in select * from public.native_dispense_allocations where dispense_id=d.id order by lot_id limit 101 loop
  n:=n+1;if n>100 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
  select * into m from public.inventory_movements where id=a.movement_id;
  if m.id is null or m.lot_id<>a.lot_id or m.quantity<>-a.quantity or m.kind<>'dispense' then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  total:=total+a.quantity;
  state:=controlled_review_v3.read_adapter_add(state,'public.native_dispense_allocations',jsonb_build_object('id',a.id),to_jsonb(a),p_role);
  state:=controlled_review_v3.read_adapter_movement(state,a.movement_id,'record_native_dispense',d.id,d.actor_id,p_role,managed is not null);
 end loop;
 if n=0 or total<>d.quantity then raise exception 'adapter_source_integrity' using errcode='23514';end if;
 select count(*) into source_count from(select movement_id from public.stock_movement_sources where writer='record_native_dispense' and source_id=d.id limit 101) q;
 if source_count>100 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
 if source_count not in(0,n) or(managed is not null and source_count<>n)
 or exists(select 1 from public.stock_movement_sources s where writer='record_native_dispense' and source_id=d.id
  and not exists(select 1 from public.native_dispense_allocations allocation_row where allocation_row.dispense_id=d.id and allocation_row.movement_id=s.movement_id)) then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 return state;
end

controlled_review_v3.read_adapter_moveme.source:
declare state jsonb:=p_state; m public.inventory_movements; l public.inventory_lots;
 s public.stock_movement_sources; boundary public.controlled_stock_opening_movements;
begin
 select * into m from public.inventory_movements where id=p_movement_id;
 select * into l from public.inventory_lots where id=m.lot_id;
 select * into s from public.stock_movement_sources where movement_id=m.id;
 if m.id is null or l.id is null or l.product_id::text is distinct from state->>'product_id'
 or m.created_by is distinct from p_actor_id or p_managed is null then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 if s.movement_id is not null then
  if s.writer is distinct from p_source_writer or s.source_id is distinct from p_source_id or s.actor_id is distinct from p_actor_id then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  perform controlled_review_v3.read_stock_source(m.id);
  state:=controlled_review_v3.read_adapter_add(state,'public.stock_movement_sources',jsonb_build_object('movement_id',s.movement_id),to_jsonb(s),p_role);
 elsif p_managed then raise exception 'adapter_source_integrity' using errcode='23514';end if;
 select * into boundary from public.controlled_stock_opening_movements where movement_id=m.id;
 if p_managed then
  if boundary.movement_id is not null or not exists(select 1 from public.controlled_stock_source_links where movement_id=m.id and event_id=p_source_id) then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
 else
  if boundary.movement_id is null or boundary.opening_id::text is distinct from state->>'opening_id'
  or boundary.source_snapshot is distinct from to_jsonb(m) or boundary.lot_id<>m.lot_id or boundary.quantity<>m.quantity
  or exists(select 1 from public.controlled_stock_source_links where movement_id=m.id) then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  state:=controlled_review_v3.read_adapter_add(state,'public.controlled_stock_opening_movements',
   jsonb_build_object('opening_id',boundary.opening_id,'movement_id',boundary.movement_id),to_jsonb(boundary),'opening_basis');
 end if;
 state:=controlled_review_v3.read_adapter_add(state,'public.inventory_movements',jsonb_build_object('id',m.id),to_jsonb(m),p_role);
 state:=controlled_review_v3.read_adapter_add(state,'public.inventory_lots',jsonb_build_object('id',l.id),to_jsonb(l),p_role);
 return state;
end

controlled_review_v3.read_adapter_openin.source:
declare
 state jsonb:=p_state; target_event public.controlled_stock_events;
 target_correction public.native_dispense_correction_events; original_dispense public.native_dispenses;
 retained_opening public.controlled_stock_openings; selected_cell public.controlled_stock_cells;
 selected_container public.controlled_stock_containers; original_allocation record;
 entry jsonb; entry_candidate jsonb; projected jsonb; boundary_allocation jsonb;
 allocation_map jsonb:='{}'; prepared_sums jsonb:='{}'; retained_node jsonb;
 opening_container_map jsonb:='{}'; opening_container_ids jsonb;
 positive_sites jsonb:='{}'; zero_sites jsonb:='{}'; site_key text; retained_site uuid; selected_site uuid;
 opening_unit text; target_unit text; selected_pickup uuid;
 return_version integer; correction_version integer; discrepancy_version integer;
 entry_count integer:=0; allocation_count integer:=0; cell_count integer:=0;
 fully_prepared boolean:=true; reason text; expected_prepared numeric; actual_prepared numeric;
begin
 if p_dispense_id is null or p_product_id is null or jsonb_typeof(state) is distinct from 'object'
 or jsonb_typeof(state->'rows') is distinct from 'object' then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 if octet_length(state::text)>1048576 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
 select * into target_event from public.controlled_stock_events
 where id=public.controlled_stock_uuid(state->'target_event_id');
 select * into target_correction from public.native_dispense_correction_events where id=target_event.id;
 select * into original_dispense from public.native_dispenses where id=p_dispense_id;
 if target_event.id is null or target_event.writer is distinct from 'append_native_dispense_correction'
 or target_event.event_kind<>all(array['append_native_dispense_correction:clinical_annotation','append_native_dispense_correction:operational_annotation'])
 or target_event.product_id is distinct from p_product_id or state->>'product_id' is distinct from p_product_id::text
 or target_event.opening_id::text is distinct from state->>'opening_id'
 or target_correction.id is null or original_dispense.id is null
 or target_correction.dispense_id is distinct from p_dispense_id
 or target_correction.kind is distinct from split_part(target_event.event_kind,':',2)
 or target_correction.authorization_id is distinct from original_dispense.authorization_id
 or target_correction.pet_id is distinct from original_dispense.pet_id
 or target_correction.actor_id is distinct from target_event.actor_id then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 select * into retained_opening from public.controlled_stock_openings where id=target_event.opening_id;
 select stock_unit into opening_unit from public.controlled_stock_policy_versions
 where id=retained_opening.policy_version_id and product_id=p_product_id;
 select stock_unit into target_unit from public.controlled_stock_policy_versions
 where id=target_event.policy_version_id and product_id=p_product_id;
 if retained_opening.id is null or retained_opening.product_id is distinct from p_product_id
 or opening_unit is null or target_unit is distinct from opening_unit then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 if octet_length(retained_opening.native_custody_boundary::text)>1048576
 or jsonb_array_length(retained_opening.native_custody_boundary)>200 then
  raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
 -- The immutable parent keeps all its reciprocal, prefix and later-link checks.
 -- H0 independently admitted the immutable opening globally; W preserves it.
 if controlled_review_v3.read_native_source_event('dispense',p_dispense_id,p_product_id) is not null then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 -- This validates complete original allocations/provenance even for direct private
 -- helper calls; re-adding the existing rows obeys the unchanged role precedence.
 state:=controlled_review_v3.read_adapter_dispense(state,p_dispense_id,p_product_id,'original_dispense',1);
 for entry_candidate in select value from jsonb_array_elements(retained_opening.native_custody_boundary) loop
  if entry_candidate->>'dispense_id'=p_dispense_id::text then
   entry_count:=entry_count+1;entry:=entry_candidate;
  end if;
 end loop;
 if entry_count<>1 then raise exception 'adapter_source_integrity' using errcode='23514';end if;
 return_version:=public.controlled_stock_opening_selector(entry->'return_head');
 correction_version:=public.controlled_stock_opening_selector(entry->'correction_head');
 discrepancy_version:=public.controlled_stock_opening_selector(entry->'discrepancy_head');
 if entry->'pickup'<>'null'::jsonb then selected_pickup:=public.controlled_stock_uuid(entry#>'{pickup,id}');end if;
 -- Immutable prefix equality and complete later-source registration were
 -- established at H0/each canonical W append. This selected target still must
 -- be strictly later than the retained correction head and have its own exact
 -- managed parent/source link (read_correction_source_event).
 if target_correction.sequence<=correction_version then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 if jsonb_array_length(entry->'allocations')>100 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
 fully_prepared:=return_version=0 and discrepancy_version=0 and selected_pickup is null
  and not exists(select 1 from public.native_dispense_correction_events prefix_correction
   where prefix_correction.dispense_id=p_dispense_id and prefix_correction.sequence<=correction_version
   and prefix_correction.kind<>all(array['clinical_annotation','operational_annotation']));
 for original_allocation in select * from public.native_dispense_allocations
 where dispense_id=p_dispense_id order by id limit 101 loop
  allocation_count:=allocation_count+1;
  if allocation_count>100 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
  select value into boundary_allocation from jsonb_array_elements(entry->'allocations')
   where value->>'allocation_id'=original_allocation.id::text;
  if boundary_allocation is null or boundary_allocation->>'lot_id' is distinct from original_allocation.lot_id::text
  or original_allocation.quantity<=0
  or (boundary_allocation->>'dispensed_quantity')::numeric is distinct from original_allocation.quantity then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  expected_prepared:=(boundary_allocation->>'prepared_quantity')::numeric;
  if expected_prepared is null or expected_prepared<0 then raise exception 'adapter_source_integrity' using errcode='23514';end if;
  if expected_prepared<>original_allocation.quantity or boundary_allocation->'held'<>'[]'::jsonb then fully_prepared:=false;end if;
  allocation_map:=allocation_map||jsonb_build_object(original_allocation.id::text,boundary_allocation);
 end loop;
 if allocation_count=0 or allocation_count<>jsonb_array_length(entry->'allocations') then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 -- Preserve assertion/managed cross-set agreement even when O is unsupported.
 for retained_node in select value from jsonb_each(state->'rows') loop
  if retained_node->>'relation'='public.controlled_stock_containers' then
   selected_site:=(retained_node#>>'{row,controlling_site_id}')::uuid;
   if selected_site is null or(retained_site is not null and retained_site<>selected_site) then
    raise exception 'adapter_source_integrity' using errcode='23514';end if;
   retained_site:=selected_site;
  end if;
 end loop;
 for selected_cell in select * from public.controlled_stock_cells
 where opening_id=retained_opening.id and dispense_id=p_dispense_id and channel='prepared'
 order by id limit 513 loop
  cell_count:=cell_count+1;if cell_count>512 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
  boundary_allocation:=allocation_map->selected_cell.allocation_id::text;
  select * into selected_container from public.controlled_stock_containers where id=selected_cell.container_id;
  if boundary_allocation is null or selected_cell.lot_id::text is distinct from boundary_allocation->>'lot_id'
  or selected_cell.intake_id is not null or selected_cell.created_event_id is not null or selected_cell.opening_quantity<0
  or selected_container.id is null or selected_container.opening_id is distinct from retained_opening.id
  or selected_container.product_id is distinct from p_product_id or selected_container.stock_unit is distinct from opening_unit
  or selected_container.kind is distinct from 'prepared' or selected_container.stock_lot_id is not null
  or selected_container.created_event_id is not null or selected_container.controlling_site_id is null then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  selected_site:=selected_container.controlling_site_id;
  if retained_site is not null and selected_site<>retained_site then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  state:=controlled_review_v3.read_adapter_add(state,'public.controlled_stock_cells',jsonb_build_object('id',selected_cell.id),to_jsonb(selected_cell),'opening_basis');
  state:=controlled_review_v3.read_adapter_add(state,'public.controlled_stock_containers',jsonb_build_object('id',selected_container.id),to_jsonb(selected_container),'opening_basis');
  -- Private same-phase canonical membership, never a role/authorization flag.
  opening_container_map:=opening_container_map||jsonb_build_object(selected_container.id::text,true);
  actual_prepared:=coalesce((prepared_sums->>selected_cell.allocation_id::text)::numeric,0)+selected_cell.opening_quantity;
  prepared_sums:=prepared_sums||jsonb_build_object(selected_cell.allocation_id::text,actual_prepared);
  if selected_cell.opening_quantity>0 then positive_sites:=positive_sites||jsonb_build_object(selected_site::text,true);
  else zero_sites:=zero_sites||jsonb_build_object(selected_site::text,true);end if;
 end loop;
 for boundary_allocation in select value from jsonb_each(allocation_map) loop
  actual_prepared:=coalesce((prepared_sums->>(boundary_allocation->>'allocation_id'))::numeric,0);
  if actual_prepared is distinct from (boundary_allocation->>'prepared_quantity')::numeric then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
 end loop;
 if positive_sites<>'{}'::jsonb then
  for site_key in select jsonb_object_keys(zero_sites) loop
   if not(positive_sites?site_key) then raise exception 'adapter_source_integrity' using errcode='23514';end if;
  end loop;
 end if;
 selected_site:=null;
 if not fully_prepared or positive_sites='{}'::jsonb then reason:='opening_package_incomplete';
 elsif(select count(*) from jsonb_object_keys(positive_sites))<>1 then reason:='opening_package_multisite';
 else select jsonb_object_keys(positive_sites)::uuid into selected_site;end if;
 select coalesce(jsonb_agg(selected_ids.key order by selected_ids.key collate "C"),'[]'::jsonb)into opening_container_ids
 from jsonb_object_keys(opening_container_map)as selected_ids(key);
 return jsonb_build_object('state',state,'site_id',selected_site,'reason',reason,'opening_container_ids',opening_container_ids);
end

controlled_review_v3.read_adapter_parent.source:
declare state jsonb:=p_state; e public.controlled_stock_events; r record; row_value jsonb;
begin
 if p_role is null or p_role<>all(array['reviewed_target','correction_target','ordinary_source','original_dispense','original_pickup']) then
  raise exception 'adapter_source_role_conflict' using errcode='23514';end if;
 select * into e from public.controlled_stock_events where id=p_event_id;
 if e.id is null or e.product_id::text is distinct from state->>'product_id'
 or e.opening_id::text is distinct from state->>'opening_id' then
  raise exception 'adapter_parent_integrity' using errcode='23514';end if;
 perform controlled_review_v3.read_validate_scalar(e.id);
 state:=controlled_review_v3.read_adapter_add(state,'public.controlled_stock_events',jsonb_build_object('id',e.id),to_jsonb(e),p_role);
 select to_jsonb(a) into row_value from public.controlled_stock_actions a where a.id=e.id;
 state:=controlled_review_v3.read_adapter_add(state,'public.controlled_stock_actions',jsonb_build_object('id',e.id),row_value,p_role);
 select to_jsonb(a) into row_value from public.controlled_stock_preparations a where a.id=e.id;
 state:=controlled_review_v3.read_adapter_add(state,'public.controlled_stock_preparations',jsonb_build_object('id',e.id),row_value,p_role);
 select to_jsonb(a) into row_value from public.controlled_stock_policy_versions a where a.id=e.policy_version_id;
 state:=controlled_review_v3.read_adapter_add(state,'public.controlled_stock_policy_versions',jsonb_build_object('id',e.policy_version_id),row_value,p_role);
 select to_jsonb(a) into row_value from public.controlled_stock_openings a where a.id=e.opening_id;
 state:=controlled_review_v3.read_adapter_add(state,'public.controlled_stock_openings',jsonb_build_object('id',e.opening_id),row_value,p_role);
 for r in select * from public.controlled_stock_source_links where event_id=e.id order by id limit 513 loop
  state:=controlled_review_v3.read_adapter_add(state,'public.controlled_stock_source_links',jsonb_build_object('id',r.id),to_jsonb(r),p_role);
 end loop;
 for r in select * from public.controlled_stock_event_lines where event_id=e.id order by cell_id,source_link_id limit 513 loop
  state:=controlled_review_v3.read_adapter_add(state,'public.controlled_stock_event_lines',jsonb_build_object('id',r.id),to_jsonb(r),p_role);
  select to_jsonb(c) into row_value from public.controlled_stock_cells c where c.id=r.cell_id;
  state:=controlled_review_v3.read_adapter_add(state,'public.controlled_stock_cells',jsonb_build_object('id',r.cell_id),row_value,p_role);
  select to_jsonb(c) into row_value from public.controlled_stock_containers c where c.id=(row_value->>'container_id')::uuid;
  state:=controlled_review_v3.read_adapter_add(state,'public.controlled_stock_containers',jsonb_build_object('id',row_value->'id'),row_value,p_role);
 end loop;
 for r in select * from public.controlled_stock_container_transitions where event_id=e.id order by container_id limit 513 loop
  state:=controlled_review_v3.read_adapter_add(state,'public.controlled_stock_container_transitions',jsonb_build_object('id',r.id),to_jsonb(r),p_role);
  select to_jsonb(c) into row_value from public.controlled_stock_containers c where c.id=r.container_id;
  state:=controlled_review_v3.read_adapter_add(state,'public.controlled_stock_containers',jsonb_build_object('id',r.container_id),row_value,p_role);
 end loop;
 return state;
end

controlled_review_v3.read_adapter_pickup.source:
declare state jsonb:=p_state; p public.native_pickups; op public.native_fulfillment_operations;
 provenance public.stock_pickup_sources; managed jsonb;
begin
 if p_role is null or p_role<>all(array['reviewed_target','original_pickup']) then
  raise exception 'adapter_source_role_conflict' using errcode='23514';end if;
 if p_depth is null or p_depth<0 or p_depth>4 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
 select * into p from public.native_pickups where id=p_pickup_id;
 select * into op from public.native_fulfillment_operations where id=p_pickup_id;
 select * into provenance from public.stock_pickup_sources where event_id=p_pickup_id;
 if p.id is null or op.id is null or op.operation<>'pickup' or op.actor_id<>p.actor_id or op.result is distinct from p.document then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 managed:=controlled_review_v3.read_native_source_event('pickup',p.id,p_product_id);
 if managed is not null then state:=controlled_review_v3.read_adapter_parent(state,(managed->>'event_id')::uuid,p_role);end if;
 if provenance.event_id is null and managed is not null then raise exception 'adapter_source_integrity' using errcode='23514';end if;
 if provenance.event_id is not null then
  if provenance.actor_id<>p.actor_id then raise exception 'adapter_source_integrity' using errcode='23514';end if;
  state:=controlled_review_v3.read_adapter_add(state,'public.stock_pickup_sources',jsonb_build_object('event_id',p.id),to_jsonb(provenance),p_role);
 end if;
 state:=controlled_review_v3.read_adapter_add(state,'public.native_pickups',jsonb_build_object('id',p.id),to_jsonb(p),p_role);
 state:=controlled_review_v3.read_adapter_add(state,'public.native_fulfillment_operations',jsonb_build_object('id',op.id),to_jsonb(op),p_role);
 state:=controlled_review_v3.read_adapter_dispense(state,p.dispense_id,p_product_id,'original_dispense',p_depth+1);
 return state;
end

controlled_review_v3.read_adapter_return.source:
declare state jsonb:=p_state; r public.native_return_events; op public.native_return_operations;
 provenance public.stock_custody_sources; original public.native_return_events;
 stock public.native_return_stock_links; movement public.inventory_movements; a public.native_dispense_allocations;
 x record; managed jsonb; source_writer text; n integer:=0; source_count integer; target_id uuid;
begin
 if p_role is null or p_role<>all(array['reviewed_target','correction_target','ordinary_source','original_intake','resolution_correction']) then
  raise exception 'adapter_source_role_conflict' using errcode='23514';end if;
 if p_depth is null or p_depth<0 or p_depth>4 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
 select * into r from public.native_return_events where id=p_return_id;
 select * into op from public.native_return_operations where id=p_return_id;
 select * into provenance from public.stock_custody_sources where event_id=p_return_id;
 source_writer:=case r.document->>'version' when '1' then 'record_native_dispense_return' when '2' then 'record_native_dispense_return_v2' end;
 if r.id is not null and(r.document->'version'not in('1'::jsonb,'2'::jsonb)or r.action not in('intake','dispose','restock','retract_intake','retract_disposal','retract_restock'))then raise exception 'read_denied'using errcode='42501';end if;
 if r.id is null or op.id is null or source_writer is null or op.actor_id<>r.actor_id or op.result is distinct from r.document
 or r.document->>'record_hash' is distinct from r.record_hash or public.native_fulfillment_hash(r.document-'record_hash') is distinct from r.record_hash then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 managed:=controlled_review_v3.read_return_source_event(r.id,p_product_id);
 -- Only these return roles declare parent/physical reference edges.
 if managed is not null and p_role in('reviewed_target','correction_target','ordinary_source') then
  state:=controlled_review_v3.read_adapter_parent(state,(managed->>'event_id')::uuid,p_role);end if;
 if provenance.event_id is null and managed is not null then raise exception 'adapter_source_integrity' using errcode='23514';end if;
 if provenance.event_id is not null then
  if provenance.actor_id<>r.actor_id or provenance.writer<>source_writer then raise exception 'adapter_source_integrity' using errcode='23514';end if;
  state:=controlled_review_v3.read_adapter_add(state,'public.stock_custody_sources',jsonb_build_object('event_id',r.id),to_jsonb(provenance),p_role);
 end if;
 state:=controlled_review_v3.read_adapter_add(state,'public.native_return_events',jsonb_build_object('id',r.id),to_jsonb(r),p_role);
 state:=controlled_review_v3.read_adapter_add(state,'public.native_return_operations',jsonb_build_object('id',op.id),to_jsonb(op),p_role);
 state:=controlled_review_v3.read_adapter_dispense(state,r.dispense_id,p_product_id,'original_dispense',p_depth+1);
 if r.intake_id is not null then
  select * into original from public.native_return_events where id=r.intake_id;
  if original.id is null or original.id=r.id or original.action<>'intake' or original.dispense_id<>r.dispense_id or original.sequence>=r.sequence then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  state:=controlled_review_v3.read_adapter_return_v1(state,original.id,p_product_id,'original_intake',p_depth+1);
 end if;
 if r.action in('retract_intake','retract_disposal','retract_restock') then
  target_id:=(r.document#>>'{correction_target,event_id}')::uuid;
  select * into original from public.native_return_events where id=target_id;
  if original.id is null or original.id=r.id or original.dispense_id<>r.dispense_id or original.sequence>=r.sequence
  or original.record_hash is distinct from r.document#>>'{correction_target,record_hash}'
  or original.action is distinct from(case r.action when 'retract_intake' then 'intake' when 'retract_disposal' then 'dispose' else 'restock' end)
  or controlled_review_v3.read_return_source_event(target_id,p_product_id) is null then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  state:=controlled_review_v3.read_adapter_return_v1(state,target_id,p_product_id,'correction_target',p_depth+1);
 end if;
 if r.action='restock' then
  for x in select * from public.native_return_stock_links where event_id=r.id order by allocation_id limit 101 loop
   n:=n+1;if n>100 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
   select * into a from public.native_dispense_allocations where id=x.allocation_id;
   select * into movement from public.inventory_movements where id=x.movement_id;
   if a.id is null or movement.id is null or a.dispense_id<>r.dispense_id or a.lot_id<>x.lot_id or movement.lot_id<>x.lot_id or movement.quantity<>x.quantity
   or not exists(select 1 from jsonb_array_elements(r.document->'allocations') d where d->>'allocation_id'=x.allocation_id::text
    and d->>'movement_id'=x.movement_id::text and(d->>'quantity')::numeric=x.quantity and d->>'lot_id'=x.lot_id::text) then
    raise exception 'adapter_source_integrity' using errcode='23514';end if;
   state:=controlled_review_v3.read_adapter_add(state,'public.native_return_stock_links',jsonb_build_object('id',x.id),to_jsonb(x),p_role);
   state:=controlled_review_v3.read_adapter_movement(state,x.movement_id,source_writer,r.id,r.actor_id,p_role,managed is not null);
  end loop;
 elsif r.action='retract_restock' then
  for x in select * from public.native_return_compensation_links where event_id=r.id order by allocation_id limit 101 loop
   n:=n+1;if n>100 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
   select * into stock from public.native_return_stock_links where event_id=target_id and allocation_id=x.allocation_id;
   select * into movement from public.inventory_movements where id=x.movement_id;
   if stock.id is null or movement.id is null or x.target_event_id<>target_id or x.original_movement_id<>stock.movement_id or x.lot_id<>stock.lot_id
   or movement.lot_id<>x.lot_id or movement.quantity<>-x.quantity
   or not exists(select 1 from jsonb_array_elements(r.document->'allocations') d where d->>'allocation_id'=x.allocation_id::text
    and d->>'movement_id'=x.movement_id::text and(d->>'quantity')::numeric=x.quantity and d->>'lot_id'=x.lot_id::text) then
    raise exception 'adapter_source_integrity' using errcode='23514';end if;
   state:=controlled_review_v3.read_adapter_add(state,'public.native_return_compensation_links',jsonb_build_object('id',x.id),to_jsonb(x),p_role);
   state:=controlled_review_v3.read_adapter_add(state,'public.native_return_stock_links',jsonb_build_object('id',stock.id),to_jsonb(stock),'correction_target');
   -- adapter_return(target) already retained/checked the original positive movement.
   -- Its exact stock link above binds original_movement_id; retain the distinct negative movement now.
   state:=controlled_review_v3.read_adapter_movement(state,x.movement_id,source_writer,r.id,r.actor_id,p_role,managed is not null);
  end loop;
 end if;
 if r.action in('restock','retract_restock') and(n=0 or n<>jsonb_array_length(r.document->'allocations')) then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 select count(*) into source_count from(select movement_id from public.stock_movement_sources s where s.writer=source_writer and s.source_id=r.id limit 101) q;
 if source_count>100 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
 if source_count not in(0,n) or(managed is not null and source_count<>n)
 or exists(select 1 from public.stock_movement_sources s where s.writer=source_writer and s.source_id=r.id
  and not exists(select 1 from public.native_return_stock_links l where r.action='restock' and l.event_id=r.id and l.movement_id=s.movement_id)
  and not exists(select 1 from public.native_return_compensation_links l where r.action='retract_restock' and l.event_id=r.id and l.movement_id=s.movement_id)) then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 return state;
end

controlled_review_v3.read_adapter_site(p.source:
declare e public.controlled_stock_events; site uuid; unit text; r record; n integer:=0;
begin
 select * into e from public.controlled_stock_events where id=p_event_id;
 if e.id is null then raise exception 'adapter_parent_integrity' using errcode='23514';end if;
 select stock_unit into unit from public.controlled_stock_policy_versions where id=e.policy_version_id;
 for r in select c.controlling_site_id,c.product_id,c.stock_unit from public.controlled_stock_container_transitions t
  join public.controlled_stock_containers c on c.id=t.container_id where t.event_id=e.id order by t.container_id limit 513 loop
  n:=n+1;
  if n>512 then raise exception 'evidence_limit_exceeded' using errcode='54000';end if;
  if r.product_id<>e.product_id or r.stock_unit is distinct from unit or(site is not null and site<>r.controlling_site_id) then
   raise exception 'adapter_source_integrity' using errcode='23514';end if;
  site:=r.controlling_site_id;
 end loop;
 if e.basis in('physical_record','correction_assertion') and(site is null or not exists(select 1 from public.controlled_stock_event_lines where event_id=e.id)) then
  raise exception 'adapter_source_integrity' using errcode='23514';end if;
 return jsonb_build_object('site_id',site);
end

controlled_review_v3.read_annotation_ope.source:
declare e public.controlled_stock_events;o public.controlled_stock_openings;a record;c record;entry jsonb;item jsonb;allocation_map jsonb:='{}';sums jsonb:='{}';
 sites jsonb:='{}';zero_sites jsonb:='{}';key_value text;site_value uuid;unit_value text;target_unit text;n integer:=0;entry_count integer:=0;cell_count integer:=0;
begin
 select *into e from public.controlled_stock_events where id=p_event_id;
 select *into o from public.controlled_stock_openings where id=e.opening_id and product_id=p_product_id;
 if e.id is null or o.id is null or e.event_kind not in('append_native_dispense_correction:clinical_annotation','append_native_dispense_correction:operational_annotation')
  or jsonb_typeof(o.native_custody_boundary)is distinct from 'array'or jsonb_array_length(o.native_custody_boundary)>200 then return jsonb_build_object('site_id',null);end if;
 for item in select value from jsonb_array_elements(o.native_custody_boundary)loop
  if item->>'dispense_id'=p_dispense_id::text then entry:=item;entry_count:=entry_count+1;end if;
 end loop;
 select stock_unit into unit_value from public.controlled_stock_policy_versions where id=o.policy_version_id and product_id=p_product_id;
 select stock_unit into target_unit from public.controlled_stock_policy_versions where id=e.policy_version_id and product_id=p_product_id;
 if entry_count<>1 or unit_value is null or unit_value is distinct from target_unit
  or public.controlled_stock_opening_selector(entry->'return_head')<>0 or public.controlled_stock_opening_selector(entry->'discrepancy_head')<>0
  or entry->'pickup'is distinct from 'null'::jsonb or jsonb_typeof(entry->'allocations')is distinct from 'array'or jsonb_array_length(entry->'allocations')not between 1 and 100
  or exists(select 1 from public.native_dispense_correction_events prefix where prefix.dispense_id=p_dispense_id
    and prefix.sequence<=public.controlled_stock_opening_selector(entry->'correction_head')and prefix.kind not in('clinical_annotation','operational_annotation'))then return jsonb_build_object('site_id',null);end if;
 for a in select *from public.native_dispense_allocations where dispense_id=p_dispense_id limit 101 loop
  n:=n+1;if n>100 then return jsonb_build_object('site_id',null);end if;
  select value into item from jsonb_array_elements(entry->'allocations')where value->>'allocation_id'=a.id::text;
  if item is null or item->>'lot_id'is distinct from a.lot_id::text or(item->>'dispensed_quantity')::numeric is distinct from a.quantity
   or(item->>'prepared_quantity')::numeric is distinct from a.quantity or a.quantity<=0 or item->'held'is distinct from '[]'::jsonb then return jsonb_build_object('site_id',null);end if;
  allocation_map:=allocation_map||jsonb_build_object(a.id::text,item);
 end loop;
 if n=0 or n<>jsonb_array_length(entry->'allocations')then return jsonb_build_object('site_id',null);end if;
 for c in select cell.*,box.product_id as box_product,box.stock_unit,box.kind as box_kind,box.stock_lot_id,box.opening_id as box_opening,
  box.created_event_id as box_created,box.controlling_site_id from public.controlled_stock_cells cell join public.controlled_stock_containers box on box.id=cell.container_id
  where cell.opening_id=o.id and cell.dispense_id=p_dispense_id and cell.channel='prepared'limit 513 loop
  cell_count:=cell_count+1;if cell_count>512 then return jsonb_build_object('site_id',null);end if;
  item:=allocation_map->c.allocation_id::text;
  if item is null or c.lot_id::text is distinct from item->>'lot_id'or c.intake_id is not null or c.created_event_id is not null or c.opening_quantity<0
   or c.box_opening is distinct from o.id or c.box_product is distinct from p_product_id or c.stock_unit is distinct from unit_value
   or c.box_kind is distinct from 'prepared'or c.stock_lot_id is not null or c.box_created is not null or c.controlling_site_id is null then return jsonb_build_object('site_id',null);end if;
  sums:=sums||jsonb_build_object(c.allocation_id::text,coalesce((sums->>c.allocation_id::text)::numeric,0)+c.opening_quantity);
  if c.opening_quantity>0 then sites:=sites||jsonb_build_object(c.controlling_site_id::text,true);else zero_sites:=zero_sites||jsonb_build_object(c.controlling_site_id::text,true);end if;
 end loop;
 for item in select value from jsonb_each(allocation_map)loop
  if coalesce((sums->>(item->>'allocation_id'))::numeric,0)is distinct from(item->>'prepared_quantity')::numeric then return jsonb_build_object('site_id',null);end if;
 end loop;
 if(select count(*)from jsonb_object_keys(sites))<>1 then return jsonb_build_object('site_id',null);end if;
 for key_value in select jsonb_object_keys(zero_sites)loop if not(sites?key_value)then return jsonb_build_object('site_id',null);end if;end loop;
 select jsonb_object_keys(sites)::uuid into site_value;
 return jsonb_build_object('site_id',site_value);
end

controlled_review_v3.read_authorizations.source:
declare policy_value jsonb:=p_configs->'policy';read_value jsonb;review_value jsonb;policy_projection jsonb;fact jsonb:=p_facts->p_actor_id::text;
begin
 if policy_value is not null and policy_value<>'null'::jsonb and policy_value->'enabled'='true'::jsonb and policy_value#>array['body','rules',p_kind,'enabled']='true'::jsonb then
 policy_projection:=jsonb_build_object('id',policy_value->'id','record_hash',policy_value->'record_hash','rule',policy_value#>array['body','rules',p_kind]);end if;
 if fact is not null then
  if p_configs->'read'<>'null'::jsonb then read_value:=controlled_review_v3.protocol_member_conditions(jsonb_build_object('record',p_configs->'read','actor_id',p_actor_id,'capability','read','active',fact->'active','live_roles',fact->'roles'));end if;
  if p_configs->'review'<>'null'::jsonb then review_value:=controlled_review_v3.protocol_member_conditions(jsonb_build_object('record',p_configs->'review','actor_id',p_actor_id,'capability','review','active',fact->'active','live_roles',fact->'roles'));end if;
 end if;
 return jsonb_build_object('policy',policy_projection,'read',read_value,'review',review_value);
end

controlled_review_v3.read_clinical_depen.source:
declare expected jsonb:=$clinical${"guards":{"anesthesia_drug_administration_guard":{"body_sha256":"bb5bd0459e0bb8b3858146d659d0cc6c32afb84e361a97aead0c554e574e3a98","configuration":["search_path=public"],"language":"plpgsql","return_type":"trigger","security_definer":false,"volatility":"v"},"guard_inquiry_history":{"body_sha256":"d4d7e91745765c745e7761655cd11ee18ca38bbd2ffce16795208b06d8c4db2e","configuration":["search_path=public"],"language":"plpgsql","return_type":"trigger","security_definer":false,"volatility":"v"},"inventory_guard":{"authority":"unchanged frozen parent205 expected_technical_manifest.functions.inventory_guard()","configuration":["search_path=public"],"definition_sha256":"f7707724b9ad5ae07f2e33253c80d5c51d89d8087eb9a07267c72e1bc490471a","language":"plpgsql","return_type":"trigger","security_definer":true,"volatility":"v"}},"relations":{"billing_invoice_items":{"acl":[{"grantable":false,"privilege":"SELECT","role":"authenticated"},{"grantable":false,"privilege":"DELETE","role":"postgres"},{"grantable":false,"privilege":"INSERT","role":"postgres"},{"grantable":false,"privilege":"MAINTAIN","role":"postgres"},{"grantable":false,"privilege":"REFERENCES","role":"postgres"},{"grantable":false,"privilege":"SELECT","role":"postgres"},{"grantable":false,"privilege":"TRIGGER","role":"postgres"},{"grantable":false,"privilege":"TRUNCATE","role":"postgres"},{"grantable":false,"privilege":"UPDATE","role":"postgres"},{"grantable":false,"privilege":"SELECT","role":"service_role"}],"columns":[{"generated":"","name":"id","not_null":true,"type":"uuid"},{"generated":"","name":"invoice_id","not_null":true,"type":"uuid"},{"generated":"","name":"pet_id","not_null":false,"type":"uuid"},{"generated":"","name":"product_id","not_null":true,"type":"uuid"},{"generated":"","name":"description","not_null":true,"type":"text"},{"generated":"","name":"quantity","not_null":true,"type":"numeric(14,3)"},{"generated":"","name":"unit_price_cents","not_null":true,"type":"bigint"},{"generated":"s","name":"amount_cents","not_null":false,"type":"bigint"},{"generated":"","name":"created_by","not_null":true,"type":"uuid"},{"generated":"","name":"created_at","not_null":true,"type":"timestamp with time zone"}],"indexes":{"billing_invoice_items_invoice_idx":{"columns":["invoice_id"],"predicate":null,"primary":false,"unique":false},"billing_invoice_items_pet_idx":{"columns":["pet_id","invoice_id"],"predicate":"(pet_id IS NOT NULL)","primary":false,"unique":false},"billing_invoice_items_pkey":{"columns":["id"],"predicate":null,"primary":true,"unique":true},"whogot_dispense_product":{"columns":["product_id","id"],"predicate":null,"primary":false,"unique":false}},"select_roles":["authenticated","service_role"],"triggers":{"inventory_audit":{"function":"audit_trigger_fn","type":21},"inventory_guard":{"function":"inventory_guard","type":31}}},"treatment_alert_reviews":{"acl":[{"grantable":false,"privilege":"SELECT","role":"authenticated"},{"grantable":false,"privilege":"DELETE","role":"postgres"},{"grantable":false,"privilege":"INSERT","role":"postgres"},{"grantable":false,"privilege":"MAINTAIN","role":"postgres"},{"grantable":false,"privilege":"REFERENCES","role":"postgres"},{"grantable":false,"privilege":"SELECT","role":"postgres"},{"grantable":false,"privilege":"TRIGGER","role":"postgres"},{"grantable":false,"privilege":"TRUNCATE","role":"postgres"},{"grantable":false,"privilege":"UPDATE","role":"postgres"}],"columns":[{"generated":"","name":"id","not_null":true,"type":"uuid"},{"generated":"","name":"treatment_id","not_null":true,"type":"uuid"},{"generated":"","name":"pet_id","not_null":true,"type":"uuid"},{"generated":"","name":"snapshot","not_null":true,"type":"jsonb"},{"generated":"","name":"source_hash","not_null":true,"type":"text"},{"generated":"","name":"reviewed_by","not_null":true,"type":"uuid"},{"generated":"","name":"reviewed_at","not_null":true,"type":"timestamp with time zone"}],"indexes":{"treatment_alert_reviews_pkey":{"columns":["id"],"predicate":null,"primary":true,"unique":true},"treatment_alert_reviews_treatment_id_key":{"columns":["treatment_id"],"predicate":null,"primary":false,"unique":true}},"select_roles":["authenticated"],"triggers":{"audit_treatment_alert_reviews":{"function":"audit_trigger_fn","type":5},"immutable_treatment_alert_reviews":{"function":"guard_inquiry_history","type":27}}}}}$clinical$::jsonb;name_value text;relation_oid oid;c pg_catalog.pg_class;observed jsonb;entry jsonb;guard_name text;fn pg_catalog.pg_proc;
begin
 for name_value,entry in select key,value from jsonb_each(expected->'relations')loop
  select *into c from pg_catalog.pg_class where oid=to_regclass('public.'||name_value);
  if c.oid is null or c.relkind<>'r'or c.relpersistence<>'p'or pg_get_userbyid(c.relowner)<>'postgres'or not c.relrowsecurity or c.relforcerowsecurity then raise exception 'clinical_read_dependency_drift'using errcode='23514';end if;
  relation_oid:=c.oid;
  select coalesce(jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'generated',a.attgenerated)order by a.attnum),'[]'::jsonb)into observed
   from pg_catalog.pg_attribute a where a.attrelid=relation_oid and a.attnum>0 and not a.attisdropped;
  if observed is distinct from entry->'columns'then raise exception 'clinical_read_dependency_drift'using errcode='23514';end if;
  select coalesce(jsonb_object_agg(ic.relname,jsonb_build_object('columns',(select jsonb_agg(a.attname order by k.position)from unnest(x.indkey::smallint[])with ordinality k(number,position)left join pg_catalog.pg_attribute a on a.attrelid=relation_oid and a.attnum=k.number),'unique',x.indisunique,'primary',x.indisprimary,'predicate',pg_get_expr(x.indpred,x.indrelid))),'{}'::jsonb)into observed
   from pg_catalog.pg_index x join pg_catalog.pg_class ic on ic.oid=x.indexrelid join pg_catalog.pg_am am on am.oid=ic.relam
   where x.indrelid=relation_oid and x.indisvalid and x.indisready and x.indislive and x.indimmediate and x.indnkeyatts=x.indnatts and am.amname='btree';
  if observed is distinct from entry->'indexes'or (select count(*)from pg_catalog.pg_index where indrelid=relation_oid)<>(select count(*)from jsonb_object_keys(entry->'indexes'))then raise exception 'clinical_read_dependency_drift'using errcode='23514';end if;
  select coalesce(jsonb_agg(jsonb_build_object('role',case when a.grantee=0 then 'PUBLIC'else pg_get_userbyid(a.grantee)end,'privilege',a.privilege_type,'grantable',a.is_grantable)order by(case when a.grantee=0 then 'PUBLIC'else pg_get_userbyid(a.grantee)end)collate "C",a.privilege_type collate "C"),'[]'::jsonb)into observed
   from aclexplode(coalesce(c.relacl,acldefault('r',c.relowner)))a;
  if observed is distinct from entry->'acl'then raise exception 'clinical_read_dependency_drift'using errcode='23514';end if;
  if exists(select 1 from pg_catalog.pg_attribute a where a.attrelid=relation_oid and a.attnum>0 and not a.attisdropped and a.attacl is not null)then raise exception 'clinical_read_dependency_drift'using errcode='23514';end if;
  select coalesce(jsonb_object_agg(t.tgname,jsonb_build_object('function',p.proname,'type',t.tgtype)),'{}'::jsonb)into observed
   from pg_catalog.pg_trigger t join pg_catalog.pg_proc p on p.oid=t.tgfoid join pg_catalog.pg_namespace ns on ns.oid=p.pronamespace
   where t.tgrelid=relation_oid and not t.tgisinternal and t.tgenabled='O'and t.tgattr=''::int2vector and t.tgqual is null and t.tgnargs=0 and t.tgargs=''::bytea and ns.nspname='public';
  if observed is distinct from entry->'triggers'or(select count(*)from pg_catalog.pg_trigger where tgrelid=relation_oid and not tgisinternal)<>(select count(*)from jsonb_object_keys(entry->'triggers'))then raise exception 'clinical_read_dependency_drift'using errcode='23514';end if;
 end loop;
 for guard_name,entry in select key,value from jsonb_each(expected->'guards')loop
  select *into fn from pg_catalog.pg_proc where oid=to_regprocedure('public.'||guard_name||'()');
  if fn.oid is null or pg_get_userbyid(fn.proowner)<>'postgres'or fn.prosecdef is distinct from(entry->>'security_definer')::boolean or to_jsonb(fn.proconfig)is distinct from entry->'configuration'
   or fn.prorettype<>'trigger'::regtype or fn.provolatile::text is distinct from entry->>'volatility'
   or fn.prolang is distinct from(select oid from pg_catalog.pg_language where lanname=entry->>'language')
   or encode(sha256(convert_to(case when entry?'definition_sha256'then pg_get_functiondef(fn.oid)else fn.prosrc end,'UTF8')),'hex')is distinct from coalesce(entry->>'definition_sha256',entry->>'body_sha256')then raise exception 'clinical_read_dependency_drift'using errcode='23514';end if;
 end loop;
end

controlled_review_v3.read_collect_scalar.source:
declare e public.controlled_stock_events;s jsonb;refs jsonb;rows_value jsonb;site uuid;adapter_value jsonb;target_value jsonb;row_site uuid;retained_site uuid;return_site uuid;dispense_site uuid;did uuid;managed jsonb;opening_projection jsonb; before_opening_containers jsonb:='{}'; opening_scope_ids jsonb; opening_scope_map jsonb:='{}'; opening_seen_map jsonb:='{}'; scope_item jsonb; scope_id uuid; scope_sorted jsonb;reason_value text;site_basis_value text:='event_transitions';row_value jsonb;
begin
 select *into e from public.controlled_stock_events where id=p_event_id;
 if e.id is null or e.event_kind not in('receive_inventory','adjust_inventory','record_patient_treatment','record_anesthesia_drug_administration','record_native_dispense','record_native_pickup','append_native_dispense_correction:clinical_annotation','append_native_dispense_correction:operational_annotation','append_native_dispense_correction:pickup_amendment','record_native_dispense_return:intake','record_native_dispense_return:dispose','record_native_dispense_return:restock','record_native_dispense_return_v2:intake','record_native_dispense_return_v2:dispose','record_native_dispense_return_v2:restock','record_native_dispense_return_v2:retract_intake','record_native_dispense_return_v2:retract_disposal','record_native_dispense_return_v2:retract_restock','record_native_return_discrepancy:report','record_native_return_discrepancy:note','record_native_return_discrepancy:resolve_corrected','record_native_return_discrepancy:resolve_confirmed_original')then raise exception 'read_denied'using errcode='42501';end if;
 s:=jsonb_build_object('rows','{}'::jsonb,'documents','[]'::jsonb,'allocations','[]'::jsonb,'target_event_id',e.id,'product_id',e.product_id,'opening_id',e.opening_id);
 s:=controlled_review_v3.read_adapter_parent(s,e.id,'reviewed_target');
 if e.event_kind='record_native_dispense'then s:=controlled_review_v3.read_adapter_dispense(s,e.id,e.product_id,'reviewed_target',0);
 elsif e.event_kind='record_native_pickup'then s:=controlled_review_v3.read_adapter_pickup(s,e.id,e.product_id,'reviewed_target',0);
 elsif e.writer in('record_native_dispense_return','record_native_dispense_return_v2')then s:=controlled_review_v3.read_adapter_return_v1(s,e.id,e.product_id,'reviewed_target',0);
 elsif e.writer='record_native_return_discrepancy'then s:=controlled_review_v3.read_adapter_discrepancy(s,e.id);
 elsif e.writer='append_native_dispense_correction'then s:=controlled_review_v3.read_adapter_annotations(s,e.id);
 else s:=controlled_review_v3.read_adapter_clinical(s,e.id);end if;
 if e.writer in('record_native_dispense_return','record_native_dispense_return_v2')then
  select dispense_id into did from public.native_return_events where id=e.id;managed:=controlled_review_v3.read_native_source_event('dispense',did,e.product_id);
  -- The managed D is the immutable scope candidate/cross-check, not the
  -- return event's proof label. Original collect_event_sources derives return
  -- site from the OWN event transitions and labels it event_transitions.
  if managed is not null then
   return_site:=(controlled_review_v3.read_adapter_site(e.id)->>'site_id')::uuid;
   dispense_site:=(controlled_review_v3.read_adapter_site(did)->>'site_id')::uuid;
   if return_site is null or dispense_site is null or return_site is distinct from dispense_site then raise exception 'adapter_source_integrity'using errcode='23514';end if;
   site:=return_site;site_basis_value:='event_transitions';
  else reason_value:='unmanaged_original_dispense';site_basis_value:='unproven';end if;
 elsif e.writer='record_native_return_discrepancy'then
  select(document#>>'{source,event_id}')::uuid into did from public.native_return_discrepancy_events where id=e.id;
  managed:=controlled_review_v3.read_return_source_event(did,e.product_id);
  if managed is not null then site:=(controlled_review_v3.read_adapter_site((managed->>'event_id')::uuid)->>'site_id')::uuid;site_basis_value:='managed_return';
  else reason_value:='unmanaged_original_return';site_basis_value:='unproven';end if;
 elsif e.writer='append_native_dispense_correction'then
  select dispense_id into did from public.native_dispense_correction_events where id=e.id;
  managed:=controlled_review_v3.read_native_source_event('dispense',did,e.product_id);
  if managed is not null then site:=(controlled_review_v3.read_adapter_site(did)->>'site_id')::uuid;site_basis_value:='managed_dispense';
  elsif e.event_kind in('append_native_dispense_correction:clinical_annotation','append_native_dispense_correction:operational_annotation')then
   -- Capture ALL existing container IDs before the fixed canonical helper.
    for row_value in select value from jsonb_each(s->'rows')loop
     if row_value->>'relation'='public.controlled_stock_containers'then
      before_opening_containers:=before_opening_containers||jsonb_build_object(public.controlled_stock_uuid(row_value#>'{key,id}')::text,true);
     end if;
    end loop;
    opening_projection:=controlled_review_v3.read_adapter_opening_site(s,did,e.product_id);s:=opening_projection->'state';
   site:=(opening_projection->>'site_id')::uuid;reason_value:=opening_projection->>'reason';site_basis_value:=case when site is null then 'unproven'else 'opening_custody_site'end;
  else reason_value:='unmanaged_original_dispense';site_basis_value:='unproven';end if;
 else
  site:=(controlled_review_v3.read_adapter_site(e.id)->>'site_id')::uuid;
  if site is null then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 end if;
 -- Only a fresh helper-owned canonical set can scope the unsupported path.
 if opening_projection is not null and managed is null
 and e.event_kind in('append_native_dispense_correction:clinical_annotation','append_native_dispense_correction:operational_annotation')
 and opening_projection->'site_id'='null'::jsonb and site is null
 and opening_projection->>'reason'in('opening_package_incomplete','opening_package_multisite')
 and reason_value=opening_projection->>'reason'and site_basis_value='unproven'
 and before_opening_containers='{}'::jsonb then
  perform public.controlled_stock_keys(opening_projection,array['state','site_id','reason','opening_container_ids']);
  opening_scope_ids:=opening_projection->'opening_container_ids';
  if jsonb_typeof(opening_scope_ids)is distinct from 'array'then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  if jsonb_array_length(opening_scope_ids)>512 then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  for scope_item in select value from jsonb_array_elements(opening_scope_ids)loop
   scope_id:=public.controlled_stock_uuid(scope_item);
   if opening_scope_map?scope_id::text then raise exception 'adapter_source_integrity'using errcode='23514';end if;
   opening_scope_map:=opening_scope_map||jsonb_build_object(scope_id::text,true);
  end loop;
  select coalesce(jsonb_agg(scope_keys.key order by scope_keys.key collate "C"),'[]'::jsonb)into scope_sorted
  from jsonb_object_keys(opening_scope_map)as scope_keys(key);
  if opening_scope_ids is distinct from scope_sorted then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 end if;
 for row_value in select value from jsonb_each(s->'rows')loop
  if row_value->>'relation'='public.controlled_stock_containers'then
   row_site:=(row_value#>>'{row,controlling_site_id}')::uuid;
   if opening_scope_ids is not null then
    scope_id:=public.controlled_stock_uuid(row_value#>'{key,id}');
    if row_site is null or row_value#>'{row,id}'is distinct from to_jsonb(scope_id)
    or not(opening_scope_map?scope_id::text)or opening_seen_map?scope_id::text then
     raise exception 'adapter_source_integrity'using errcode='23514';end if;
    opening_seen_map:=opening_seen_map||jsonb_build_object(scope_id::text,true);
   else
   if row_site is null or(retained_site is not null and row_site<>retained_site)or(site is not null and row_site<>site)then raise exception 'adapter_source_integrity'using errcode='23514';end if;
   retained_site:=row_site;
   end if;
  end if;
 end loop;
 if opening_scope_ids is not null and opening_seen_map is distinct from opening_scope_map then
  raise exception 'adapter_source_integrity'using errcode='23514';end if;
 target_value:=jsonb_build_object('event_id',e.id,'product_id',e.product_id,'sequence',e.sequence,'record_hash',e.record_hash,'original_actor_id',e.actor_id,'policy_version_id',e.policy_version_id,'opening_id',e.opening_id,'engine_revision',e.engine_revision);
 select coalesce(jsonb_agg(value-'row'order by(value->>'relation')collate "C",(value->'key')::text collate "C"),'[]'::jsonb),
 coalesce(jsonb_agg(value-'row_hash'-'role'order by(value->>'relation')collate "C",(value->'key')::text collate "C"),'[]'::jsonb)into refs,rows_value from jsonb_each(s->'rows');
 adapter_value:=jsonb_build_object('version',1,'event_kind',e.event_kind,'adapter_id',case e.event_kind when 'record_patient_treatment'then 'treatment_v1'when 'record_anesthesia_drug_administration'then 'anesthesia_v1'when 'record_native_dispense'then 'dispense_v1'when 'record_native_pickup'then 'pickup_v1'else case when e.writer='record_native_return_discrepancy'then 'discrepancy_v1'when e.writer='append_native_dispense_correction'then 'annotation_v1'when e.writer='record_native_dispense_return'then 'return_v1'when e.event_kind in('record_native_dispense_return_v2:retract_intake','record_native_dispense_return_v2:retract_disposal','record_native_dispense_return_v2:retract_restock')then 'retraction_v1'when e.writer='record_native_dispense_return_v2'then 'return_v2'else 'movement_v1'end end,'target',target_value,'site_basis',site_basis_value,'site_id',site,'source_refs',refs,'native_family_dispense_id',case e.event_kind when 'record_native_dispense'then e.id when 'record_native_pickup'then(select dispense_id from public.native_pickups where id=e.id)else null end,'provenance_state',case when reason_value is null then 'supported'else 'unsupported'end,'reason',reason_value);
 if octet_length(jsonb_build_object('adapter',adapter_value,'source_rows',rows_value)::text)>1048576 then raise exception 'evidence_limit_exceeded'using errcode='54000';end if;
 return jsonb_build_object('adapter',adapter_value,'source_rows',rows_value);
end

controlled_review_v3.read_collect_visibl.source:
declare e public.controlled_stock_events;target_value jsonb;collected_value jsonb;message_value text;context_value text;
begin
 -- All exact local target/source validations OUTSIDE the capacity catch.
 perform controlled_review_v3.read_validate_scalar(p_event_id);
 select *into strict e from public.controlled_stock_events where id=p_event_id;
 target_value:=jsonb_build_object('event_id',e.id,'product_id',e.product_id,'sequence',e.sequence,'record_hash',e.record_hash,'original_actor_id',e.actor_id,'policy_version_id',e.policy_version_id,'opening_id',e.opening_id,'engine_revision',e.engine_revision);
 begin collected_value:=controlled_review_v3.read_collect_scalar(p_event_id);
 exception when sqlstate '54000'then
  get stacked diagnostics message_value=MESSAGE_TEXT,context_value=PG_EXCEPTION_CONTEXT;
  if message_value is distinct from 'evidence_limit_exceeded'or split_part(context_value,E'\n',1)!~'^PL/pgSQL function controlled_review_v3\.(read_adapter_add|read_collect_scalar|read_adapter_site|read_adapter_dispense|read_adapter_pickup|read_adapter_opening_site|read_return_v1_context|read_return_v1_source_event|read_adapter_return_v1|read_return_v2_prefix|read_return_v2_quantity_step|read_return_discrepancy_snapshot|read_return_source_event)\([^\n]*\) line [1-9][0-9]* at RAISE$'then raise;end if;
  return jsonb_build_object('state','collector_limit','event',to_jsonb(e),'adapter',jsonb_build_object('version',1,'event_kind',e.event_kind,'adapter_id',case e.event_kind when 'record_patient_treatment'then 'treatment_v1'when 'record_anesthesia_drug_administration'then 'anesthesia_v1'when 'record_native_dispense'then 'dispense_v1'when 'record_native_pickup'then 'pickup_v1'else case when e.writer='record_native_return_discrepancy'then 'discrepancy_v1'when e.writer='append_native_dispense_correction'then 'annotation_v1'when e.writer='record_native_dispense_return'then 'return_v1'when e.event_kind in('record_native_dispense_return_v2:retract_intake','record_native_dispense_return_v2:retract_disposal','record_native_dispense_return_v2:retract_restock')then 'retraction_v1'when e.writer='record_native_dispense_return_v2'then 'return_v2'else 'movement_v1'end end,'target',target_value,
  'site_basis','unproven','site_id',null,'source_refs','[]'::jsonb,'native_family_dispense_id',null,'provenance_state','unsupported','reason','evidence_limit_exceeded'),'source_rows',null);
 end;
 return jsonb_build_object('state','complete','adapter',collected_value->'adapter','source_rows',collected_value->'source_rows');
end

controlled_review_v3.read_configuration_.source:
declare stored_row controlled_review_v3.configuration;result_value jsonb;
begin
 if p_id is null or p_id='00000000-0000-0000-0000-000000000000'::uuid then
  raise exception 'configuration_record_invalid'using errcode='23514';end if;
 select *into stored_row from controlled_review_v3.configuration where id=p_id;
 if not found then return null;end if;
 result_value:=jsonb_build_object('id',stored_row.id,'kind',stored_row.kind,'stream_key',stored_row.stream_key,
  'version',stored_row.version,'predecessor_id',stored_row.predecessor_id,'predecessor_hash',stored_row.predecessor_hash,
  'enabled',stored_row.enabled,'document',stored_row.document,'record_hash',stored_row.record_hash,
  'publication_operation_id',stored_row.publication_operation_id,
  'published_at',controlled_review_v3.protocol_utc(stored_row.published_at),
  'publisher_actor_id',stored_row.publisher_actor_id,'publisher_session_id',stored_row.publisher_session_id,
  'publisher_name',stored_row.publisher_name,'authorization_id',stored_row.authorization_id,'publication_mode',stored_row.publication_mode,
  'effective_from',case when stored_row.effective_from is null then null else controlled_review_v3.protocol_utc(stored_row.effective_from)end);
 perform controlled_review_v3.configuration_record(result_value);
 return result_value;
end

declare row_value jsonb:=controlled_review_v3.read_configuration_dto(p_id);
begin
 if row_value is null then return null;end if;
 return controlled_review_v3.configuration_record(row_value);
end

controlled_review_v3.read_correction_cap.source:
declare captured jsonb;d jsonb;target jsonb;head jsonb;latest jsonb;pickup jsonb;v jsonb;previous_stamp timestamptz;
 e public.native_dispense_correction_events;o public.native_dispense_correction_operations;
 authorization_value uuid;pet_value uuid;dispense_value uuid;previous_row public.native_dispense_correction_events;latest_row public.native_dispense_correction_events;reference public.native_dispense_correction_events;
begin
 perform public.controlled_stock_uuid(to_jsonb(p_event_id));perform public.controlled_stock_uuid(to_jsonb(p_product_id));
 select *into e from public.native_dispense_correction_events where id=p_event_id;
 if e.id is null or e.kind not in('clinical_annotation','operational_annotation','pickup_amendment')then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 captured:=controlled_review_v3.read_dispense_capture(e.dispense_id,p_product_id);d:=captured#>'{dispense,document}';
 if d is null or d->>'authorization_id'is distinct from e.authorization_id::text or d->>'pet_id'is distinct from e.pet_id::text then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 authorization_value:=(d->>'authorization_id')::uuid;pet_value:=(d->>'pet_id')::uuid;dispense_value:=(d->>'id')::uuid;
 target:=jsonb_build_object('authorization_id',authorization_value,'pet_id',pet_value,'dispense_id',dispense_value);
 pickup:=public.native_correction_pickup(e.dispense_id);
 head:=jsonb_build_object('event_id',null,'version',0,'record_hash',null);
 if e.prior_event_id is not null then
  select *into previous_row from public.native_dispense_correction_events where id=e.prior_event_id;
  if previous_row.id is null or previous_row.dispense_id is distinct from e.dispense_id or previous_row.authorization_id is distinct from e.authorization_id
   or previous_row.pet_id is distinct from e.pet_id or previous_row.sequence<>e.sequence-1
   or previous_row.record_hash is distinct from public.native_fulfillment_hash(previous_row.document-'record_hash')
   or previous_row.document->>'id'is distinct from previous_row.id::text or previous_row.document->'sequence'is distinct from to_jsonb(previous_row.sequence)
   or previous_row.document->'target'is distinct from target then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  head:=jsonb_build_object('event_id',previous_row.id,'version',previous_row.sequence,'record_hash',previous_row.record_hash);previous_stamp:=previous_row.created_at;
 elsif e.sequence<>1 then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 -- The original canonical writer established global latest/absence and prefix
 -- validity at commit. H0/W preserves it. We still independently bind the exact
 -- retained latest-amendment pointer/value/hash and order to immutable PK rows;
 -- NULL is source absence under that theorem, never a cached validation flag.
 if e.reviewed_context->'latest_pickup_amendment'is distinct from 'null'::jsonb then
  select *into latest_row from public.native_dispense_correction_events where id=(e.reviewed_context#>>'{latest_pickup_amendment,event_id}')::uuid;
  if latest_row.id is null or latest_row.dispense_id is distinct from e.dispense_id or latest_row.kind<>'pickup_amendment'or latest_row.sequence>=e.sequence or latest_row.authorization_id is distinct from e.authorization_id or latest_row.pet_id is distinct from e.pet_id
   or latest_row.document->>'id'is distinct from latest_row.id::text or latest_row.document->'sequence'is distinct from to_jsonb(latest_row.sequence)
   or latest_row.document->'kind'is distinct from '"pickup_amendment"'::jsonb or latest_row.document->'target'is distinct from target
   or latest_row.record_hash is distinct from public.native_fulfillment_hash(latest_row.document-'record_hash')then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  latest:=jsonb_build_object('event_id',latest_row.id,'version',latest_row.sequence,'value',latest_row.document->'pickup_amendment');
 end if;
  v:=e.document;select * into o from public.native_dispense_correction_operations where id=e.id;
  if o.id is null or o.actor_id<>e.actor_id or o.result is distinct from v or o.created_at is distinct from e.created_at
   or o.request_hash is distinct from public.native_fulfillment_hash(jsonb_build_object('version',1,'actor_id',o.actor_id,'operation','append_native_dispense_correction','request',o.request))
   or e.authorization_id<>authorization_value or e.pet_id<>pet_value or e.sequence<>(head->>'version')::integer+1 or e.prior_event_id::text is distinct from head->>'event_id'
   or v->'target' is distinct from target or v->>'id' is distinct from e.id::text or v->'version' is distinct from '1'::jsonb
   or v->'sequence' is distinct from to_jsonb(e.sequence) or v->>'prior_event_id' is distinct from head->>'event_id' or v->>'prior_record_hash' is distinct from head->>'record_hash'
   or v#>>'{actor,id}' is distinct from e.actor_id::text or v->>'kind' is distinct from e.kind or (v->>'created_at')::timestamptz is distinct from e.created_at
   or v->>'authorization_hash' is distinct from d->>'authorization_hash' or v->>'dispense_document_hash' is distinct from public.native_fulfillment_hash(d)
   or v->>'record_hash' is distinct from e.record_hash or e.record_hash is distinct from public.native_fulfillment_hash(v-'record_hash')
   or v->>'reviewed_context_hash' is distinct from public.native_fulfillment_hash(e.reviewed_context)
   or e.reviewed_context->'target' is distinct from target or e.reviewed_context->'head' is distinct from head
   or e.reviewed_context->'latest_pickup_amendment' is distinct from coalesce(latest,'null'::jsonb)
   or e.reviewed_context->>'authorization_hash' is distinct from d->>'authorization_hash'
   or e.reviewed_context->>'dispense_document_hash' is distinct from public.native_fulfillment_hash(d)
   or e.reviewed_context->>'dispense_artifact_hash' is distinct from d->>'artifact_hash'
   or e.reviewed_context->'dispensed_at' is distinct from d->'dispensed_at'
   or (e.reviewed_context->'original_pickup'<>'null'::jsonb and e.reviewed_context->'original_pickup' is distinct from pickup)
   or e.created_at<(d->>'dispensed_at')::timestamptz or (previous_stamp is not null and e.created_at<previous_stamp)
  then raise exception 'Native correction integrity mismatch' using errcode='23514';end if;
  perform public.native_rx_keys(v,array['version','id','target','authorization_hash','dispense_document_hash','sequence','prior_event_id','prior_record_hash','actor','kind','reason','note','amends_event_id','pickup_amendment','reviewed_context_hash','created_at','record_hash']);
  perform public.native_rx_keys(e.reviewed_context,array['version','target','authorization_hash','dispense_document_hash','dispense_artifact_hash','dispensed_at','original_pickup','head','latest_pickup_amendment']);
  perform public.native_rx_keys(v->'actor',array['id','name','authority']);perform public.native_rx_text(v#>'{actor,name}',200);
  if v#>>'{actor,authority}' is distinct from (case when e.kind='clinical_annotation' then 'active_dvm' else 'active_staff' end)
   or (o.request->>'authorization_id')::uuid is distinct from authorization_value or (o.request->>'pet_id')::uuid is distinct from pet_value or (o.request->>'dispense_id')::uuid is distinct from dispense_value
   or o.request-'authorization_id'-'pet_id'-'dispense_id'-'expected_context_hash'-'expected_head'-'attest_review' is distinct from jsonb_build_object('kind',v->'kind','reason',v->'reason','note',v->'note','amends_event_id',v->'amends_event_id','pickup_amendment',v->'pickup_amendment')
   or o.request->'expected_head' is distinct from head or o.request->>'expected_context_hash' is distinct from v->>'reviewed_context_hash' or o.request->'attest_review' is distinct from 'true'::jsonb
  then raise exception 'Native correction receipt mismatch' using errcode='23514';end if;
  if e.kind='pickup_amendment' then
   if pickup is null or e.created_at<(pickup->>'picked_up_at')::timestamptz or (v#>>'{pickup_amendment,original_pickup_id}')::uuid is distinct from (pickup->>'id')::uuid or (v->>'amends_event_id')::uuid is distinct from (latest->>'event_id')::uuid then raise exception 'Native pickup amendment chain mismatch' using errcode='23514';end if;
   latest:=jsonb_build_object('event_id',e.id,'version',e.sequence,'value',v->'pickup_amendment');
  elsif v->'pickup_amendment' is distinct from 'null'::jsonb then raise exception 'Native correction kind mismatch' using errcode='23514';end if;
  if v->>'amends_event_id' is not null then
   select * into reference from public.native_dispense_correction_events where id=(v->>'amends_event_id')::uuid;
   if reference.id is null or reference.dispense_id<>dispense_value or reference.sequence>=e.sequence or reference.kind<>e.kind then raise exception 'Native correction amendment target mismatch' using errcode='23514';end if;
  end if;
 if reference.id is not null and(reference.record_hash is distinct from public.native_fulfillment_hash(reference.document-'record_hash')
  or reference.document->>'id'is distinct from reference.id::text or reference.document->'target'is distinct from target)then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 return jsonb_build_object('event',to_jsonb(e),'operation',to_jsonb(o),'dispense',captured,
  'prior_head',head,'latest_pickup_amendment',latest,'original_pickup',pickup);
end

controlled_review_v3.read_correction_sou.source:
declare captured jsonb;e public.native_dispense_correction_events;provenance public.stock_correction_sources;
 link public.controlled_stock_source_links;parent public.controlled_stock_events;opening public.controlled_stock_openings;entry jsonb;
begin
 captured:=controlled_review_v3.read_correction_capture(p_event_id,p_product_id);e:=jsonb_populate_record(null::public.native_dispense_correction_events,captured->'event');
 -- Preserve complete selected dispense allocation/source/opening membership.
 perform controlled_review_v3.read_native_source_event('dispense',e.dispense_id,p_product_id);
 select *into provenance from public.stock_correction_sources where event_id=e.id;
 if provenance.event_id is not null and provenance.actor_id is distinct from e.actor_id then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 select *into opening from public.controlled_stock_openings where product_id=p_product_id;
 select *into link from public.controlled_stock_source_links where correction_event_id=e.id;
 if link.id is not null then
  select *into parent from public.controlled_stock_events where id=link.event_id;
  if provenance.event_id is null or parent.id is distinct from e.id or parent.product_id is distinct from p_product_id
   or parent.writer is distinct from 'append_native_dispense_correction'or parent.actor_id is distinct from e.actor_id
   or parent.event_kind is distinct from 'append_native_dispense_correction:'||e.kind
   or(opening.id is not null and parent.opening_id is distinct from opening.id)
