  if not exists(select 1 from public.native_return_events r where r.dispense_id=parent.dispense_id and r.id::text=d#>>'{return_head,event_id}' and r.sequence=(d#>>'{return_head,version}')::integer and r.record_hash=d#>>'{return_head,record_hash}' and r.created_at<=e.created_at) then raise exception 'Discrepancy return head mismatch' using errcode='23514';end if;
  if e.action='report' then
   if cases ? e.case_id::text or d#>>'{actor,authority}' not in('active_staff','active_dvm') then raise exception 'Discrepancy report identity mismatch' using errcode='23514';end if;
   case_row:=jsonb_build_object('id',e.id,'source',d->'source','allocations',d->'allocations','status','open','report',d,'decisions','[]'::jsonb);ordered:=array_append(ordered,e.id::text);
  else
   case_row:=cases->e.case_id::text;
   if case_row is null or case_row->>'status'<>'open' or case_row->'source' is distinct from d->'source' or case_row->'allocations' is distinct from d->'allocations' then raise exception 'Discrepancy case mismatch' using errcode='23514';end if;
   if e.action like 'resolve_%' then
    if d#>>'{actor,authority}'<>'active_dvm' then raise exception 'DVM discrepancy resolution required' using errcode='23514';end if;
    -- H0/W: canonical confirmed-original writer forbids a compensated case.
    -- Its committed prefix absence is not re-scanned through later history.
    if e.action='resolve_confirmed_original' and o.request->'attest_original_quantities_custody_and_stock_accurate' is distinct from 'true'::jsonb then raise exception 'Original facts require explicit confirmation' using errcode='23514';end if;
    if e.action='resolve_corrected' then
     if jsonb_array_length(d->'correction_ids')=0 or exists(select 1 from jsonb_array_elements_text(d->'correction_ids')ids where not exists(select 1 from public.native_return_discrepancy_correction_links l join public.native_return_events r on r.id=l.correction_id where l.case_id=e.case_id and l.resolution_id=e.id and r.id::text=ids and r.document#>'{correction_target}'=d->'source' and r.document->>'discrepancy_id'=e.case_id::text and r.dispense_id=parent.dispense_id and r.created_at<=e.created_at and octet_length(r.document::text)<=1048576 and jsonb_typeof(r.document->'allocations')='array'and jsonb_array_length(r.document->'allocations')between 1 and 100 and r.document->'version'='2'::jsonb and r.action like'retract_%'and r.record_hash=public.native_fulfillment_hash(r.document-'record_hash')and r.document->>'id'=r.id::text and r.document->'target'=d->'target')) then raise exception 'Discrepancy compensation links missing' using errcode='23514';end if;
     -- Exact NUMERIC sums from actual referenced rows are captured once per
     -- resolution. Repeating the same correction PK/array traversal for each
     -- allocation would add an unnecessary allocation-count factor.
     select coalesce(jsonb_object_agg(allocation_id,quantity),'{}'::jsonb)into correction_quantities from(
      select x->>'allocation_id'as allocation_id,sum((x->>'quantity')::numeric)as quantity from jsonb_array_elements_text(d->'correction_ids')declared_id join public.native_return_discrepancy_correction_links l on l.correction_id=declared_id::uuid join public.native_return_events r on r.id=l.correction_id cross join lateral jsonb_array_elements(r.document->'allocations')x where l.resolution_id=e.id and l.case_id=e.case_id group by x->>'allocation_id')summed;
     if exists(select 1 from jsonb_array_elements(d->'allocations')a where (a->>'quantity')::numeric is distinct from(correction_quantities->>(a->>'allocation_id'))::numeric)then raise exception 'Discrepancy compensation quantity mismatch' using errcode='23514';end if;
    elsif d->'correction_ids' is distinct from '[]'::jsonb then raise exception 'Unexpected discrepancy compensation links' using errcode='23514';end if;
    case_row:=jsonb_set(case_row,'{status}',to_jsonb(case e.action when 'resolve_corrected' then 'resolved_corrected' else 'resolved_confirmed_original' end));
   end if;
   case_row:=jsonb_set(case_row,'{decisions}',case_row->'decisions'||jsonb_build_array(d));
  end if;
  cases:=jsonb_set(cases,array[e.case_id::text],case_row);head:=jsonb_build_object('event_id',e.id,'version',e.sequence,'record_hash',e.record_hash);previous:=e.created_at;
 end loop;
 if head is distinct from wanted_head then raise exception 'Exact discrepancy prefix unavailable' using errcode='23514';end if;
 foreach key in array ordered loop rows:=rows||jsonb_build_array(cases->key);if cases#>>array[key,'status']='open' then open_count:=open_count+1;end if;end loop;
 select coalesce(jsonb_agg(lot_id order by lot_id),'[]'::jsonb) into lots from(select distinct case_allocation.value->>'lot_id' lot_id from jsonb_array_elements(rows) as case_entry(value) cross join lateral jsonb_array_elements(case_entry.value->'allocations') as case_allocation(value) where case_entry.value->>'status'='open')q;
 snapshot_result:=jsonb_build_object('version',1,'head',head,'open_case_count',open_count,'held_lot_ids',lots,'cases',rows);
 if snapshot_result is distinct from p_snapshot then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 return snapshot_result;
end

controlled_review_v3.read_discrepancy_so.source:
declare captured jsonb;e public.native_return_discrepancy_events;provenance public.stock_discrepancy_sources;
 link public.controlled_stock_source_links;parent public.controlled_stock_events;opening public.controlled_stock_openings;entry jsonb;
begin
 captured:=controlled_review_v3.read_discrepancy_capture(p_event_id,p_product_id);e:=jsonb_populate_record(null::public.native_return_discrepancy_events,captured->'event');
 perform controlled_review_v3.read_native_source_event('dispense',e.dispense_id,p_product_id);
 select *into provenance from public.stock_discrepancy_sources where event_id=e.id;
 if provenance.event_id is not null and provenance.actor_id is distinct from e.actor_id then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 select *into opening from public.controlled_stock_openings where product_id=p_product_id;
 select *into link from public.controlled_stock_source_links where discrepancy_event_id=e.id;
 if link.id is not null then
  select *into parent from public.controlled_stock_events where id=link.event_id;
  if provenance.event_id is null or parent.id is distinct from e.id or parent.product_id is distinct from p_product_id
   or parent.writer is distinct from'record_native_return_discrepancy'or parent.actor_id is distinct from e.actor_id
   or parent.event_kind is distinct from'record_native_return_discrepancy:'||e.action
   or(opening.id is not null and parent.opening_id is distinct from opening.id)
   or parent.source_bundle#>>'{native,kind}'is distinct from'discrepancy'or parent.source_bundle#>>'{native,id}'is distinct from e.id::text then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  perform controlled_review_v3.read_validate_scalar(parent.id);
  return jsonb_build_object('event_id',parent.id,'source_link_ids',jsonb_build_array(link.id));
 end if;
 if exists(select 1 from public.controlled_stock_events where id=e.id)then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 if opening.id is not null then
  if jsonb_typeof(opening.native_custody_boundary)is distinct from'array'or jsonb_array_length(opening.native_custody_boundary)>200 then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  select value into entry from jsonb_array_elements(opening.native_custody_boundary)where value->>'dispense_id'=e.dispense_id::text;
  if entry is null or e.sequence>public.controlled_stock_opening_selector(entry->'discrepancy_head')then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 end if;
 return null;
end

controlled_review_v3.read_dispense_captu.source:
declare d public.native_dispenses;o public.native_fulfillment_operations;i public.billing_invoice_items;
 a record;m public.inventory_movements;l public.inventory_lots;s public.stock_movement_sources;
 allocation_ids jsonb:='[]'::jsonb;n integer:=0;total numeric:=0;verified jsonb;
begin
 perform public.controlled_stock_uuid(to_jsonb(p_dispense_id));perform public.controlled_stock_uuid(to_jsonb(p_product_id));
 select *into d from public.native_dispenses where id=p_dispense_id;
 select *into o from public.native_fulfillment_operations where id=p_dispense_id;
 select *into i from public.billing_invoice_items where id=d.invoice_item_id;
 if d.id is null or o.id is null or i.id is null or o.operation<>'dispense'or o.actor_id<>d.actor_id
  or o.result->'dispense'is distinct from d.document or i.product_id<>p_product_id or i.quantity<>d.quantity
  or i.created_by<>d.actor_id or i.invoice_id<>d.invoice_id or i.pet_id is distinct from d.pet_id then
  raise exception 'adapter_source_integrity'using errcode='23514';end if;
 if jsonb_typeof(d.document#>'{reviewed_context,lots}')is distinct from 'array'
  or jsonb_array_length(d.document#>'{reviewed_context,lots}')not between 1 and 100 then
  raise exception 'adapter_source_integrity'using errcode='23514';end if;
 -- Sentinel precedes the original STABLE verifier's all-allocation aggregation.
 -- No SELECT ORDER BY over an uncapped corrupt membership is introduced here.
 select count(*)into n from(select 1 from public.native_dispense_allocations where dispense_id=d.id limit 101)q;
 if n not between 1 and 100 then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 n:=0;
 for a in select *from public.native_dispense_allocations where dispense_id=d.id order by lot_id loop
  n:=n+1;select *into m from public.inventory_movements where id=a.movement_id;
  select *into l from public.inventory_lots where id=a.lot_id;
  select *into s from public.stock_movement_sources where movement_id=a.movement_id;
  if m.id is null or l.id is null or l.product_id<>p_product_id or m.lot_id<>a.lot_id or m.quantity<>-a.quantity
   or m.kind<>'dispense'or m.created_by<>d.actor_id or a.quantity<=0 then
   raise exception 'adapter_source_integrity'using errcode='23514';end if;
  if s.movement_id is not null and(s.writer<>'record_native_dispense'or s.source_id<>d.id or s.actor_id<>d.actor_id)then
   raise exception 'adapter_source_integrity'using errcode='23514';end if;
  total:=total+a.quantity;
  allocation_ids:=allocation_ids||jsonb_build_array(a.id);
 end loop;
 if n=0 or total<>d.quantity then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 -- Source-declared STABLE, single retained authorization PK plus <=100 captured
 -- allocations. It does not inspect today's authorization/head/role state.
 verified:=public.native_fulfillment_verified_dispense(d.id);
 if verified is distinct from d.document then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 return jsonb_build_object('dispense',to_jsonb(d),'operation',to_jsonb(o),'invoice_item',to_jsonb(i),'allocation_ids',allocation_ids);
end

controlled_review_v3.read_exception_obli.source:
declare expected_value jsonb;stored_value jsonb;projection_value jsonb;row_value controlled_review_v3.escalations;
begin
 if p_visible#>'{adapter,site_id}'is distinct from 'null'::jsonb
  or p_visible#>'{adapter,site_basis}'is distinct from '"unproven"'::jsonb
  or p_visible#>'{adapter,provenance_state}'is distinct from '"unsupported"'::jsonb then
  raise exception 'review_history_integrity'using errcode='23514';end if;
 expected_value:=controlled_review_v3.read_obligation_captured(p_event,p_visible->'adapter',null);
 stored_value:=controlled_review_v3.read_obligation_dto((p_event->>'id')::uuid);
 if stored_value is not null and stored_value is distinct from expected_value
  or exists(select 1 from controlled_review_v3.decisions where event_id=(p_event->>'id')::uuid)then
  raise exception 'review_history_integrity'using errcode='23514';end if;
 projection_value:=jsonb_build_object('source_state',p_visible->'state','target',p_visible#>'{adapter,target}',
  'adapter',p_visible->'adapter','event',p_event,'obligation',expected_value,'family',null,'packet_base',null);
 for row_value in select *from controlled_review_v3.escalations where event_id=(p_event->>'id')::uuid order by reason collate "C" limit 7 loop
  if stored_value is null or row_value.reason<>'evidence_unavailable'then raise exception 'review_history_integrity'using errcode='23514';end if;
  perform controlled_review_v3.ops_worker_escalation_record(to_jsonb(row_value));
  perform controlled_review_v3.ops_validate_worker_assessment(row_value.evidence->'assessment',projection_value);
  if row_value.evidence->'target_hash'is distinct from expected_value->'target_hash'then raise exception 'review_history_integrity'using errcode='23514';end if;
 end loop;
end

controlled_review_v3.read_get(p_request.source:
declare actor_value uuid;event_value uuid;e public.controlled_stock_events;site_value uuid;scope_value jsonb;exception_scope jsonb;visible_value jsonb;base_value jsonb;result_value jsonb;as_of_value timestamptz;final_scope jsonb;ids_value jsonb;
begin
 if jsonb_typeof(p_request)is distinct from 'object'or octet_length(p_request::text)>131072 then raise exception 'review_request_invalid'using errcode='23514';end if;
 perform public.controlled_stock_keys(p_request,array['actor_id','event_id']);
 actor_value:=public.controlled_stock_uuid(p_request->'actor_id');event_value:=public.controlled_stock_uuid(p_request->'event_id');
 perform controlled_review_v3.read_prelude(actor_value);
 select *into e from public.controlled_stock_events where id=event_value;
 if e.id is null or e.event_kind not in('receive_inventory','adjust_inventory','record_patient_treatment','record_anesthesia_drug_administration','record_native_dispense','record_native_pickup','append_native_dispense_correction:clinical_annotation','append_native_dispense_correction:operational_annotation','append_native_dispense_correction:pickup_amendment','record_native_dispense_return:intake','record_native_dispense_return:dispose','record_native_dispense_return:restock','record_native_dispense_return_v2:intake','record_native_dispense_return_v2:dispose','record_native_dispense_return_v2:restock','record_native_dispense_return_v2:retract_intake','record_native_dispense_return_v2:retract_disposal','record_native_dispense_return_v2:retract_restock','record_native_return_discrepancy:report','record_native_return_discrepancy:note','record_native_return_discrepancy:resolve_corrected','record_native_return_discrepancy:resolve_confirmed_original')then
  perform controlled_review_v3.protocol_identity(actor_value);raise exception 'read_denied'using errcode='42501';end if;
 site_value:=(controlled_review_v3.read_site_candidate(e.id)->>'site_id')::uuid;
 if site_value is null then
  perform controlled_review_v3.read_lock_scope(actor_value,e.product_id,null,null,true,false);
  exception_scope:=controlled_review_v3.read_scope_or_null(actor_value,e.product_id,null,null,true);
 else
  perform controlled_review_v3.read_lock_scope(actor_value,e.product_id,site_value,e.event_kind,false,true);
  scope_value:=controlled_review_v3.read_scope_or_null(actor_value,e.product_id,site_value,e.event_kind,false);
  exception_scope:=controlled_review_v3.read_scope_or_null(actor_value,e.product_id,null,null,true);
 end if;
 if scope_value is null and exception_scope is null then perform controlled_review_v3.protocol_identity(actor_value);raise exception 'read_denied'using errcode='42501';end if;
 visible_value:=controlled_review_v3.read_collect_visible_scalar(e.id);
 if visible_value->>'state'='collector_limit'then
  if not e.secondary_review_required then perform controlled_review_v3.protocol_identity(actor_value);raise exception 'read_denied'using errcode='42501';end if;
  if exception_scope is null then perform controlled_review_v3.protocol_identity(actor_value);raise exception 'read_denied'using errcode='42501';end if;
  -- A previously admitted signature/obligation cannot acquire a different collector-limit adapter under immutable H/W.
  perform controlled_review_v3.read_exception_obligation(visible_value,to_jsonb(e));
  result_value:=jsonb_build_object('version',3,'state','exception','data',jsonb_build_object('summary',controlled_review_v3.read_limit_summary(visible_value)));
  final_scope:=controlled_review_v3.read_scope_authorization(actor_value,e.product_id,null,null,true);
  if final_scope is distinct from exception_scope then raise exception 'configuration_changed'using errcode='PT409';end if;
 elsif site_value is null then
  if not e.secondary_review_required then perform controlled_review_v3.protocol_identity(actor_value);raise exception 'read_denied'using errcode='42501';end if;
  -- No late alternate site key/auth acquisition. Product exception_read alone
  -- can expose only an unproven summary, never a P or preparation selection.
  if visible_value#>>'{adapter,site_id}'is not null or exception_scope is null then perform controlled_review_v3.protocol_identity(actor_value);raise exception 'read_denied'using errcode='42501';end if;
  perform controlled_review_v3.read_exception_obligation(visible_value,to_jsonb(e));
  result_value:=jsonb_build_object('version',3,'state','exception','data',jsonb_build_object('summary',controlled_review_v3.read_unproven_summary(to_jsonb(e))));
  final_scope:=controlled_review_v3.read_scope_authorization(actor_value,e.product_id,null,null,true);
  if final_scope is distinct from exception_scope then raise exception 'configuration_changed'using errcode='PT409';end if;
 else
  if scope_value is null or visible_value#>>'{adapter,site_id}'is distinct from site_value::text then perform controlled_review_v3.protocol_identity(actor_value);raise exception 'read_denied'using errcode='42501';end if;
  base_value:=controlled_review_v3.read_scalar_base(visible_value-'state');as_of_value:=clock_timestamp();
  result_value:=controlled_review_v3.read_scalar_project(base_value,actor_value,as_of_value);ids_value:=result_value->'_configuration_ids';
  final_scope:=controlled_review_v3.read_scope_authorization(actor_value,e.product_id,site_value,e.event_kind,false);
  if final_scope is distinct from scope_value or ids_value is distinct from controlled_review_v3.read_configuration_ids(base_value->'adapter',clock_timestamp())then raise exception 'configuration_changed'using errcode='PT409';end if;
  result_value:=result_value-'_configuration_ids';
 end if;
 perform controlled_review_v3.required();perform controlled_review_v3.protocol_identity(actor_value);
 if octet_length(result_value::text)>1179648 then raise exception 'evidence_limit_exceeded'using errcode='23514';end if;
 return result_value;
end

controlled_review_v3.read_limit_summary(.source:
declare e jsonb:=p_visible->'event';required_value boolean:=(e->>'secondary_review_required')::boolean;
begin
 return jsonb_build_object('event_id',e->'id','event_sequence',e->>'sequence','event_kind',e->'event_kind','site_basis','unproven','site_id',null,'observed_at',e->'observed_at','recorded_at',e->'recorded_at',
 'review_state',case when required_value then 'awaiting_review'else 'not_required'end,'deadline_state',case when required_value then 'historical_policy_unavailable'else 'not_required'end,
 'deadline_basis',case when required_value then 'historical_policy_unavailable'else 'not_required'end,'due_at',null,'unavailable_reason',case when required_value then 'site_unproven'else null end,
 'signing_state','blocked','signing_reason',case when required_value then 'evidence_limit_exceeded'else 'not_required'end);
end

controlled_review_v3.read_list(p_request.source:
declare actor_value uuid;product_value uuid;site_value uuid;kind_value text;view_value text;page_value integer;cursor_value jsonb;scope_value jsonb;final_scope jsonb;
 high_value bigint;after_value bigint:=0;last_value bigint:=0;current_max bigint;examined_value integer:=0;items_value jsonb:='[]'::jsonb;next_value jsonb;
 e public.controlled_stock_events;visible_value jsonb;base_value jsonb;detail_value jsonb;adapter_scope jsonb;configuration_ids jsonb;as_of_value timestamptz;
begin
 perform public.controlled_stock_keys(p_request,array['actor_id','product_id','site_id','event_kind','view','page_size','cursor']);
 if octet_length(p_request::text)>16384 or jsonb_typeof(p_request->'view')is distinct from 'string'or p_request->>'view'not in('site','exceptions')
 or jsonb_typeof(p_request->'page_size')is distinct from 'number'or(p_request->>'page_size')!~'^(?:[1-9]|[1-9][0-9]|100)$'then raise exception 'review_request_invalid'using errcode='23514';end if;
 actor_value:=public.controlled_stock_uuid(p_request->'actor_id');product_value:=public.controlled_stock_uuid(p_request->'product_id');page_value:=(p_request->>'page_size')::integer;
 view_value:=p_request->>'view';cursor_value:=p_request->'cursor';
 if view_value='exceptions'then
  if p_request->'site_id'is distinct from 'null'::jsonb or p_request->'event_kind'is distinct from 'null'::jsonb then raise exception 'review_request_invalid'using errcode='23514';end if;
 else site_value:=public.controlled_stock_uuid(p_request->'site_id');kind_value:=p_request->>'event_kind';end if;
 -- Validate caller-declared scope without consulting parent events.
 perform controlled_review_v3.protocol_stream_key(jsonb_build_object('kind','eligibility','product_id',product_value,'site_id',site_value,'event_kind',kind_value,'capability',case when view_value='exceptions'then 'exception_read'else 'read'end));
 perform controlled_review_v3.read_prelude(actor_value);
 perform controlled_review_v3.read_lock_scope(actor_value,product_value,site_value,kind_value,view_value='exceptions',false);
 scope_value:=controlled_review_v3.read_scope_authorization(actor_value,product_value,site_value,kind_value,view_value='exceptions');
 if view_value='site'and kind_value not in('receive_inventory','adjust_inventory','record_patient_treatment','record_anesthesia_drug_administration','record_native_dispense','record_native_pickup','append_native_dispense_correction:clinical_annotation','append_native_dispense_correction:operational_annotation','append_native_dispense_correction:pickup_amendment','record_native_dispense_return:intake','record_native_dispense_return:dispose','record_native_dispense_return:restock','record_native_dispense_return_v2:intake','record_native_dispense_return_v2:dispose','record_native_dispense_return_v2:restock','record_native_dispense_return_v2:retract_intake','record_native_dispense_return_v2:retract_disposal','record_native_dispense_return_v2:retract_restock','record_native_return_discrepancy:report','record_native_return_discrepancy:note','record_native_return_discrepancy:resolve_corrected','record_native_return_discrepancy:resolve_confirmed_original')then
  perform controlled_review_v3.protocol_identity(actor_value);raise exception 'read_native_or_clinical_pending'using errcode='0A000';end if;
 select coalesce((select sequence from public.controlled_stock_events where product_id=product_value order by sequence desc limit 1),0)into current_max;
 high_value:=current_max;
 if cursor_value is distinct from 'null'::jsonb then
  perform public.controlled_stock_keys(cursor_value,array['version','actor_id','product_id','site_id','event_kind','view','after_sequence','high_water','read_eligibility_id','read_authorization_hash']);
  after_value:=controlled_review_v3.protocol_bigint_wire(cursor_value->'after_sequence');high_value:=controlled_review_v3.protocol_bigint_wire(cursor_value->'high_water');
  if cursor_value->'version'is distinct from '3'::jsonb or cursor_value->'actor_id'is distinct from p_request->'actor_id'or cursor_value->'product_id'is distinct from p_request->'product_id'
   or cursor_value->'site_id'is distinct from p_request->'site_id'or cursor_value->'event_kind'is distinct from p_request->'event_kind'or cursor_value->'view'is distinct from p_request->'view'
   or cursor_value->'read_eligibility_id'is distinct from scope_value->'id'or cursor_value->'read_authorization_hash'is distinct from scope_value->'fingerprint'
   or after_value>high_value or high_value>current_max or(high_value>0 and not exists(select 1 from public.controlled_stock_events where product_id=product_value and sequence=high_value))then raise exception 'cursor_stale'using errcode='PT409';end if;
 end if;
 last_value:=after_value;as_of_value:=clock_timestamp();
 adapter_scope:=jsonb_build_object('target',jsonb_build_object('product_id',product_value),'site_id',site_value,'event_kind',kind_value);
 if view_value='site'then configuration_ids:=controlled_review_v3.read_configuration_ids(adapter_scope,as_of_value);end if;
 for e in select *from public.controlled_stock_events where product_id=product_value and sequence>after_value and sequence<=high_value order by sequence limit 100 loop
  examined_value:=examined_value+1;last_value:=e.sequence;
  if view_value='exceptions'then
   -- Product exception_read is only the required site-unproven work view.
   -- It never authorizes the status/history of a proved-site event.
   if not e.secondary_review_required then continue;end if;
   visible_value:=controlled_review_v3.read_collect_visible_scalar(e.id);
   if visible_value->>'state'='collector_limit'then
    -- Same immutable H0/W contradiction refusal as detail: never replace a
    -- previously retained obligation/decision with a capacity-only adapter.
    perform controlled_review_v3.read_exception_obligation(visible_value,to_jsonb(e));
    items_value:=items_value||jsonb_build_array(controlled_review_v3.read_limit_summary(visible_value));
   elsif visible_value#>>'{adapter,site_id}'is null then
    if visible_value#>>'{adapter,site_basis}'is distinct from 'unproven'or visible_value#>>'{adapter,provenance_state}'is distinct from 'unsupported'then raise exception 'review_history_integrity'using errcode='23514';end if;
    perform controlled_review_v3.read_exception_obligation(visible_value,to_jsonb(e));
    items_value:=items_value||jsonb_build_array(controlled_review_v3.read_unproven_summary(to_jsonb(e)));
   else
    -- No site roster query or clinical projection for excluded proved sites.
    continue;
   end if;
   exit when jsonb_array_length(items_value)=page_value;
   continue;
  end if;
  if e.event_kind<>kind_value then continue;end if;
  visible_value:=controlled_review_v3.read_collect_visible_scalar(e.id);
  -- Unproven collector-limit adapter does not match this proved-site scope. No exception permission query or guessedsite.
  if visible_value->>'state'='collector_limit'then continue;end if;
  if visible_value#>>'{adapter,site_id}'is distinct from site_value::text then continue;end if;
  base_value:=controlled_review_v3.read_scalar_base(visible_value-'state');detail_value:=controlled_review_v3.read_scalar_project(base_value,actor_value,as_of_value);
  if detail_value->'_configuration_ids'is distinct from configuration_ids then raise exception 'configuration_changed'using errcode='PT409';end if;
  items_value:=items_value||jsonb_build_array(detail_value#>'{data,summary}');
  exit when jsonb_array_length(items_value)=page_value;
 end loop;
 if last_value<high_value and(examined_value=100 or jsonb_array_length(items_value)=page_value)then
  next_value:=jsonb_build_object('version',3,'actor_id',actor_value,'product_id',product_value,'site_id',site_value,'event_kind',kind_value,'view',view_value,
   'after_sequence',last_value::text,'high_water',high_value::text,'read_eligibility_id',scope_value->'id','read_authorization_hash',scope_value->'fingerprint');
 end if;
 final_scope:=controlled_review_v3.read_scope_authorization(actor_value,product_value,site_value,kind_value,view_value='exceptions');
 if final_scope is distinct from scope_value then raise exception 'configuration_changed'using errcode='PT409';end if;
 if view_value='site'then
  if configuration_ids is distinct from controlled_review_v3.read_configuration_ids(adapter_scope,clock_timestamp())then raise exception 'configuration_changed'using errcode='PT409';end if;
 end if;
 perform controlled_review_v3.required();perform controlled_review_v3.protocol_identity(actor_value);
 return jsonb_build_object('version',3,'state','page','data',jsonb_build_object('items',items_value,'next_cursor',next_value,'high_water',high_value::text,'examined',examined_value,'coverage','bounded_page'));
end

