controlled_review_v3.read_pickup_capture.source:
declare p public.native_pickups;o public.native_fulfillment_operations;s public.stock_pickup_sources;
 dispense_value jsonb;summary_value jsonb;
begin
 perform public.controlled_stock_uuid(to_jsonb(p_pickup_id));perform public.controlled_stock_uuid(to_jsonb(p_product_id));
 select *into p from public.native_pickups where id=p_pickup_id;
 select *into o from public.native_fulfillment_operations where id=p_pickup_id;
 select *into s from public.stock_pickup_sources where event_id=p_pickup_id;
 if p.id is null or o.id is null or o.operation<>'pickup'or o.actor_id<>p.actor_id
  or o.result is distinct from p.document or(s.event_id is not null and s.actor_id<>p.actor_id) then
  raise exception 'adapter_source_integrity'using errcode='23514';end if;
 dispense_value:=controlled_review_v3.read_dispense_capture(p.dispense_id,p_product_id);
 -- Despite its legacy name this sealed STABLE helper is SELECTED pickup-only:
 -- one unique pickup, its operation/provenance, retained dispense validation,
 -- and at most one original refill-event PK. No return/correction replay or
 -- current prescription/patient/role/authorization-head query is performed.
 summary_value:=public.controlled_stock_opening_pickup(p.dispense_id);
 if summary_value->>'id'is distinct from p.id::text
  or summary_value->>'document_hash'is distinct from public.native_fulfillment_hash(p.document)
  or summary_value->>'operation_hash'is distinct from public.native_fulfillment_hash(public.native_fulfillment_receipt(o))then
  raise exception 'adapter_source_integrity'using errcode='23514';end if;
 return jsonb_build_object('pickup',to_jsonb(p),'operation',to_jsonb(o),'provenance',to_jsonb(s),
  'dispense',dispense_value,'original_pickup',summary_value);
end

controlled_review_v3.read_policy_at(p_pr.source:
begin
 if p_product_id is null or p_product_id='00000000-0000-0000-0000-000000000000'::uuid
  or p_anchor is null or not isfinite(p_anchor)then
  raise exception 'review_history_integrity'using errcode='23514';end if;
 -- Configuration starts in2026; older immutable source is still visible, with
 -- explicit historical absence, rather than interpreted under today's policy.
 if p_site_id is null or p_anchor<timestamptz '2026-01-01 00:00:00Z'or p_anchor>=timestamptz '2101-01-01 00:00:00Z'then return null;end if;
 return controlled_review_v3.read_select_configuration(jsonb_build_object('stream_key',jsonb_build_object(
  'kind','policy','product_id',p_product_id,'site_id',p_site_id,'event_kind',null,'capability',null),
  'at',controlled_review_v3.protocol_utc(p_anchor)));
end

