declare policy_value jsonb;kind_value text;reference_value jsonb;references_value jsonb:='{}';reference_id uuid;
begin
 policy_value:=controlled_review_v3.validate_configuration_record(p_policy);
 if policy_value->'kind'is distinct from '"policy"'::jsonb then
  raise exception 'review_history_integrity'using errcode='23514';end if;
 foreach kind_value in array array['calendar','routing']loop
  reference_value:=null;
  if policy_value#>array['body',kind_value||'_id']is distinct from 'null'::jsonb then
   reference_id:=public.controlled_stock_uuid(policy_value#>array['body',kind_value||'_id']);
   reference_value:=controlled_review_v3.read_configuration_record(reference_id);
   if reference_value is null or reference_value->>'kind'<>kind_value
    or reference_value#>'{scope,product_id}'is distinct from policy_value#>'{scope,product_id}'
    or reference_value#>'{scope,site_id}'is distinct from policy_value#>'{scope,site_id}'
    or reference_value->'enabled'is distinct from 'true'::jsonb
    or controlled_review_v3.protocol_instant(reference_value->'published_at')>controlled_review_v3.protocol_instant(policy_value->'published_at')then
    raise exception 'review_history_integrity'using errcode='23514';end if;
  end if;
  references_value:=references_value||jsonb_build_object(kind_value,reference_value);
 end loop;
 return references_value;
end

