   or(h->>'disposed')::numeric-(h->>'retractDisposed')::numeric<>(t->>'disposed')::numeric
   or(h->>'restocked')::numeric-(h->>'retractRestocked')::numeric<>(t->>'restocked')::numeric then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  histories:=histories||jsonb_build_object(aid,h);
 end loop;
 for row_value in select value from jsonb_array_elements(p_prior->'intakes')loop
  perform public.native_rx_keys(row_value,array['id','allocations']);root:=public.native_correction_uuid(row_value->'id')::text;
  if intakes?root or jsonb_typeof(row_value->'allocations')is distinct from'array'or jsonb_array_length(row_value->'allocations')not between 1 and 100 then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  intakes:=intakes||jsonb_build_object(root,'{}'::jsonb);intake_order:=array_append(intake_order,root);last_allocation:=null;
  for slot in select value from jsonb_array_elements(row_value->'allocations')loop
   perform public.native_rx_keys(slot,array['allocation_id','lot_id','quantity','held_quantity','disposed_quantity','restocked_quantity']);candidate_id:=public.native_correction_uuid(slot->'allocation_id');aid:=candidate_id::text;s:=sources->aid;
   if s is null or(last_allocation is not null and candidate_id<=last_allocation)or slot->'lot_id'is distinct from s->'lot_id'then raise exception 'adapter_source_integrity'using errcode='23514';end if;last_allocation:=candidate_id;maximum:=(s->>'quantity')::numeric;
   received:=controlled_review_v3.read_return_quantity_number(slot->'quantity',maximum);held:=controlled_review_v3.read_return_quantity_number(slot->'held_quantity',maximum);disposed:=controlled_review_v3.read_return_quantity_number(slot->'disposed_quantity',maximum);restocked:=controlled_review_v3.read_return_quantity_number(slot->'restocked_quantity',maximum);
   if received<>held+disposed+restocked then raise exception 'adapter_source_integrity'using errcode='23514';end if;
   c:=jsonb_build_object('received',received,'held',held,'disposed',disposed,'restocked',restocked);intakes:=jsonb_set(intakes,array[root,aid],c);
   t:=sums->aid;
   foreach k in array array['received','held','disposed','restocked']loop t:=jsonb_set(t,array[k],to_jsonb((t->>k)::numeric+(c->>k)::numeric));end loop;
   sums:=jsonb_set(sums,array[aid],t);
  end loop;
 end loop;
 for aid,t in select x.key,x.value from jsonb_each(totals)x loop
  if t is distinct from sums->aid then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 end loop;
 for row_value in select value from jsonb_array_elements(p_prior->'correction_remaining')loop
  perform public.native_rx_keys(row_value,array['event_id','allocations']);eid:=public.native_correction_uuid(row_value->'event_id')::text;
  if ordinary?eid or jsonb_typeof(row_value->'allocations')is distinct from'array'or jsonb_array_length(row_value->'allocations')not between 1 and 100 then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  b:='{}';last_allocation:=null;
  for slot in select value from jsonb_array_elements(row_value->'allocations')loop
   perform public.native_rx_keys(slot,array['allocation_id','quantity']);candidate_id:=public.native_correction_uuid(slot->'allocation_id');aid:=candidate_id::text;s:=sources->aid;
   if s is null or(last_allocation is not null and candidate_id<=last_allocation)then raise exception 'adapter_source_integrity'using errcode='23514';end if;last_allocation:=candidate_id;
   n:=controlled_review_v3.read_return_quantity_number(slot->'quantity',(s->>'quantity')::numeric);b:=b||jsonb_build_object(aid,n);
  end loop;
  ordinary:=ordinary||jsonb_build_object(eid,jsonb_build_object('event',null,'remaining',b));ordinary_order:=array_append(ordinary_order,eid);seen:=seen||jsonb_build_object(eid,true);
 end loop;
 if p_event->>'action'like'retract_%'then
  perform public.native_rx_keys(p_target,array['action','allocations','correction_target_id','id','intake_id','sequence']);
  eid:=public.native_correction_uuid(p_target->'id')::text;
  if eid is distinct from p_event->>'correction_target_id'or ordinary->eid is null or(p_target->>'sequence')::integer>seq then raise exception 'adapter_source_integrity'using errcode='23514';end if;
