  for slot in select value from jsonb_array_elements(p_target->'allocations')loop
   aid:=slot->>'allocation_id';n:=(slot->>'quantity')::numeric;
   if ordinary#>array[eid,'remaining',aid]is null or(ordinary#>>array[eid,'remaining',aid])::numeric>n then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  end loop;
  ordinary:=jsonb_set(ordinary,array[eid,'event'],p_target);
 elsif p_target is not null and p_target is distinct from'null'::jsonb then raise exception 'adapter_source_integrity'using errcode='23514';end if;
 -- EXACT ORIGINAL SELECTED EVENT TRANSITION FOLLOWS. All inputs above are
 -- projected actual retained prefix data; no current/global history traversal.
 for e in select p_event loop
  seq:=seq+1;
  if jsonb_typeof(e) is distinct from 'object' then raise exception 'Invalid native return quantity history' using errcode='23514';end if;
  if (select array_agg(keys.k order by keys.k) from jsonb_object_keys(e) as keys(k)) is distinct from array['action','allocations','correction_target_id','id','intake_id','sequence']::text[]
   or jsonb_typeof(e->'id') is distinct from 'string' or (e->>'id') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   or seen ? (e->>'id') or e->'sequence' is distinct from to_jsonb(seq)
   or jsonb_typeof(e->'action') is distinct from 'string' or (e->>'action') not in('intake','dispose','restock','retract_intake','retract_disposal','retract_restock')
