 if adapter_value->>'site_id'is null then reason_value:='site_unproven';
 elsif event_value.event_kind in('record_native_dispense','record_native_pickup')then
  family_value:=controlled_review_v3.read_native_family((adapter_value->>'native_family_dispense_id')::uuid,event_value.product_id);
  if family_value is null then reason_value:='missing_managed_dispense_family';
  else
   family_id:=(family_value->>'dispense_id')::uuid;
   historical_value:=historical_value||jsonb_build_object('family_binding_hash',family_value->'binding_hash');
   reason_value:=family_value#>>'{selection,unavailable_reason}';
   if family_value->'site_id'is distinct from adapter_value->'site_id'then
    raise exception 'review_history_integrity'using errcode='23514';end if;
   if family_value#>>'{selection,policy_id}'is not null then
    policy_value:=controlled_review_v3.read_configuration_record((family_value#>>'{selection,policy_id}')::uuid);
    if policy_value->'record_hash'is distinct from family_value#>'{selection,policy_hash}'then
     raise exception 'review_history_integrity'using errcode='23514';end if;
   end if;
   choice_value:=family_value#>>'{selection,native_deadline_kind}';
  end if;
 else policy_value:=controlled_review_v3.read_policy_at(event_value.product_id,(adapter_value->>'site_id')::uuid,anchor_value);
 end if;
 if policy_value is not null then
  rule_value:=policy_value#>array['body','rules',event_value.event_kind];
  if rule_value is null then raise exception 'review_history_integrity'using errcode='23514';end if;
  references_value:=controlled_review_v3.read_policy_references(policy_value);
  historical_value:=historical_value||jsonb_build_object('policy_id',policy_value->'id','policy_hash',policy_value->'record_hash','rule',rule_value,
   'calendar_id',references_value#>'{calendar,id}','calendar_hash',references_value#>'{calendar,record_hash}',
   'routing_id',references_value#>'{routing,id}','routing_hash',references_value#>'{routing,record_hash}',
   'routing_snapshot',controlled_review_v3.protocol_routing_snapshot(references_value->'routing'));
  if reason_value is null and policy_value->'enabled'is distinct from 'true'::jsonb then reason_value:='policy_disabled_at_anchor';end if;
 elsif reason_value is null then reason_value:='no_policy_at_anchor';end if;
 if reason_value is null then
  if event_value.event_kind in('record_native_dispense','record_native_pickup')and choice_value is not null and choice_value<>event_value.event_kind then
   historical_value:=historical_value||jsonb_build_object('deadline_basis','not_assigned','unavailable_reason','other_native_kind_selected');
  elsif rule_value->'enabled'is distinct from 'true'::jsonb or rule_value->>'deadline_mode'='not_configured'then
   historical_value:=historical_value||jsonb_build_object('deadline_basis','not_configured','unavailable_reason','kind_not_configured');
  else
   if rule_value->>'deadline_mode'<>'next_staffed_day_close'or references_value#>>'{calendar,id}'is null then
    raise exception 'review_history_integrity'using errcode='23514';end if;
   deadline_value:=controlled_review_v3.protocol_deadline(references_value->'calendar',anchor_value);
   historical_value:=historical_value||deadline_value;
  end if;
 else historical_value:=historical_value||jsonb_build_object('unavailable_reason',reason_value);end if;
 result_value:=jsonb_build_object('event_id',event_value.id,'product_id',event_value.product_id,'event_sequence',event_value.sequence::text,
  'meaning','independent_record_review_v1','target',adapter_value->'target','target_hash',public.controlled_stock_hash(adapter_value->'target'),
  'adapter',adapter_value,'historical',historical_value,'site_id',adapter_value->'site_id','due_at',historical_value->'due_at','family_dispense_id',family_id);
 return result_value||jsonb_build_object('binding_hash',public.controlled_stock_hash(result_value));
end

controlled_review_v3.read_scalar_preflig.source:
declare r public.controlled_stock_preparations;c jsonb;l jsonb;prior uuid;total integer:=0;n integer;native_dispense uuid;native_intake uuid;
begin
 select *into r from public.controlled_stock_preparations where id=p_id;
 if r.id is null or r.writer not in('receive_inventory','adjust_inventory','record_patient_treatment','record_anesthesia_drug_administration','record_native_dispense','record_native_pickup','append_native_dispense_correction','record_native_return_discrepancy','record_native_dispense_return','record_native_dispense_return_v2')or octet_length(r.context::text)>262144 or octet_length(r.frozen::text)>1048576 then
 raise exception 'review_history_integrity'using errcode='23514';end if;
 perform controlled_review_v3.read_validate_parent_request(to_jsonb(r));
 if r.writer='record_native_dispense'then native_dispense:=r.id;
 elsif r.writer='append_native_dispense_correction'then select dispense_id into native_dispense from public.native_dispense_correction_events where id=r.id;
  if native_dispense is null then raise exception 'review_history_integrity'using errcode='23514';end if;
 elsif r.writer in('record_native_dispense_return','record_native_dispense_return_v2')then select dispense_id,coalesce(intake_id,id)into native_dispense,native_intake from public.native_return_events where id=r.id;
  if native_dispense is null then raise exception 'review_history_integrity'using errcode='23514';end if;
 elsif r.writer='record_native_return_discrepancy'then select dispense_id into native_dispense from public.native_return_discrepancy_events where id=r.id;
  if native_dispense is null then raise exception 'review_history_integrity'using errcode='23514';end if;
 elsif r.writer='record_native_pickup'then select dispense_id into native_dispense from public.native_pickups where id=r.id;
  if native_dispense is null then raise exception 'review_history_integrity'using errcode='23514';end if;end if;
 perform public.controlled_stock_keys(r.context,array['version','product_id','policy_version_id','state_head_id','opening_id','basis','containers']);
 if r.context->'version'is distinct from '1'::jsonb or jsonb_typeof(r.context->'containers')is distinct from 'array'
 or jsonb_array_length(r.context->'containers')>32 then raise exception 'review_history_integrity'using errcode='23514';end if;
 for c in select value from jsonb_array_elements(r.context->'containers')loop
  perform public.controlled_stock_keys(c,array['id','expected_version','create','after','lines']);
  if prior is not null and public.controlled_stock_uuid(c->'id')<=prior then raise exception 'review_history_integrity'using errcode='23514';end if;
  prior:=public.controlled_stock_uuid(c->'id');
  if jsonb_typeof(c->'lines')is distinct from 'array'or jsonb_array_length(c->'lines')>100 then raise exception 'review_history_integrity'using errcode='23514';end if;
  total:=total+jsonb_array_length(c->'lines');
  for l in select value from jsonb_array_elements(c->'lines')loop
   perform public.controlled_stock_keys(l,array['lot_id','channel','dispense_id','intake_id','quantity_delta']);
   if l->'channel'='"available"'::jsonb then
    if l->'dispense_id'is distinct from 'null'::jsonb or l->'intake_id'is distinct from 'null'::jsonb then raise exception 'review_history_integrity'using errcode='23514';end if;
   elsif l->'channel'='"prepared"'::jsonb and native_dispense is not null then
    if public.controlled_stock_uuid(l->'dispense_id')is distinct from native_dispense or l->'intake_id'is distinct from 'null'::jsonb then raise exception 'review_history_integrity'using errcode='23514';end if;
   elsif l->'channel'='"return_held"'::jsonb and r.writer in('record_native_dispense_return','record_native_dispense_return_v2')then
    if public.controlled_stock_uuid(l->'dispense_id')is distinct from native_dispense or public.controlled_stock_uuid(l->'intake_id')is distinct from native_intake then raise exception 'review_history_integrity'using errcode='23514';end if;
   else raise exception 'review_history_integrity'using errcode='23514';end if;
   perform public.controlled_stock_uuid(l->'lot_id');perform public.controlled_stock_decimal(l->'quantity_delta');
  end loop;
 end loop;
 if total>200 then raise exception 'review_history_integrity'using errcode='23514';end if;
 select count(*)into n from(select 1 from public.controlled_stock_event_lines where event_id=p_id limit 201)q;
 if n>200 then raise exception 'review_history_integrity'using errcode='23514';end if;
 select count(*)into n from(select 1 from public.controlled_stock_container_transitions where event_id=p_id limit 33)q;
 if n>32 then raise exception 'review_history_integrity'using errcode='23514';end if;
 select count(*)into n from(select 1 from public.controlled_stock_source_links where event_id=p_id limit 102)q;
 if n>101 or(r.writer in('receive_inventory','adjust_inventory','record_patient_treatment','record_anesthesia_drug_administration')and n<>1)or(r.writer='record_native_dispense'and n not between 1 and 100)or(r.writer in('record_native_pickup','append_native_dispense_correction')and n<>1)or(r.writer in('record_native_dispense_return','record_native_dispense_return_v2')and n not between 1 and 101)then raise exception 'review_history_integrity'using errcode='23514';end if;
end

controlled_review_v3.read_scalar_project.source:
declare adapter_value jsonb:=p_base->'adapter';event_value jsonb:=p_base->'event';obligation_value jsonb:=p_base->'obligation';history_value jsonb;
 configs_value jsonb;ids jsonb;facts_value jsonb;authorization_value jsonb;candidate_authorization jsonb;authorizations_value jsonb:='[]'::jsonb;member_value jsonb;fact jsonb;route_value jsonb;
 policy_status text;capacity_value jsonb;current_bytes integer;packet_value jsonb;states_value jsonb;summary_value jsonb;terminal_state jsonb;reasons text[]:='{}';route_eligible boolean:=false;
 candidate_id uuid;required_value boolean:=(p_base#>>'{event,secondary_review_required}')::boolean;unresolved boolean;
begin
 configs_value:=controlled_review_v3.read_current_configs(adapter_value,p_as_of);
 history_value:=controlled_review_v3.read_scalar_history(p_base);unresolved:=history_value->'terminal_review'='null'::jsonb;
 route_value:=obligation_value#>'{historical,routing_snapshot}';
 select coalesce(jsonb_agg(to_jsonb(id_value)order by id_value),'[]'::jsonb)into ids from(
 select p_actor_id::text id_value union select value->>'actor_id'from jsonb_array_elements(coalesce(configs_value#>'{read,body,members}','[]'::jsonb))
 union select value->>'actor_id'from jsonb_array_elements(coalesce(route_value->'members','[]'::jsonb)))q;
 -- <=100 named read members includes every potential signer, plus100 route members and viewer.
 facts_value:=controlled_review_v3.read_named_facts(ids);
 authorization_value:=controlled_review_v3.read_authorizations(configs_value,p_actor_id,adapter_value->>'event_kind',facts_value);
 if authorization_value->'read'='null'::jsonb then raise exception 'read_denied'using errcode='42501';end if;
 policy_status:=case when configs_value->'policy'='null'::jsonb then 'missing'when configs_value#>'{policy,enabled}'='false'::jsonb then 'disabled'else 'enabled'end;
 for member_value in select value from jsonb_array_elements(coalesce(configs_value#>'{read,body,members}','[]'::jsonb))loop
  candidate_id:=(member_value->>'actor_id')::uuid;
  if candidate_id::text<>p_base#>>'{target,original_actor_id}'then
   candidate_authorization:=controlled_review_v3.read_authorizations(configs_value,candidate_id,adapter_value->>'event_kind',facts_value);
   if candidate_authorization->'policy'<>'null'::jsonb and candidate_authorization->'read'<>'null'::jsonb and candidate_authorization->'review'<>'null'::jsonb then
    authorizations_value:=authorizations_value||jsonb_build_array(candidate_authorization);
   end if;
  end if;
 end loop;
 capacity_value:=controlled_review_v3.protocol_packet_capacity(p_base,authorizations_value);
 if route_value is not null and route_value<>'null'::jsonb and route_value->'enabled'='true'::jsonb then
  for member_value in select value from jsonb_array_elements(route_value->'members')loop
   fact:=facts_value->(member_value->>'actor_id');
   if fact->'active'='true'::jsonb and exists(select 1 from jsonb_array_elements_text(member_value->'roles')r(role_value)join jsonb_array_elements_text(fact->'roles')a(role_value)using(role_value))then route_eligible:=true;end if;
  end loop;
 end if;
 if required_value and unresolved then
  if obligation_value->'due_at'<>'null'::jsonb and p_as_of>controlled_review_v3.protocol_instant(obligation_value->'due_at')then reasons:=array_append(reasons,'overdue');end if;
  if jsonb_array_length(authorizations_value)=0 or(capacity_value->>'within_limit')::integer=0 then reasons:=array_append(reasons,'no_eligible_reviewer');end if;
  if not route_eligible then reasons:=array_append(reasons,'routing_unavailable');end if;
  if capacity_value->'base_alone_exceeds_limit'='true'::jsonb or capacity_value->'all_candidates_exceed_limit'='true'::jsonb then reasons:=array_append(reasons,'evidence_unavailable');end if;
 end if;
 if required_value and event_value->>'event_kind'='record_native_return_discrepancy:report'
  and obligation_value#>'{historical,rule,enabled}'='true'::jsonb
  and obligation_value#>>'{historical,rule,escalation_mode}'='immediate_on_record'then
  reasons:=array_append(reasons,'discrepancy_report');
 end if;
 select coalesce(array_agg(reason_value order by reason_value collate "C"),'{}'::text[])into reasons from unnest(reasons)q(reason_value)
 where not exists(select 1 from jsonb_array_elements(history_value->'escalations')x where x->>'reason'=reason_value);
 terminal_state:=case when history_value->'terminal_review'='null'::jsonb then 'null'::jsonb else jsonb_build_object('decision',history_value#>'{terminal_review,decision}','recorded_at',history_value#>'{terminal_review,recorded_at}')end;
 states_value:=controlled_review_v3.protocol_review_states(jsonb_build_object('secondary_review_required',event_value->'secondary_review_required','actor_id',p_actor_id,
 'original_actor_id',p_base#>'{target,original_actor_id}','adapter',adapter_value,'current_authorization',authorization_value,'current_policy_status',policy_status,
 'terminal_decision',terminal_state,'as_of',controlled_review_v3.protocol_utc(p_as_of),'obligation',obligation_value));
 current_bytes:=octet_length(p_base::text)+octet_length(to_jsonb('current_authorization'::text)::text)+4+octet_length(authorization_value::text);
 if current_bytes>1048576 and required_value and unresolved then states_value:=states_value||jsonb_build_object('signing_state','blocked','signing_reason','evidence_limit_exceeded');end if;
 summary_value:=jsonb_build_object('event_id',event_value->'id','event_sequence',event_value->>'sequence','event_kind',event_value->'event_kind','site_basis',adapter_value->'site_basis','site_id',adapter_value->'site_id',
 'observed_at',event_value->'observed_at','recorded_at',event_value->'recorded_at')||states_value;
 if current_bytes>1048576 then return jsonb_build_object('version',3,'state','exception','data',jsonb_build_object('summary',summary_value),'_configuration_ids',jsonb_build_object('policy',configs_value#>'{policy,id}','read',configs_value#>'{read,id}','review',configs_value#>'{review,id}'));end if;
 packet_value:=p_base||jsonb_build_object('current_authorization',authorization_value);
 return jsonb_build_object('version',3,'state','detail','_configuration_ids',jsonb_build_object('policy',configs_value#>'{policy,id}','read',configs_value#>'{read,id}','review',configs_value#>'{review,id}'),'data',jsonb_build_object('summary',summary_value,'packet',packet_value,'terminal_review',history_value->'terminal_review',
 'escalations',history_value->'escalations','derived_escalation_reasons',to_jsonb(reasons),'policy_id',authorization_value#>'{policy,id}','read_eligibility_id',authorization_value#>'{read,id}','review_eligibility_id',authorization_value#>'{review,id}'));
end

controlled_review_v3.read_scope_authoriz.source:
declare stream_value jsonb;record_value jsonb;authorization_value jsonb;
begin
 perform controlled_review_v3.protocol_identity(p_actor_id);
 stream_value:=jsonb_build_object('kind','eligibility','product_id',p_product_id,'site_id',p_site_id,'event_kind',p_kind,'capability',case when p_exception then 'exception_read'else 'read'end);
 record_value:=controlled_review_v3.protocol_select_configuration(jsonb_build_object('stream_key',stream_value,'at',controlled_review_v3.protocol_utc(clock_timestamp())));
 if record_value is null then raise exception 'read_denied'using errcode='42501';end if;
 begin authorization_value:=controlled_review_v3.protocol_read_authorization(jsonb_build_object('actor_id',p_actor_id,'read_eligibility_id',record_value->'id'));
 exception when insufficient_privilege then raise exception 'read_denied'using errcode='42501';end;
 return jsonb_build_object('id',record_value->'id','fingerprint',authorization_value->'read_authorization_hash');
end

controlled_review_v3.read_select_configu.source:
declare stream_value jsonb;at_value timestamptz;selected_id uuid;
begin
 if jsonb_typeof(p_request)is distinct from 'object'or octet_length(p_request::text)>8192 then
  raise exception 'review_selection_invalid'using errcode='23514';end if;
 perform public.controlled_stock_keys(p_request,array['stream_key','at']);
 stream_value:=controlled_review_v3.protocol_stream_key(p_request->'stream_key');
 at_value:=controlled_review_v3.protocol_instant(p_request->'at');
 if stream_value->>'kind'='policy'then
  select id into selected_id from controlled_review_v3.configuration
   where stream_key=stream_value and effective_from<=at_value and published_at<=at_value
   order by effective_from desc,version desc limit 1;
 else
  select id into selected_id from controlled_review_v3.configuration
   where stream_key=stream_value and published_at<=at_value order by version desc limit 1;
 end if;
 if selected_id is null then return null;end if;
 -- No enabled filter: a disabled newest/selected record suppresses prior rows.
 return controlled_review_v3.read_configuration_record(selected_id);
end

controlled_review_v3.read_site_candidate.source:
declare e public.controlled_stock_events;c public.native_dispense_correction_events;site_value uuid;assertion_site uuid;did uuid;
begin
 select *into e from public.controlled_stock_events where id=p_event_id;
 if e.event_kind in('receive_inventory','adjust_inventory','record_patient_treatment','record_anesthesia_drug_administration','record_native_dispense','record_native_pickup')then return controlled_review_v3.read_adapter_site(e.id);end if;
 if e.writer in('record_native_dispense_return','record_native_dispense_return_v2')then
  select dispense_id into did from public.native_return_events where id=e.id and document->>'version'=case e.writer when'record_native_dispense_return'then'1'else'2'end;
  if exists(select 1 from public.controlled_stock_events d where d.id=did and d.writer='record_native_dispense'and d.product_id=e.product_id)then site_value:=(controlled_review_v3.read_adapter_site(did)->>'site_id')::uuid;end if;
  assertion_site:=(controlled_review_v3.read_adapter_site(e.id)->>'site_id')::uuid;
  if assertion_site is not null and assertion_site is distinct from site_value then return jsonb_build_object('site_id',null);end if;
  return jsonb_build_object('site_id',site_value);
 end if;
 if e.writer='record_native_return_discrepancy'then
  select(document#>>'{source,event_id}')::uuid into did from public.native_return_discrepancy_events where id=e.id;
  if exists(select 1 from public.controlled_stock_events r where r.id=did and r.product_id=e.product_id and r.writer in('record_native_dispense_return','record_native_dispense_return_v2'))then site_value:=(controlled_review_v3.read_adapter_site(did)->>'site_id')::uuid;end if;
  assertion_site:=(controlled_review_v3.read_adapter_site(e.id)->>'site_id')::uuid;
  if assertion_site is not null and assertion_site is distinct from site_value then return jsonb_build_object('site_id',null);end if;
  return jsonb_build_object('site_id',site_value);
 end if;
 if e.writer is distinct from 'append_native_dispense_correction'then return jsonb_build_object('site_id',null);end if;
 select *into c from public.native_dispense_correction_events where id=e.id;
 if c.id is null then return jsonb_build_object('site_id',null);end if;
 -- This immutable parent is only a routing candidate. Source links/complete
 -- canonical validation and exact site equality still run AFTER fresh auth.
 if exists(select 1 from public.controlled_stock_events d where d.id=c.dispense_id and d.writer='record_native_dispense'and d.product_id=e.product_id)then
  site_value:=(controlled_review_v3.read_adapter_site(c.dispense_id)->>'site_id')::uuid;
 elsif e.event_kind in('append_native_dispense_correction:clinical_annotation','append_native_dispense_correction:operational_annotation')then
  site_value:=(controlled_review_v3.read_annotation_opening_candidate(e.id,c.dispense_id,e.product_id)->>'site_id')::uuid;
 end if;
 assertion_site:=(controlled_review_v3.read_adapter_site(e.id)->>'site_id')::uuid;
 if assertion_site is not null and assertion_site is distinct from site_value then return jsonb_build_object('site_id',null);end if;
 return jsonb_build_object('site_id',site_value);
end

controlled_review_v3.read_source_bundle(.source:
declare expected jsonb;native_document jsonb;native_kind text;dispense uuid;
 product uuid;products uuid[];available jsonb;allocations jsonb;
 movement_count integer;actual_actor uuid;source_count integer;return_source jsonb;verified_dispense jsonb;
begin
 if p_root is null or p_actor is null or p_result is null then
  raise exception 'Exact controlled source identity required'using errcode='23514';end if;
 case p_writer
 when 'receive_inventory','adjust_inventory'then
  select to_jsonb(m),m.created_by into expected,actual_actor
  from public.inventory_movements m where m.id=p_root;
 when 'record_patient_treatment'then
  select to_jsonb(t),t.created_by into expected,actual_actor
  from public.patient_treatments t where t.id=p_root and not t.historical;
 when 'record_anesthesia_drug_administration'then
  -- The outer writer returns its treatment row, not the separate audit link.
  select to_jsonb(t),a.created_by into expected,actual_actor
  from public.anesthesia_drug_administrations a
  join public.patient_treatments t on t.id=a.id and t.created_by=a.created_by
  where a.id=p_root;
 when 'record_native_dispense'then
  select public.native_fulfillment_receipt(o),d.actor_id,d.id,d.document
  into expected,actual_actor,dispense,native_document
  from public.native_dispenses d join public.native_fulfillment_operations o
   on o.id=d.id and o.operation='dispense'and o.actor_id=d.actor_id
  where d.id=p_root and o.result->'dispense'=d.document;
  native_kind:='dispense';
 when 'record_native_dispense_return','record_native_dispense_return_v2'then
  select e.actor_id,e.dispense_id,e.document into actual_actor,dispense,native_document
  from public.native_return_events e join public.stock_custody_sources s
   on s.event_id=e.id and s.actor_id=e.actor_id and s.writer=p_writer
  join public.native_return_operations o on o.id=e.id and o.actor_id=e.actor_id and o.result=e.document
  where e.id=p_root and e.document->>'version'=case p_writer when 'record_native_dispense_return'then '1'else '2'end;
  if p_writer='record_native_dispense_return'then
   select public.native_return_receipt(o)into expected from public.native_return_operations o where o.id=p_root;
  else
   select jsonb_build_object('version',2,'id',o.id,'actor_id',o.actor_id,'request',o.request,
    'request_hash',o.request_hash,'result',o.result,'created_at',o.created_at)into expected
   from public.native_return_operations o where o.id=p_root;
  end if;
  -- Provenance remains verifiable after the original recorder retires. This
  -- private data reader must not borrow an owner-only recovery RPC's Auth gate.
  perform controlled_review_v3.read_return_capture(p_root,(select i.product_id from public.native_dispenses d join public.billing_invoice_items i on i.id=d.invoice_item_id where d.id=dispense));
  native_kind:='return';
  select jsonb_build_object('action',e.action,'intake_id',coalesce(e.intake_id,e.id),
   'intake_document',i.document,'intake_reviewed_context',i.reviewed_context)
  into return_source from public.native_return_events e
  join public.native_return_events i on i.id=coalesce(e.intake_id,e.id)
   and i.action='intake'and i.dispense_id=e.dispense_id
  where e.id=p_root;
  if return_source is null then raise exception 'Exact original intake source required'using errcode='23514';end if;
 when 'record_native_return_discrepancy'then
  select e.actor_id,e.dispense_id,e.document into actual_actor,dispense,native_document
  from public.native_return_discrepancy_events e join public.stock_discrepancy_sources s on s.event_id=e.id and s.actor_id=e.actor_id
  join public.native_return_discrepancy_operations o on o.id=e.id and o.actor_id=e.actor_id and o.result=e.document where e.id=p_root;
  select jsonb_build_object('version',1,'id',o.id,'actor_id',o.actor_id,'request',o.request,'request_hash',o.request_hash,'result',o.result,'created_at',o.created_at)into expected from public.native_return_discrepancy_operations o where o.id=p_root;
  perform controlled_review_v3.read_discrepancy_capture(p_root,(select i.product_id from public.native_dispenses d join public.billing_invoice_items i on i.id=d.invoice_item_id where d.id=dispense));
  native_kind:='discrepancy';
 when 'record_native_pickup'then
  select public.native_fulfillment_receipt(o),e.actor_id,e.dispense_id,e.document
  into expected,actual_actor,dispense,native_document
  from public.native_pickups e join public.stock_pickup_sources s on s.event_id=e.id and s.actor_id=e.actor_id
  join public.native_fulfillment_operations o on o.id=e.id and o.operation='pickup'and o.actor_id=e.actor_id and o.result=e.document
  where e.id=p_root;
  native_kind:='pickup';
 when 'append_native_dispense_correction'then
  select public.native_correction_receipt(o),e.actor_id,e.dispense_id,e.document into expected,actual_actor,dispense,native_document
  from public.native_dispense_correction_events e join public.stock_correction_sources s on s.event_id=e.id and s.actor_id=e.actor_id
  join public.native_dispense_correction_operations o on o.id=e.id and o.actor_id=e.actor_id and o.result=e.document where e.id=p_root;
  native_kind:='correction';
 else raise exception 'read_native_pending'using errcode='0A000';
 end case;
 if expected is null or expected is distinct from p_result or actual_actor is distinct from p_actor then
  raise exception 'Original controlled canonical receipt required'using errcode='23514';end if;

 if native_kind is not null then
  perform controlled_review_v3.read_dispense_capture(dispense,(select i.product_id from public.native_dispenses d join public.billing_invoice_items i on i.id=d.invoice_item_id where d.id=dispense));
  if native_kind='pickup'and(public.controlled_stock_opening_pickup(dispense)->>'id')is distinct from p_root::text then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  if native_kind='correction'then perform controlled_review_v3.read_correction_capture(p_root,(select i.product_id from public.native_dispenses d join public.billing_invoice_items i on i.id=d.invoice_item_id where d.id=dispense));end if;
 end if;
 -- Keep every actual signed movement as a distinct source; never net opposing
 -- compensation entries or assign meaning by the order of generated UUIDs.
 select count(*)::integer into source_count from(select 1 from public.stock_movement_sources s
  where s.writer=p_writer and s.source_id=p_root limit 101)bounded;
 if source_count>100 then raise exception 'Bounded controlled source movements required'using errcode='23514';end if;
 if exists(select 1 from public.stock_movement_sources s where s.writer=p_writer and s.source_id=p_root and s.actor_id is distinct from p_actor)then
  raise exception 'Exact controlled source actor required'using errcode='23514';end if;
 perform controlled_review_v3.read_stock_source(s.movement_id)
 from public.stock_movement_sources s where s.writer=p_writer and s.source_id=p_root;
 select count(*)::integer,array_agg(distinct l.product_id),coalesce(jsonb_agg(jsonb_build_object(
  'kind','movement','id',m.id,'lot_id',m.lot_id,'product_id',l.product_id,
  'quantity_delta',m.quantity::text,'native_kind',m.kind
 )order by m.id),'[]'::jsonb)into movement_count,products,available
 from public.stock_movement_sources s join public.inventory_movements m on m.id=s.movement_id
 join public.inventory_lots l on l.id=m.lot_id
 where s.writer=p_writer and s.source_id=p_root and s.actor_id=p_actor;
 if p_writer in('receive_inventory','adjust_inventory','record_patient_treatment','record_anesthesia_drug_administration')then
  if movement_count<>1 then raise exception 'One original controlled stock movement required'using errcode='23514';end if;
 elsif p_writer in('record_native_return_discrepancy','record_native_pickup','append_native_dispense_correction')and movement_count<>0 then
  raise exception 'Custody or annotation cannot invent available stock effects'using errcode='23514';
 end if;

 if native_kind is not null then
  if native_document is null or dispense is null then raise exception 'Exact native controlled source required'using errcode='23514';end if;
  if(select count(*)from(select 1 from public.native_dispense_allocations where dispense_id=dispense limit 101)q)not between 1 and 100
   or not exists(select 1 from public.native_dispenses d where d.id=dispense and jsonb_typeof(d.document#>'{reviewed_context,lots}')='array'and jsonb_array_length(d.document#>'{reviewed_context,lots}')between 1 and 100)then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  verified_dispense:=public.native_fulfillment_verified_dispense(dispense);
  if verified_dispense is null or(native_kind='dispense'and verified_dispense is distinct from native_document)then
   raise exception 'Verified original native dispense required'using errcode='23514';end if;
  select array_agg(distinct l.product_id),count(*)::integer,coalesce(jsonb_agg(jsonb_build_object(
   'allocation_id',a.id,'dispense_id',a.dispense_id,'lot_id',a.lot_id,
   'movement_id',a.movement_id,'quantity',a.quantity::text
  )order by a.lot_id),'[]'::jsonb)into products,source_count,allocations
  from public.native_dispense_allocations a join public.inventory_lots l on l.id=a.lot_id
  where a.dispense_id=dispense;
  if source_count not between 1 and 100 or cardinality(products)<>1 then
   raise exception 'Exact single-product native allocation membership required'using errcode='23514';end if;
  if p_writer='record_native_dispense'and movement_count<>source_count then
   raise exception 'Every controlled dispense allocation needs its original debit'using errcode='23514';end if;
 end if;
 if cardinality(products)is distinct from 1 then
  raise exception 'One exact controlled source product required'using errcode='23514';end if;
 product:=products[1];
 if exists(select 1 from jsonb_array_elements(available)source where(source->>'product_id')::uuid is distinct from product)then
  raise exception 'Controlled source product membership changed'using errcode='23514';end if;
 -- The caller must still reconcile per-source custody effects to its frozen
 -- container slots. Returning this bundle never authorizes or posts an event.
 return jsonb_build_object('version',1,'writer',p_writer,'root',p_root,
  'actor_id',p_actor,'product_id',product,'available',available,
  'native',case when native_kind is null then 'null'::jsonb else
   jsonb_build_object('kind',native_kind,'id',p_root,'dispense_id',dispense,
    'document',native_document,'original_allocations',allocations,
    'return_source',coalesce(return_source,'null'::jsonb))end);
end

controlled_review_v3.read_source_effects.source:
declare b jsonb:=controlled_review_v3.read_source_bundle(p_writer,p_root,p_actor,p_result);
 n jsonb:=b->'native';a jsonb;original jsonb;available jsonb:=b->'available';
 custody jsonb:='[]';kind text:=n->>'kind';action text;delta numeric;
 lot uuid;allocation uuid;movement uuid;intake uuid;dispense uuid;quantity numeric;
 prepared_factor integer;held_factor integer;basis text:='stock_record';requirements jsonb:='{}';
begin
 if n<>'null'::jsonb then dispense:=(n->>'dispense_id')::uuid;end if;
 if kind in('dispense','pickup')then
  basis:=case kind when 'dispense'then 'preparation_record'else 'handoff_record'end;
  requirements:=case kind when 'pickup'then
   '{"complete_original_prepared_package":true,"expected_container_heads_required":true}'::jsonb
   else '{"exact_available_container_allocations_required":true}'::jsonb end;
  for a in select value from jsonb_array_elements(n->'original_allocations')loop
   quantity:=(a->>'quantity')::numeric;allocation:=(a->>'allocation_id')::uuid;lot:=(a->>'lot_id')::uuid;
   if quantity<=0 then raise exception 'Positive original custody allocation required'using errcode='23514';end if;
   if kind='dispense'then
    if(select count(*)from jsonb_array_elements(available)m where m->>'id'=a->>'movement_id'
     and m->>'lot_id'=lot::text and(m->>'quantity_delta')::numeric=-quantity)<>1 then
     raise exception 'Exact original available debit required'using errcode='23514';end if;
   end if;
   custody:=custody||jsonb_build_array(jsonb_build_object('source_kind',kind,'source_id',p_root,
    'allocation_id',allocation,'lot_id',lot,'dispense_id',dispense,'intake_id',null,
    'channel','prepared','quantity_delta',(case kind when 'dispense'then quantity else -quantity end)::text));
  end loop;
 elsif kind='return'then
  action:=n#>>'{return_source,action}';intake:=(n#>>'{return_source,intake_id}')::uuid;
  if action is distinct from n#>>'{document,action}'or intake is null then
   raise exception 'Exact return action and intake identity required'using errcode='23514';end if;
  basis:=case when action like 'retract_%'then 'correction_assertion'else 'custody_record'end;
  -- These are explicit eligibility requirements, not an authorization result.
  -- A recorded-in-error pickup amendment never proves clinic-retained custody.
  requirements:=jsonb_build_object('original_intake_id',intake,
   'original_intake_custody',n#>'{return_source,intake_document,custody}',
   'clinic_retained_before_handoff_required',true,
   'actual_original_pickup_must_be_checked',true,'expected_container_heads_required',true,
   'explicit_restock_destination_required',action in('restock','retract_restock'));
  case action
   when 'intake'then prepared_factor:=-1;held_factor:=1;
   when 'dispose'then prepared_factor:=0;held_factor:=-1;
   when 'restock'then prepared_factor:=0;held_factor:=-1;
   when 'retract_intake'then prepared_factor:=1;held_factor:=-1;
   when 'retract_disposal'then prepared_factor:=0;held_factor:=1;
   when 'retract_restock'then prepared_factor:=0;held_factor:=1;
   else raise exception 'Reviewed return source action required'using errcode='23514';
  end case;
  if jsonb_array_length(n#>'{document,allocations}')not between 1 and 100 then
   raise exception 'Bounded exact return allocation membership required'using errcode='23514';end if;
  if(select count(*)<>count(distinct value->>'allocation_id')from jsonb_array_elements(n#>'{document,allocations}'))then
   raise exception 'Unique return source allocation required'using errcode='23514';end if;
  for a in select value from jsonb_array_elements(n#>'{document,allocations}')loop
   allocation:=(a->>'allocation_id')::uuid;lot:=(a->>'lot_id')::uuid;quantity:=(a->>'quantity')::numeric;
   select value into original from jsonb_array_elements(n->'original_allocations')
    where value->>'allocation_id'=allocation::text and value->>'lot_id'=lot::text;
   if original is null or quantity<=0 or quantity>(original->>'quantity')::numeric then
    raise exception 'Exact positive original return allocation required'using errcode='23514';end if;
   if action in('restock','retract_restock')then
    movement:=(a->>'movement_id')::uuid;delta:=case action when 'restock'then quantity else -quantity end;
    if movement is null or(select count(*)from jsonb_array_elements(available)m where
     m->>'id'=movement::text and m->>'lot_id'=lot::text and(m->>'quantity_delta')::numeric=delta)<>1 then
     raise exception 'Exact signed available return movement required'using errcode='23514';end if;
   elsif a->'movement_id'is distinct from 'null'::jsonb then
    raise exception 'Custody-only source cannot invent available stock'using errcode='23514';
   end if;
   if prepared_factor<>0 then
    custody:=custody||jsonb_build_array(jsonb_build_object('source_kind','return','source_id',p_root,
     'allocation_id',allocation,'lot_id',lot,'dispense_id',dispense,'intake_id',null,
     'channel','prepared','quantity_delta',(quantity*prepared_factor)::text));
   end if;
   custody:=custody||jsonb_build_array(jsonb_build_object('source_kind','return','source_id',p_root,
    'allocation_id',allocation,'lot_id',lot,'dispense_id',dispense,'intake_id',intake,
    'channel','return_held','quantity_delta',(quantity*held_factor)::text));
  end loop;
  if jsonb_array_length(available)<>(case when action in('restock','retract_restock')then
   jsonb_array_length(n#>'{document,allocations}')else 0 end)then
   raise exception 'Every available return movement must have one exact allocation'using errcode='23514';end if;
 elsif kind='discrepancy'then
  basis:='discrepancy_assertion';
  requirements:='{"native_and_controlled_holds_must_compose":true}'::jsonb;
 elsif kind='correction'then
  basis:='annotation';
  requirements:='{"annotation_cannot_restore_stock_or_prove_physical_return":true}'::jsonb;
 end if;
 return jsonb_build_object('version',1,'writer',p_writer,'root',p_root,'actor_id',p_actor,
  'product_id',b->'product_id','basis',basis,'available',available,'custody',custody,
  'requirements',requirements,'authorizes_execution',false);
end

controlled_review_v3.read_stock_source(p.source:
declare s public.stock_movement_sources;m public.inventory_movements;valid boolean:=false;
begin
 select *into s from public.stock_movement_sources where movement_id=p_id;
 if not found then raise exception 'Stock movement source required'using errcode='23514';end if;
 select *into m from public.inventory_movements where id=p_id;
 if not found or m.created_by is distinct from s.actor_id then raise exception 'Stock movement source mismatch'using errcode='23514';end if;
 case s.writer when 'receive_inventory'then valid:=m.id=s.source_id and m.kind='receive'and m.quantity>0;
 when 'adjust_inventory'then valid:=m.id=s.source_id and m.kind='adjust'and m.quantity<>0;
 when 'record_patient_treatment','record_anesthesia_drug_administration'then
  valid:=m.id=s.source_id and m.kind='dispense'and exists(
   select 1 from public.patient_treatments t where t.id=s.source_id and not t.historical
   and t.lot_id=m.lot_id and t.quantity=-m.quantity and t.created_by=s.actor_id and t.created_at=m.created_at);
  if s.writer='record_anesthesia_drug_administration'then
   valid:=valid and exists(select 1 from public.anesthesia_drug_administrations a join public.patient_treatments t on t.id=a.id
    where a.id=s.source_id and a.created_by=s.actor_id and a.pet_id=t.pet_id and a.request=t.request
    and t.source='Anesthesia record '||a.record_id::text);
  end if;
 when 'record_native_dispense' then
  if(select count(*)from(select 1 from public.native_dispense_allocations where dispense_id=s.source_id limit 101)q)>100 then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  valid:=m.kind='dispense' and exists(
   select 1 from public.native_dispense_allocations a join public.native_dispenses d on d.id=a.dispense_id
   join public.native_fulfillment_operations o on o.id=d.id and o.operation='dispense'
   where d.id=s.source_id and d.actor_id=s.actor_id and a.movement_id=p_id
   and a.lot_id=m.lot_id and a.quantity=-m.quantity
   and o.actor_id=d.actor_id and o.result->'dispense'=d.document
   and jsonb_array_length(d.document->'allocations')=(select count(*)from public.native_dispense_allocations other where other.dispense_id=d.id)
   and d.quantity=(select sum(other.quantity)from public.native_dispense_allocations other where other.dispense_id=d.id)
   and exists(select 1 from jsonb_array_elements(d.document->'allocations')line where line->>'movement_id'=p_id::text and line->>'lot_id'=m.lot_id::text and (line->>'quantity')::numeric=a.quantity)
  );
 when 'record_native_dispense_return','record_native_dispense_return_v2' then
  if(select count(*)from(select 1 from public.native_return_stock_links where event_id=s.source_id limit 101)q)>100 then raise exception 'adapter_source_integrity'using errcode='23514';end if;
  valid:=exists(select 1 from public.native_return_events e join public.native_return_operations o on o.id=e.id where e.id=s.source_id
   and e.actor_id=s.actor_id and e.created_at=m.created_at
   and o.actor_id=e.actor_id and o.result=e.document
   and e.document->>'version'=case s.writer when 'record_native_dispense_return' then '1' else '2' end
   and exists(select 1 from jsonb_array_elements(e.document->'allocations')line where line->>'movement_id'=p_id::text and line->>'lot_id'=m.lot_id::text and (line->>'quantity')::numeric=abs(m.quantity))
   and (
    (m.kind='native_return' and e.action='restock' and exists(select 1 from public.native_return_stock_links return_stock_link where return_stock_link.event_id=e.id and return_stock_link.movement_id=p_id and return_stock_link.lot_id=m.lot_id and return_stock_link.quantity=m.quantity))
    or (m.kind='native_return_compensation' and e.action='retract_restock' and s.writer='record_native_dispense_return_v2' and exists(select 1 from public.native_return_compensation_links return_compensation_link where return_compensation_link.event_id=e.id and return_compensation_link.movement_id=p_id and return_compensation_link.lot_id=m.lot_id and return_compensation_link.quantity=-m.quantity))
   )
  );
 else raise exception 'read_native_or_clinical_pending'using errcode='0A000';end case;
 if valid is distinct from true then raise exception 'Canonical stock source does not match movement'using errcode='23514';end if;
end

controlled_review_v3.read_unproven_summa.source:
declare required_value boolean:=(p_event->>'secondary_review_required')::boolean;
begin
 return jsonb_build_object('event_id',p_event->'id','event_sequence',p_event->>'sequence','event_kind',p_event->'event_kind','site_basis','unproven','site_id',null,
  'observed_at',p_event->'observed_at','recorded_at',p_event->'recorded_at','review_state',case when required_value then 'awaiting_review'else 'not_required'end,
  'deadline_state',case when required_value then 'historical_policy_unavailable'else 'not_required'end,'deadline_basis',case when required_value then 'historical_policy_unavailable'else 'not_required'end,
  'due_at',null,'unavailable_reason',case when required_value then 'site_unproven'else null end,'signing_state','blocked','signing_reason',case when required_value then 'unsupported_provenance'else 'not_required'end);
end

controlled_review_v3.read_validate_paren.source:
begin
 if p_row->>'request_hash'is distinct from public.controlled_stock_hash(jsonb_build_object('version',1,'actor_id',p_row->'actor_id','id',p_row->'id',
 'writer',p_row->'writer','canonical_arguments',p_row->'canonical_arguments','context',p_row->'context'))then
 raise exception 'review_history_integrity'using errcode='23514';end if;
end

controlled_review_v3.read_validate_retai.source:
declare row_value jsonb:=controlled_review_v3.protocol_retained_preparation(p_preparation);packet_value jsonb:=row_value->'packet';
 base_value jsonb;policy_value jsonb;read_value jsonb;review_value jsonb;authorization_value jsonb;stream_value jsonb;at_value timestamptz;
 actor_value uuid;product_value uuid;site_value uuid;kind_value text;member_value jsonb;
 begin
  base_value:=p_base;
  if packet_value-'current_authorization'is distinct from base_value then raise exception 'review_history_integrity'using errcode='23514';end if;
  actor_value:=(row_value->>'actor_id')::uuid;product_value:=(packet_value#>>'{target,product_id}')::uuid;
  site_value:=(packet_value#>>'{adapter,site_id}')::uuid;kind_value:=packet_value#>>'{adapter,event_kind}';at_value:=(row_value->>'created_at')::timestamptz;
  stream_value:=jsonb_build_object('kind','policy','product_id',product_value,'site_id',site_value,'event_kind',null,'capability',null);
  policy_value:=controlled_review_v3.read_select_configuration(jsonb_build_object('stream_key',stream_value,'at',controlled_review_v3.protocol_utc(at_value)));
  stream_value:=stream_value||jsonb_build_object('kind','eligibility','event_kind',kind_value,'capability','read');
  read_value:=controlled_review_v3.read_select_configuration(jsonb_build_object('stream_key',stream_value,'at',controlled_review_v3.protocol_utc(at_value)));
  stream_value:=stream_value||jsonb_build_object('capability','review');
  review_value:=controlled_review_v3.read_select_configuration(jsonb_build_object('stream_key',stream_value,'at',controlled_review_v3.protocol_utc(at_value)));
  if policy_value is null or read_value is null or review_value is null or policy_value->'id'is distinct from row_value->'policy_id'
   or read_value->'id'is distinct from row_value->'read_eligibility_id'or review_value->'id'is distinct from row_value->'review_eligibility_id'
   or policy_value->'enabled'is distinct from 'true'::jsonb or policy_value#>array['body','rules',kind_value,'enabled']is distinct from 'true'::jsonb then
   raise exception 'review_history_integrity'using errcode='23514';end if;
  authorization_value:=jsonb_build_object('policy',jsonb_build_object('id',policy_value->'id','record_hash',policy_value->'record_hash','rule',policy_value#>array['body','rules',kind_value]),
   'read',controlled_review_v3.protocol_retained_member(read_value,actor_value,product_value,site_value,kind_value,'read'),
   'review',controlled_review_v3.protocol_retained_member(review_value,actor_value,product_value,site_value,kind_value,'review'));
  if authorization_value is distinct from packet_value->'current_authorization'then raise exception 'review_history_integrity'using errcode='23514';end if;
 end

controlled_review_v3.read_validate_scala.source:
declare e public.controlled_stock_events;a public.controlled_stock_actions;r public.controlled_stock_preparations;
 b jsonb;effects jsonb;value jsonb;heads jsonb;frozen_container jsonb;actual numeric;expected numeric;v record;source uuid;expected_links integer;
begin
 perform controlled_review_v3.read_scalar_preflight(p_id);
 select * into e from public.controlled_stock_events where id=p_id;
 select * into a from public.controlled_stock_actions where id=p_id;
 select * into r from public.controlled_stock_preparations where id=p_id;
 if e.id is null or a.id is null or r.id is null or e.actor_id<>r.actor_id or a.actor_id<>r.actor_id
  or e.writer<>r.writer or a.writer<>r.writer or a.request_hash<>r.request_hash
  or e.product_id<>r.product_id or e.policy_version_id<>r.policy_version_id or e.opening_id<>r.opening_id
  or e.session_id<>a.session_id or e.recorded_at<>a.recorded_at or e.recorded_at<r.created_at
  or e.event_kind is distinct from public.controlled_stock_event_kind(r.writer,r.canonical_arguments)
  or e.basis is distinct from r.context#>>'{basis,kind}'or e.note is distinct from r.context#>>'{basis,note}'
  or e.observed_at is distinct from(case when e.basis='physical_record'then public.appointment_catalog_instant(r.context#>'{basis,observed_at}')else null end)
  or(e.observed_at is not null and(e.observed_at>e.recorded_at or e.observed_at<(select observed_at from public.controlled_stock_openings where id=e.opening_id)))
  or e.engine_revision is distinct from(select engine_revision from public.controlled_stock_policy_versions where id=e.policy_version_id)
  or e.secondary_review_required is distinct from(r.frozen#>>'{permission,secondary_review}')::boolean
  or e.clinical_snapshot is distinct from jsonb_build_object('catalog',r.frozen->'catalog','original_result',e.canonical_result)
  or e.context_hash<>public.controlled_stock_hash(r.context)
  or e.record_hash<>public.controlled_stock_hash(to_jsonb(e)-'record_hash')
  or exists(select 1 from public.controlled_stock_cancellations where id=p_id)then
  raise exception 'Exact immutable owned controlled event/action evidence required'using errcode='23514';end if;
 if e.sequence>1 and not exists(select 1 from public.controlled_stock_events prior where prior.id=e.prior_event_id
  and prior.product_id=e.product_id and prior.sequence=e.sequence-1 and prior.record_hash=e.prior_record_hash)then
  raise exception 'Controlled product event predecessor mismatch'using errcode='23514';end if;
 b:=controlled_review_v3.read_source_bundle(e.writer,e.id,e.actor_id,e.canonical_result);
 effects:=controlled_review_v3.read_source_effects(e.writer,e.id,e.actor_id,e.canonical_result);
 if e.source_bundle is distinct from b or e.source_effects is distinct from effects
  or public.controlled_stock_source_totals(effects)is distinct from public.controlled_stock_effect_totals(r.frozen->'expected_effects')then
  raise exception 'Controlled event must preserve every exact original canonical source'using errcode='23514';end if;
 expected_links:=jsonb_array_length(effects->'available')+case when b#>>'{native,kind}'in('return','pickup','discrepancy','correction')then 1 else 0 end;
 if(select count(*)from public.controlled_stock_source_links where event_id=e.id)<>expected_links then
  raise exception 'Exact controlled source-link membership required'using errcode='23514';end if;
 if b#>>'{native,kind}'in('return','pickup','discrepancy','correction')and not exists(
  select 1 from public.controlled_stock_source_links k where k.event_id=e.id and
   case b#>>'{native,kind}'when 'return'then k.return_event_id=e.id when 'pickup'then k.pickup_id=e.id
    when 'discrepancy'then k.discrepancy_event_id=e.id when 'correction'then k.correction_event_id=e.id else false end)then
  raise exception 'Exact original native source family and root required'using errcode='23514';end if;
 for value in select element.value from jsonb_array_elements(effects->'available')element(value)loop
  source:=null;
  select id into source from public.controlled_stock_source_links where event_id=e.id and movement_id=(value->>'id')::uuid;
  if source is null then raise exception 'Available stock movement missing its exact controlled source link'using errcode='23514';end if;
  select coalesce(sum(l.quantity_delta),0)into actual from public.controlled_stock_event_lines l
   join public.controlled_stock_cells c on c.id=l.cell_id
   where l.event_id=e.id and l.source_link_id=source and c.channel='available'and c.lot_id=(value->>'lot_id')::uuid;
  if actual is distinct from(value->>'quantity_delta')::numeric then
   raise exception 'Controlled available allocations must total their actual signed movement'using errcode='23514';end if;
 end loop;
 for value in select element.value from jsonb_array_elements(effects->'custody')element(value)loop
  select coalesce(sum(l.quantity_delta),0)into actual from public.controlled_stock_event_lines l
   join public.controlled_stock_cells c on c.id=l.cell_id join public.controlled_stock_source_links s on s.id=l.source_link_id
   where l.event_id=e.id and c.channel=value->>'channel'and c.lot_id=(value->>'lot_id')::uuid
    and c.allocation_id=(value->>'allocation_id')::uuid and c.dispense_id=(value->>'dispense_id')::uuid
    and c.intake_id is not distinct from(value->>'intake_id')::uuid
    and(case when b#>>'{native,kind}'='dispense'then s.movement_id=(select movement_id from public.native_dispense_allocations where id=c.allocation_id)
     else coalesce(s.return_event_id,s.pickup_id)=e.id end);
  if actual is distinct from(value->>'quantity_delta')::numeric then
   raise exception 'Controlled custody allocation must preserve its exact native source'using errcode='23514';end if;
 end loop;
 for v in select l.*,c.channel,c.lot_id,c.dispense_id,c.allocation_id,c.intake_id,c.container_id,s.event_id as source_event_id,
  s.movement_id,s.return_event_id,s.pickup_id,s.discrepancy_event_id,s.correction_event_id,t.product_id
  from public.controlled_stock_event_lines l join public.controlled_stock_cells c on c.id=l.cell_id
  join public.controlled_stock_source_links s on s.id=l.source_link_id
  join public.controlled_stock_containers t on t.id=c.container_id where l.event_id=e.id loop
  if v.source_event_id<>e.id or v.product_id<>e.product_id
   or not exists(select 1 from public.controlled_stock_container_transitions t where t.event_id=e.id and t.container_id=v.container_id
    and t.version_before=v.container_version_before and t.version_after=v.container_version_after)then
   raise exception 'Controlled line source, product and container transition must agree'using errcode='23514';end if;
  if v.channel='available'then
   if not exists(select 1 from jsonb_array_elements(effects->'available')x where(x->>'id')::uuid=v.movement_id
    and(x->>'lot_id')::uuid=v.lot_id and((x->>'quantity_delta')::numeric>0)=(v.quantity_delta>0))then
    raise exception 'Available line cannot borrow another source or hide an opposing movement'using errcode='23514';end if;
  else
   if not exists(select 1 from jsonb_array_elements(effects->'custody')x where x->>'channel'=v.channel
    and(x->>'lot_id')::uuid=v.lot_id and(x->>'allocation_id')::uuid=v.allocation_id
    and(x->>'dispense_id')::uuid=v.dispense_id and(x->>'intake_id')::uuid is not distinct from v.intake_id
    and((x->>'quantity_delta')::numeric>0)=(v.quantity_delta>0))then
    raise exception 'Custody line cannot borrow another native allocation or source meaning'using errcode='23514';end if;
  end if;
 end loop;
 if(select count(*)from public.controlled_stock_container_transitions where event_id=e.id)<>jsonb_array_length(r.context->'containers')then
  raise exception 'Every reviewed container must have one exact immutable transition'using errcode='23514';end if;
 for value in select element.value from jsonb_array_elements(r.context->'containers')element(value)loop
  select x.item into frozen_container from jsonb_array_elements(r.frozen->'containers')x(item)where x.item->>'id'=value->>'id';
  if frozen_container is null then raise exception 'Original frozen container frame required'using errcode='23514';end if;
  if value->'expected_version'='null'::jsonb then
   if not exists(select 1 from public.controlled_stock_containers c where c.id=(value->>'id')::uuid
    and c.created_event_id=e.id and c.opening_id is null and c.product_id=e.product_id
    and c.stock_unit=(select stock_unit from public.controlled_stock_policy_versions where id=e.policy_version_id)
    and c.kind=value#>>'{create,kind}'and c.label=value#>>'{create,label}'
    and c.stock_lot_id is not distinct from(value#>>'{create,stock_lot_id}')::uuid
    and c.controlling_site_id=(value#>>'{create,site_id}')::uuid and c.initial_location_id=(value#>>'{create,location_id}')::uuid
    and c.initial_custodian_id is not distinct from(value#>>'{create,custodian_id}')::uuid
    and c.actor_id=e.actor_id and c.session_id=e.session_id)then
    raise exception 'New physical container must preserve its exact reviewed identity and provenance'using errcode='23514';end if;
  elsif frozen_container->'container'is distinct from(select to_jsonb(c)from public.controlled_stock_containers c where c.id=(value->>'id')::uuid)then
   raise exception 'Existing immutable container differs from its original review'using errcode='23514';end if;
  if not exists(select 1 from public.controlled_stock_container_transitions t where t.event_id=e.id and t.container_id=(value->>'id')::uuid
   and t.before_location_id is not distinct from coalesce(frozen_container#>>'{head,location_id}',value#>>'{create,location_id}')::uuid
   and t.before_custodian_id is not distinct from coalesce(frozen_container#>>'{head,custodian_id}',value#>>'{create,custodian_id}')::uuid
   and t.before_status=coalesce(frozen_container#>>'{head,status}','onsite'))then
   raise exception 'Container transition must begin at its exact frozen reviewed state'using errcode='23514';end if;
  if not exists(select 1 from public.controlled_stock_container_transitions t where t.event_id=e.id and t.container_id=(value->>'id')::uuid
   and t.version_before=coalesce((value->>'expected_version')::bigint,0)
   and jsonb_build_object('status',t.after_status,'location_id',t.after_location_id,'custodian_id',t.after_custodian_id)=value->'after')then
   raise exception 'Immutable container transition differs from its reviewed after-state'using errcode='23514';end if;
  for v in select l as line_value from jsonb_array_elements(value->'lines')l loop
   select coalesce(sum(line.quantity_delta),0)into actual from public.controlled_stock_event_lines line
    join public.controlled_stock_cells c on c.id=line.cell_id
    where line.event_id=e.id and c.container_id=(value->>'id')::uuid and c.lot_id=(v.line_value->>'lot_id')::uuid
     and c.channel=v.line_value->>'channel'and c.dispense_id is not distinct from(v.line_value->>'dispense_id')::uuid
     and c.intake_id is not distinct from(v.line_value->>'intake_id')::uuid;
   if actual is distinct from(v.line_value->>'quantity_delta')::numeric then
    raise exception 'Posted container split differs from its immutable reviewed allocation'using errcode='23514';end if;
  end loop;
 end loop;
 select coalesce(jsonb_agg(jsonb_build_object('container_id',t.container_id,'version',t.version_after,
  'location_id',t.after_location_id,'custodian_id',t.after_custodian_id,'status',t.after_status,'last_event_id',t.event_id)order by t.container_id),'[]'::jsonb)
 into heads from public.controlled_stock_container_transitions t where t.event_id=e.id;
 if a.receipt is distinct from jsonb_build_object('version',1,'id',e.id,'writer',e.writer,'actor_id',e.actor_id,
  'canonical_result',e.canonical_result,'event',to_jsonb(e),'containers',heads)then
  raise exception 'Owned controlled receipt must preserve the original event and head transitions'using errcode='23514';end if;
end

