end

controlled_review_v3.validate_calendar_o.source:
declare body jsonb;observation jsonb;day_row jsonb;item jsonb;candidate jsonb;
 first_day date;last_day date;day_date date;idx integer:=0;zone_name text;version_text text;
 requested text[]:=array[]::text[];observed text[]:=array[]::text[];label text;previous_label text;
 local_value timestamp;utc_value timestamp;offset_seconds integer;utc_text text;previous_utc text;
 candidates jsonb;start_candidate jsonb;end_candidate jsonb;close_candidate jsonb;fold integer;
 start_value timestamp;end_value timestamp;close_value timestamp;previous_end timestamp;
begin
 if jsonb_typeof(p_request)is distinct from 'object'or octet_length(p_request::text)>131072 then
  raise exception 'calendar_observation_invalid'using errcode='23514';end if;
 if(select array_agg(k order by k)from jsonb_object_keys(p_request)k)is distinct from array['calendar','observation']then
  raise exception 'calendar_observation_invalid'using errcode='23514';end if;
 body:=p_request->'calendar';observation:=p_request->'observation';
 if jsonb_typeof(body)is distinct from 'object'or jsonb_typeof(observation)is distinct from 'object'then
  raise exception 'calendar_observation_invalid'using errcode='23514';end if;
 if(select array_agg(k order by k)from jsonb_object_keys(body)k)is distinct from array['days','first_date','last_date','zone']
 or(select array_agg(k order by k)from jsonb_object_keys(observation)k)is distinct from array['local_values','postgres_version','zone']then
  raise exception 'calendar_observation_invalid'using errcode='23514';end if;
 if jsonb_typeof(body->'zone')is distinct from 'string'or observation->'zone'is distinct from body->'zone'then
  raise exception 'calendar_observation_invalid'using errcode='23514';end if;
 zone_name:=body->>'zone';
 -- Retained names satisfy the supported lexical predicate; existence today is
 -- neither needed nor evidence of what the publishing environment observed.
 if octet_length(zone_name)not between 1 and 100 or(zone_name<>'UTC'and(
  zone_name!~'^[A-Za-z][A-Za-z0-9_+-]*(/[A-Za-z0-9_+-]+)+$'
  or zone_name like 'posix/%'or zone_name like 'right/%'))then
  raise exception 'calendar_observation_invalid'using errcode='23514';end if;
 version_text:=public.controlled_stock_text(observation->'postgres_version',200,false);
 if jsonb_typeof(body->'first_date')is distinct from 'string'or jsonb_typeof(body->'last_date')is distinct from 'string'
 or(body->>'first_date')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'or(body->>'last_date')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'then
  raise exception 'calendar_observation_invalid'using errcode='23514';end if;
 first_day:=(body->>'first_date')::date;last_day:=(body->>'last_date')::date;
 if first_day<date '2026-01-01'or last_day>=date '2101-01-01'or last_day-first_day not between 0 and 30
 or to_char(first_day,'YYYY-MM-DD')<>body->>'first_date'or to_char(last_day,'YYYY-MM-DD')<>body->>'last_date'then
  raise exception 'calendar_observation_invalid'using errcode='23514';end if;
 if jsonb_typeof(body->'days')is distinct from 'array'then
  raise exception 'calendar_observation_invalid'using errcode='23514';end if;
 if jsonb_array_length(body->'days')<>last_day-first_day+1 then
  raise exception 'calendar_observation_invalid'using errcode='23514';end if;
 for day_row in select value from jsonb_array_elements(body->'days')loop
  if jsonb_typeof(day_row)is distinct from 'object'then
   raise exception 'calendar_observation_invalid'using errcode='23514';end if;
  if(select array_agg(k order by k)from jsonb_object_keys(day_row)k)is distinct from
   array['close_fold','close_local','close_utc','date','end_utc','staffed','start_utc']then
   raise exception 'calendar_observation_invalid'using errcode='23514';end if;
  day_date:=first_day+idx;
  if day_row->'date'is distinct from to_jsonb(to_char(day_date,'YYYY-MM-DD'))
  or jsonb_typeof(day_row->'staffed')is distinct from 'boolean'then
   raise exception 'calendar_observation_invalid'using errcode='23514';end if;
  requested:=array_append(requested,to_char(day_date,'YYYY-MM-DD')||'T00:00:00');
  requested:=array_append(requested,to_char(day_date+1,'YYYY-MM-DD')||'T00:00:00');
  if(day_row->>'staffed')::boolean then
   if jsonb_typeof(day_row->'close_local')is distinct from 'string'
   or(day_row->>'close_local')!~'^([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9]$'
   or jsonb_typeof(day_row->'close_fold')is distinct from 'number'or(day_row->>'close_fold')!~'^[01]$'then
    raise exception 'calendar_observation_invalid'using errcode='23514';end if;
   requested:=array_append(requested,to_char(day_date,'YYYY-MM-DD')||'T'||(day_row->>'close_local'));
  elsif day_row->'close_local'is distinct from 'null'::jsonb or day_row->'close_fold'is distinct from 'null'::jsonb
  or day_row->'close_utc'is distinct from 'null'::jsonb then
   raise exception 'calendar_observation_invalid'using errcode='23514';end if;
  idx:=idx+1;
 end loop;
 select array_agg(value order by value collate "C")into requested from(select distinct unnest(requested)as value)q;
 if jsonb_typeof(observation->'local_values')is distinct from 'array'then
  raise exception 'calendar_observation_invalid'using errcode='23514';end if;
 if jsonb_array_length(observation->'local_values')not between 1 and 63 then
  raise exception 'calendar_observation_invalid'using errcode='23514';end if;
 for item in select value from jsonb_array_elements(observation->'local_values')loop
  if jsonb_typeof(item)is distinct from 'object'then
   raise exception 'calendar_observation_invalid'using errcode='23514';end if;
  if(select array_agg(k order by k)from jsonb_object_keys(item)k)is distinct from array['candidates','local_timestamp']
  or jsonb_typeof(item->'local_timestamp')is distinct from 'string'or jsonb_typeof(item->'candidates')is distinct from 'array'then
   raise exception 'calendar_observation_invalid'using errcode='23514';end if;
  label:=item->>'local_timestamp';
  if label!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}$'
  or(previous_label is not null and label collate "C"<=previous_label collate "C")then
   raise exception 'calendar_observation_invalid'using errcode='23514';end if;
  local_value:=label::timestamp;
  if not isfinite(local_value)or local_value<timestamp '2026-01-01 00:00:00'or local_value>timestamp '2101-01-01 00:00:00'
  or to_char(local_value,'YYYY-MM-DD"T"HH24:MI:SS')<>label or jsonb_array_length(item->'candidates')not between 1 and 2 then
   raise exception 'calendar_observation_invalid'using errcode='23514';end if;
  observed:=array_append(observed,label);previous_label:=label;previous_utc:=null;
  for candidate in select value from jsonb_array_elements(item->'candidates')loop
   if jsonb_typeof(candidate)is distinct from 'object'then
    raise exception 'calendar_observation_invalid'using errcode='23514';end if;
   if(select array_agg(k order by k)from jsonb_object_keys(candidate)k)is distinct from array['offset_seconds','utc']
   or jsonb_typeof(candidate->'utc')is distinct from 'string'or jsonb_typeof(candidate->'offset_seconds')is distinct from 'number'
   or(candidate->>'offset_seconds')!~'^-?(0|[1-9][0-9]*)$'then
    raise exception 'calendar_observation_invalid'using errcode='23514';end if;
   utc_text:=candidate->>'utc';offset_seconds:=(candidate->>'offset_seconds')::integer;
   if utc_text!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}Z$'
   or offset_seconds not between -50400 and 50400
   or(previous_utc is not null and utc_text collate "C"<=previous_utc collate "C")then
    raise exception 'calendar_observation_invalid'using errcode='23514';end if;
   -- Explicit UTC civil fields as timestamp WITHOUT time zone. No timezone
   -- lookup/conversion or current catalog can influence retained arithmetic.
   utc_value:=left(utc_text,26)::timestamp;
   if not isfinite(utc_value)or utc_value<timestamp '2026-01-01 00:00:00'or utc_value>=timestamp '2101-01-01 00:00:00'
   or to_char(utc_value,'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')<>utc_text
   or utc_value+offset_seconds*interval '1 second'<>local_value then
    raise exception 'calendar_observation_invalid'using errcode='23514';end if;
   previous_utc:=utc_text;
  end loop;
 end loop;
 if observed is distinct from requested then
  raise exception 'calendar_observation_invalid'using errcode='23514';end if;
 idx:=0;
 for day_row in select value from jsonb_array_elements(body->'days')loop
  day_date:=first_day+idx;
  select value#>'{candidates,0}'into strict start_candidate from jsonb_array_elements(observation->'local_values')
   where value->>'local_timestamp'=to_char(day_date,'YYYY-MM-DD')||'T00:00:00';
  select value#>'{candidates,0}'into strict end_candidate from jsonb_array_elements(observation->'local_values')
   where value->>'local_timestamp'=to_char(day_date+1,'YYYY-MM-DD')||'T00:00:00';
  if day_row->'start_utc'is distinct from start_candidate->'utc'or day_row->'end_utc'is distinct from end_candidate->'utc'then
   raise exception 'calendar_observation_invalid'using errcode='23514';end if;
  start_value:=left(start_candidate->>'utc',26)::timestamp;end_value:=left(end_candidate->>'utc',26)::timestamp;
  if end_value<=start_value or(previous_end is not null and previous_end<>start_value)then
   raise exception 'calendar_observation_invalid'using errcode='23514';end if;
  if(day_row->>'staffed')::boolean then
   select value->'candidates'into strict candidates from jsonb_array_elements(observation->'local_values')
    where value->>'local_timestamp'=to_char(day_date,'YYYY-MM-DD')||'T'||(day_row->>'close_local');
   fold:=(day_row->>'close_fold')::integer;
   if fold>=jsonb_array_length(candidates)then
    raise exception 'calendar_observation_invalid'using errcode='23514';end if;
   close_candidate:=candidates->fold;
   if day_row->'close_utc'is distinct from close_candidate->'utc'then
    raise exception 'calendar_observation_invalid'using errcode='23514';end if;
   close_value:=left(close_candidate->>'utc',26)::timestamp;
   if close_value<=start_value or close_value>=end_value then
    raise exception 'calendar_observation_invalid'using errcode='23514';end if;
  end if;
  previous_end:=end_value;idx:=idx+1;
 end loop;
 return p_request;
exception when invalid_text_representation or invalid_datetime_format or datetime_field_overflow
 or numeric_value_out_of_range or check_violation then
 raise exception 'calendar_observation_invalid'using errcode='23514';
end

controlled_review_v3.validate_configurat.source:
declare
 v_kind text; v_scope jsonb; v_body jsonb; v_enabled boolean; v_version integer;
 v_rules jsonb; v_rule jsonb; v_event_kind text; v_rule_enabled boolean;
 v_choice text; v_expected_mode text; v_expected_anchor text; v_expected_escalation text;
 v_calendar_required boolean:=false; v_routing_required boolean:=false;
 v_members jsonb; v_member jsonb; v_values jsonb; v_item jsonb;
 v_actor text; v_previous_actor text; v_label text; v_previous_label text;
 v_field text; v_count integer; v_index integer:=0;
 v_zone text; v_first date; v_last date; v_date date; v_day jsonb;
 v_stamp jsonb; v_stamp_value timestamptz; v_stamps jsonb[];
 v_start timestamptz; v_end timestamptz; v_close timestamptz; v_previous_end timestamptz;
 v_kinds constant text[]:=array[
  'receive_inventory','adjust_inventory','record_patient_treatment',
  'record_anesthesia_drug_administration','record_native_dispense','record_native_pickup',
  'record_native_dispense_return:intake','record_native_dispense_return:dispose',
  'record_native_dispense_return:restock','record_native_dispense_return_v2:intake',
  'record_native_dispense_return_v2:dispose','record_native_dispense_return_v2:restock',
  'record_native_dispense_return_v2:retract_intake','record_native_dispense_return_v2:retract_disposal',
  'record_native_dispense_return_v2:retract_restock','record_native_return_discrepancy:report',
  'record_native_return_discrepancy:note','record_native_return_discrepancy:resolve_corrected',
  'record_native_return_discrepancy:resolve_confirmed_original',
  'append_native_dispense_correction:clinical_annotation',
  'append_native_dispense_correction:operational_annotation',
  'append_native_dispense_correction:pickup_amendment'];
begin
 -- Bound the whole decoded input before any object/array expansion.
 if pg_catalog.jsonb_typeof(p_request)is distinct from 'object'
 or pg_catalog.octet_length(p_request::text)>131072 then
  raise exception 'configuration_invalid'using errcode='23514';end if;
 perform public.controlled_stock_keys(p_request,array['schema_version','kind','scope','version',
  'predecessor_id','predecessor_hash','enabled','body','approval_reference']);
 if pg_catalog.jsonb_typeof(p_request->'schema_version')is distinct from 'number'
 or p_request->>'schema_version'<>'1'
 or pg_catalog.jsonb_typeof(p_request->'version')is distinct from 'number'
 or (p_request->>'version')!~'^[1-9][0-9]{0,9}$'
 or pg_catalog.jsonb_typeof(p_request->'enabled')is distinct from 'boolean'
 or pg_catalog.jsonb_typeof(p_request->'kind')is distinct from 'string'then
  raise exception 'configuration_invalid'using errcode='23514';end if;
 v_version:=(p_request->>'version')::integer;
 v_kind:=p_request->>'kind';v_enabled:=(p_request->>'enabled')::boolean;
 if v_version<1 or not(v_kind=any(array['administration','policy','eligibility','calendar','routing']))then
  raise exception 'configuration_invalid'using errcode='23514';end if;
 if v_version=1 then
  if p_request->'predecessor_id'is distinct from 'null'::jsonb
  or p_request->'predecessor_hash'is distinct from 'null'::jsonb then
   raise exception 'configuration_invalid'using errcode='23514';end if;
 else
  perform public.controlled_stock_uuid(p_request->'predecessor_id');
  if pg_catalog.jsonb_typeof(p_request->'predecessor_hash')is distinct from 'string'
  or (p_request->>'predecessor_hash')!~'^[0-9a-f]{64}$'then
   raise exception 'configuration_invalid'using errcode='23514';end if;
 end if;
 perform public.controlled_stock_text(p_request->'approval_reference',200,false);
 v_scope:=p_request->'scope';v_body:=p_request->'body';
 perform public.controlled_stock_keys(v_scope,array['product_id','site_id','event_kind','capability']);
 perform public.controlled_stock_uuid(v_scope->'product_id');
 if v_kind='administration'then
  if v_scope->'site_id'is distinct from 'null'::jsonb
  or v_scope->'event_kind'is distinct from 'null'::jsonb
  or v_scope->'capability'is distinct from 'null'::jsonb then
   raise exception 'configuration_invalid'using errcode='23514';end if;
 elsif v_kind='eligibility'then
  if pg_catalog.jsonb_typeof(v_scope->'capability')is distinct from 'string'then
   raise exception 'configuration_invalid'using errcode='23514';end if;
  if v_scope->>'capability'='exception_read'then
   if v_scope->'site_id'is distinct from 'null'::jsonb
   or v_scope->'event_kind'is distinct from 'null'::jsonb then
    raise exception 'configuration_invalid'using errcode='23514';end if;
  elsif v_scope->>'capability'=any(array['read','review'])then
   perform public.controlled_stock_uuid(v_scope->'site_id');
   if pg_catalog.jsonb_typeof(v_scope->'event_kind')is distinct from 'string'
   or not((v_scope->>'event_kind')=any(v_kinds))then
    raise exception 'configuration_invalid'using errcode='23514';end if;
  else raise exception 'configuration_invalid'using errcode='23514';end if;
 else
  perform public.controlled_stock_uuid(v_scope->'site_id');
  if v_scope->'event_kind'is distinct from 'null'::jsonb
  or v_scope->'capability'is distinct from 'null'::jsonb then
   raise exception 'configuration_invalid'using errcode='23514';end if;
 end if;
 if v_kind=any(array['administration','eligibility','routing'])then
  perform public.controlled_stock_keys(v_body,array['members']);v_members:=v_body->'members';
  if pg_catalog.jsonb_typeof(v_members)is distinct from 'array'then
   raise exception 'configuration_invalid'using errcode='23514';end if;
  v_count:=pg_catalog.jsonb_array_length(v_members);
  if v_count>100 or(v_enabled and v_count=0)then
   raise exception 'configuration_invalid'using errcode='23514';end if;
  for v_member in select roster_entry.value from pg_catalog.jsonb_array_elements(v_members)as roster_entry(value)loop
   if v_kind='administration'then
    perform public.controlled_stock_keys(v_member,array['actor_id','roles','capabilities']);
   else perform public.controlled_stock_keys(v_member,array['actor_id','roles']);end if;
   v_actor:=public.controlled_stock_uuid(v_member->'actor_id')::text;
   if v_previous_actor is not null and v_actor collate "C"<=v_previous_actor collate "C"then
    raise exception 'configuration_invalid'using errcode='23514';end if;
   v_previous_actor:=v_actor;
   foreach v_field in array(case when v_kind='administration'then array['roles','capabilities']else array['roles']end)loop
    v_values:=v_member->v_field;
    if pg_catalog.jsonb_typeof(v_values)is distinct from 'array'then
     raise exception 'configuration_invalid'using errcode='23514';end if;
    v_count:=pg_catalog.jsonb_array_length(v_values);
    if(v_field='roles'and v_count not between 1 and 4)
    or(v_field='capabilities'and v_count>6)then
     raise exception 'configuration_invalid'using errcode='23514';end if;
    v_previous_label:=null;
    for v_item in select member_value.value from pg_catalog.jsonb_array_elements(v_values)as member_value(value)loop
     if pg_catalog.jsonb_typeof(v_item)is distinct from 'string'then
      raise exception 'configuration_invalid'using errcode='23514';end if;
     v_label:=v_item#>>'{}';
     if(v_field='roles'and not(v_label=any(array['ADMIN','DVM','STAFF','TECH'])))
     or(v_field='capabilities'and not(v_label=any(array['audit','manage_eligibility','manage_escalation','publish_calendar','publish_policy','publish_routing'])))
     or(v_previous_label is not null and v_label collate "C"<=v_previous_label collate "C")then
      raise exception 'configuration_invalid'using errcode='23514';end if;
     v_previous_label:=v_label;
    end loop;
   end loop;
  end loop;
 elsif v_kind='policy'then
  perform public.controlled_stock_keys(v_body,array['effective_from','calendar_id','routing_id','native_deadline_kind','rules']);
  perform public.controlled_stock_keys(v_body->'effective_from',array['mode','at']);
  if pg_catalog.jsonb_typeof(v_body->'effective_from'->'mode')is distinct from 'string'then
   raise exception 'configuration_invalid'using errcode='23514';end if;
  if v_body->'effective_from'->>'mode'='now'then
   if v_body->'effective_from'->'at'is distinct from 'null'::jsonb then
    raise exception 'configuration_invalid'using errcode='23514';end if;
  elsif v_body->'effective_from'->>'mode'='at'then
   v_stamp:=v_body->'effective_from'->'at';
   if pg_catalog.jsonb_typeof(v_stamp)is distinct from 'string'
   or(v_stamp#>>'{}')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}[.][0-9]{6}Z$'then
    raise exception 'configuration_invalid'using errcode='23514';end if;
   v_stamp_value:=(v_stamp#>>'{}')::timestamptz;
   if not pg_catalog.isfinite(v_stamp_value)
   or v_stamp_value<timestamptz '2026-01-01 00:00:00+00'
   or v_stamp_value>=timestamptz '2101-01-01 00:00:00+00'
   or pg_catalog.to_char(v_stamp_value at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')<>v_stamp#>>'{}'then
    raise exception 'configuration_invalid'using errcode='23514';end if;
  else raise exception 'configuration_invalid'using errcode='23514';end if;
  foreach v_field in array array['calendar_id','routing_id']loop
   if v_body->v_field is distinct from 'null'::jsonb then perform public.controlled_stock_uuid(v_body->v_field);end if;
  end loop;
  if v_body->'native_deadline_kind'='null'::jsonb then v_choice:=null;
  elsif pg_catalog.jsonb_typeof(v_body->'native_deadline_kind')='string'
  and(v_body->>'native_deadline_kind')=any(array['record_native_dispense','record_native_pickup'])then
   v_choice:=v_body->>'native_deadline_kind';
  else raise exception 'configuration_invalid'using errcode='23514';end if;
  v_rules:=v_body->'rules';
  -- Exact fixed keyset without expanding an unadmitted rules object.
  if pg_catalog.jsonb_typeof(v_rules)is distinct from 'object'
  or not(v_rules?&v_kinds)or(v_rules-v_kinds)<>'{}'::jsonb then
   raise exception 'configuration_invalid'using errcode='23514';end if;
  foreach v_event_kind in array v_kinds loop
   v_rule:=v_rules->v_event_kind;
   perform public.controlled_stock_keys(v_rule,array['enabled','adapter_version','meaning','quorum','deadline_mode','deadline_anchor','escalation_mode']);
   if pg_catalog.jsonb_typeof(v_rule->'enabled')is distinct from 'boolean'
   or pg_catalog.jsonb_typeof(v_rule->'adapter_version')is distinct from 'number'
   or v_rule->>'adapter_version'<>'1'
   or pg_catalog.jsonb_typeof(v_rule->'quorum')is distinct from 'number'
   or v_rule->>'quorum'<>'1'
   or v_rule->'meaning'is distinct from '"independent_record_review_v1"'::jsonb then
    raise exception 'configuration_invalid'using errcode='23514';end if;
   v_rule_enabled:=(v_rule->>'enabled')::boolean;
   v_expected_mode:='not_configured';v_expected_escalation:='not_configured';
   if v_event_kind=any(array['receive_inventory','adjust_inventory','record_patient_treatment',
    'record_anesthesia_drug_administration','record_native_dispense','record_native_pickup',
    'record_native_dispense_return:intake','record_native_dispense_return:dispose','record_native_dispense_return:restock',
    'record_native_dispense_return_v2:intake','record_native_dispense_return_v2:dispose','record_native_dispense_return_v2:restock'])then
    v_expected_anchor:='observed_at';
   else v_expected_anchor:='recorded_at';end if;
   if v_rule_enabled and(v_event_kind=any(array['record_patient_treatment','record_anesthesia_drug_administration'])or v_event_kind=v_choice)then
    v_expected_mode:='next_staffed_day_close';v_expected_escalation:='overdue';
   elsif v_rule_enabled and v_event_kind='record_native_return_discrepancy:report'then
    v_expected_escalation:='immediate_on_record';end if;
   if v_event_kind=v_choice and not v_rule_enabled then
    raise exception 'configuration_invalid'using errcode='23514';end if;
   if pg_catalog.jsonb_typeof(v_rule->'deadline_mode')is distinct from 'string'
   or pg_catalog.jsonb_typeof(v_rule->'deadline_anchor')is distinct from 'string'
   or pg_catalog.jsonb_typeof(v_rule->'escalation_mode')is distinct from 'string'
   or v_rule->>'deadline_mode'<>v_expected_mode
   or v_rule->>'deadline_anchor'<>v_expected_anchor
   or v_rule->>'escalation_mode'<>v_expected_escalation then
    raise exception 'configuration_invalid'using errcode='23514';end if;
   v_calendar_required:=v_calendar_required or v_expected_mode='next_staffed_day_close';
   v_routing_required:=v_routing_required or v_expected_escalation=any(array['overdue','immediate_on_record']);
  end loop;
  if(v_calendar_required and v_body->'calendar_id'='null'::jsonb)
  or(v_routing_required and v_body->'routing_id'='null'::jsonb)then
   raise exception 'configuration_invalid'using errcode='23514';end if;
 else
  perform public.controlled_stock_keys(v_body,array['zone','first_date','last_date','days']);
  if pg_catalog.jsonb_typeof(v_body->'zone')is distinct from 'string'then
   raise exception 'configuration_invalid'using errcode='23514';end if;
  v_zone:=v_body->>'zone';
  if pg_catalog.octet_length(v_zone)not between 1 and 100
  or pg_catalog.octet_length(v_zone)<>pg_catalog.char_length(v_zone)
  or(v_zone<>'UTC'and(v_zone!~'^[A-Za-z][A-Za-z0-9_+-]*(/[A-Za-z0-9_+-]+)+$'
   or v_zone like 'posix/%'or v_zone like 'right/%'))then
   raise exception 'configuration_invalid'using errcode='23514';end if;
  if pg_catalog.jsonb_typeof(v_body->'first_date')is distinct from 'string'
  or pg_catalog.jsonb_typeof(v_body->'last_date')is distinct from 'string'
  or(v_body->>'first_date')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
  or(v_body->>'last_date')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'then
   raise exception 'configuration_invalid'using errcode='23514';end if;
  v_first:=(v_body->>'first_date')::date;v_last:=(v_body->>'last_date')::date;
  if v_first<date '2026-01-01'or v_last>=date '2101-01-01'or v_last-v_first not between 0 and 30
  or pg_catalog.to_char(v_first,'YYYY-MM-DD')<>v_body->>'first_date'
  or pg_catalog.to_char(v_last,'YYYY-MM-DD')<>v_body->>'last_date'then
   raise exception 'configuration_invalid'using errcode='23514';end if;
  if pg_catalog.jsonb_typeof(v_body->'days')is distinct from 'array'then
   raise exception 'configuration_invalid'using errcode='23514';end if;
  if pg_catalog.jsonb_array_length(v_body->'days')<>v_last-v_first+1 then
   raise exception 'configuration_invalid'using errcode='23514';end if;
  for v_day in select calendar_day.value from pg_catalog.jsonb_array_elements(v_body->'days')as calendar_day(value)loop
   perform public.controlled_stock_keys(v_day,array['date','staffed','start_utc','end_utc','close_local','close_fold','close_utc']);
   v_date:=v_first+v_index;v_index:=v_index+1;
   if v_day->'date'is distinct from pg_catalog.to_jsonb(pg_catalog.to_char(v_date,'YYYY-MM-DD'))
   or pg_catalog.jsonb_typeof(v_day->'staffed')is distinct from 'boolean'then
    raise exception 'configuration_invalid'using errcode='23514';end if;
   v_stamps:=array[v_day->'start_utc',v_day->'end_utc'];
   if(v_day->>'staffed')::boolean then
    if pg_catalog.jsonb_typeof(v_day->'close_local')is distinct from 'string'
    or(v_day->>'close_local')!~'^([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9]$'
    or pg_catalog.jsonb_typeof(v_day->'close_fold')is distinct from 'number'
    or(v_day->>'close_fold')not in('0','1')then
     raise exception 'configuration_invalid'using errcode='23514';end if;
    v_stamps:=pg_catalog.array_append(v_stamps,v_day->'close_utc');
   elsif v_day->'close_local'is distinct from 'null'::jsonb
   or v_day->'close_fold'is distinct from 'null'::jsonb
   or v_day->'close_utc'is distinct from 'null'::jsonb then
    raise exception 'configuration_invalid'using errcode='23514';end if;
   foreach v_stamp in array v_stamps loop
    if pg_catalog.jsonb_typeof(v_stamp)is distinct from 'string'
    or(v_stamp#>>'{}')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}[.][0-9]{6}Z$'then
     raise exception 'configuration_invalid'using errcode='23514';end if;
    v_stamp_value:=(v_stamp#>>'{}')::timestamptz;
    if not pg_catalog.isfinite(v_stamp_value)
    or v_stamp_value<timestamptz '2026-01-01 00:00:00+00'
    or v_stamp_value>=timestamptz '2101-01-01 00:00:00+00'
    or pg_catalog.to_char(v_stamp_value at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')<>v_stamp#>>'{}'then
     raise exception 'configuration_invalid'using errcode='23514';end if;
   end loop;
   v_start:=(v_day->>'start_utc')::timestamptz;v_end:=(v_day->>'end_utc')::timestamptz;
   if v_end<=v_start or(v_previous_end is not null and v_start<>v_previous_end)then
    raise exception 'configuration_invalid'using errcode='23514';end if;
   v_previous_end:=v_end;
   if(v_day->>'staffed')::boolean then
    v_close:=(v_day->>'close_utc')::timestamptz;
    if v_close<=v_start or v_close>=v_end then
     raise exception 'configuration_invalid'using errcode='23514';end if;
   end if;
  end loop;
 end if;
 return p_request;
exception
 when check_violation or invalid_text_representation or numeric_value_out_of_range
 or invalid_datetime_format or datetime_field_overflow then
  raise exception 'configuration_invalid'using errcode='23514';
end;

declare configuration_dto jsonb;publication_dto jsonb;complete_record jsonb;original_request jsonb;
 caller_document jsonb;stored_comparison jsonb;expected_stored jsonb;receipt_value jsonb;expected_receipt jsonb;mode_text text;
begin
 if jsonb_typeof(p_request)is distinct from 'object'or octet_length(p_request::text)>524288 then
  raise exception 'configuration_pair_invalid'using errcode='23514';end if;
 perform public.controlled_stock_keys(p_request,array['configuration','publication']);
 configuration_dto:=p_request->'configuration';publication_dto:=p_request->'publication';
 if jsonb_typeof(configuration_dto)is distinct from 'object'or octet_length(configuration_dto::text)>262144
  or jsonb_typeof(publication_dto)is distinct from 'object'or octet_length(publication_dto::text)>393216 then
  raise exception 'configuration_pair_invalid'using errcode='23514';end if;
 perform public.controlled_stock_keys(publication_dto,array['operation_id','actor_id','request','request_hash','record_id','receipt','recorded_at','mode']);
 original_request:=publication_dto->'request';receipt_value:=publication_dto->'receipt';
 if jsonb_typeof(original_request)is distinct from 'object'or octet_length(original_request::text)>131072
  or jsonb_typeof(receipt_value)is distinct from 'object'or octet_length(receipt_value::text)>131072 then
  raise exception 'configuration_pair_invalid'using errcode='23514';end if;
 complete_record:=controlled_review_v3.configuration_record(configuration_dto);
 perform public.controlled_stock_uuid(publication_dto->'operation_id');
 perform public.controlled_stock_uuid(publication_dto->'record_id');
 if jsonb_typeof(publication_dto->'request_hash')is distinct from 'string'
  or(publication_dto->>'request_hash')!~'^[0-9a-f]{64}$'
  or jsonb_typeof(publication_dto->'mode')is distinct from 'string'
  or jsonb_typeof(publication_dto->'recorded_at')is distinct from 'string'then
  raise exception 'configuration_pair_invalid'using errcode='23514';end if;
 -- Equality to validated canonical metadata also validates exact UTC6/null form.
 if publication_dto->'operation_id'is distinct from complete_record->'publication_operation_id'
  or publication_dto->'record_id'is distinct from complete_record->'id'
  or publication_dto->'actor_id'is distinct from complete_record->'publisher_actor_id'
  or publication_dto->'mode'is distinct from complete_record->'publication_mode'
  or publication_dto->'recorded_at'is distinct from complete_record->'published_at'then
  raise exception 'configuration_pair_invalid'using errcode='23514';end if;
 mode_text:=complete_record->>'publication_mode';
 if mode_text='staff'then
  perform public.controlled_stock_keys(original_request,array['actor_id','operation_id','record_id','document']);
  perform public.controlled_stock_uuid(original_request->'actor_id');
  if original_request->'actor_id'is distinct from complete_record->'publisher_actor_id'then
   raise exception 'configuration_pair_invalid'using errcode='23514';end if;
 else
  perform public.controlled_stock_keys(original_request,array['operation_id','record_id','document','reason']);
  perform public.controlled_stock_text(original_request->'reason',4000,true);
 end if;
 perform public.controlled_stock_uuid(original_request->'operation_id');
 perform public.controlled_stock_uuid(original_request->'record_id');
 if original_request->'operation_id'is distinct from publication_dto->'operation_id'
  or original_request->'record_id'is distinct from publication_dto->'record_id'then
  raise exception 'configuration_pair_invalid'using errcode='23514';end if;
 caller_document:=original_request->'document';
 perform controlled_review_v3.validate_configuration(caller_document);
 stored_comparison:=(configuration_dto->'document')-'calendar_observation';
 expected_stored:=caller_document;
 if complete_record->'kind'='"policy"'::jsonb then
  if caller_document#>>'{body,effective_from,mode}'='now'then
   expected_stored:=jsonb_set(caller_document,'{body,effective_from}',complete_record->'published_at',false);
  elsif caller_document#>>'{body,effective_from,mode}'='at'then
   expected_stored:=jsonb_set(caller_document,'{body,effective_from}',caller_document#>'{body,effective_from,at}',false);
  else raise exception 'configuration_pair_invalid'using errcode='23514';end if;
 end if;
 if stored_comparison is distinct from expected_stored then raise exception 'configuration_pair_invalid'using errcode='23514';end if;
 if publication_dto->>'request_hash'is distinct from public.controlled_stock_hash(original_request)then
  raise exception 'configuration_pair_invalid'using errcode='23514';end if;
 perform public.controlled_stock_keys(receipt_value,array['version','operation_id','request_hash','record_id','record_hash','publisher_actor_id','publisher_session_id','publisher_name','authorization_id','publication_mode','published_at']);
 if jsonb_typeof(receipt_value->'version')is distinct from 'number'or receipt_value->>'version'<>'3'then
  raise exception 'configuration_pair_invalid'using errcode='23514';end if;
 expected_receipt:=jsonb_build_object('version',3,'operation_id',publication_dto->'operation_id','request_hash',publication_dto->'request_hash',
  'record_id',complete_record->'id','record_hash',complete_record->'record_hash','publisher_actor_id',complete_record->'publisher_actor_id',
  'publisher_session_id',complete_record->'publisher_session_id','publisher_name',complete_record->'publisher_name',
  'authorization_id',complete_record->'authorization_id','publication_mode',complete_record->'publication_mode','published_at',complete_record->'published_at');
 if receipt_value is distinct from expected_receipt then raise exception 'configuration_pair_invalid'using errcode='23514';end if;
 return p_request;
exception when check_violation or invalid_text_representation or invalid_datetime_format
 or datetime_field_overflow or numeric_value_out_of_range then
 raise exception 'configuration_pair_invalid'using errcode='23514';
end

declare stored_document jsonb;published_text text;published_value timestamp;effective_value timestamp;
 mode_text text;kind_text text;version_value integer;
begin
 if jsonb_typeof(p_request)is distinct from 'object'or octet_length(p_request::text)>262144 then
  raise exception 'configuration_record_invalid'using errcode='23514';end if;
 perform public.controlled_stock_keys(p_request,array['schema_version','kind','scope','version','predecessor_id','predecessor_hash','enabled','body','approval_reference','id','publication_operation_id','published_at','publisher_actor_id','publisher_session_id','publisher_name','authorization_id','calendar_observation','publication_mode','record_hash']);
 stored_document:=p_request-array['id','publication_operation_id','published_at','publisher_actor_id','publisher_session_id','publisher_name','authorization_id','publication_mode','record_hash'];
 if octet_length(stored_document::text)>131072 then raise exception 'configuration_record_invalid'using errcode='23514';end if;
 perform controlled_review_v3.validate_stored_configuration(stored_document);
 perform public.controlled_stock_uuid(p_request->'id');
 perform public.controlled_stock_uuid(p_request->'publication_operation_id');
 if p_request->'id'=p_request->'predecessor_id'then raise exception 'configuration_record_invalid'using errcode='23514';end if;
 perform public.controlled_stock_text(p_request->'publisher_name',200,false);
 if jsonb_typeof(p_request->'published_at')is distinct from 'string'
  or jsonb_typeof(p_request->'publication_mode')is distinct from 'string'
  or jsonb_typeof(p_request->'record_hash')is distinct from 'string'
  or(p_request->>'record_hash')!~'^[0-9a-f]{64}$'then
  raise exception 'configuration_record_invalid'using errcode='23514';end if;
 published_text:=p_request->>'published_at';
 if published_text!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}Z$'then
  raise exception 'configuration_record_invalid'using errcode='23514';end if;
 published_value:=left(published_text,26)::timestamp;
 if not isfinite(published_value)or published_value<timestamp '2026-01-01 00:00:00'
  or published_value>=timestamp '2101-01-01 00:00:00'
  or to_char(published_value,'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')<>published_text then
  raise exception 'configuration_record_invalid'using errcode='23514';end if;
 mode_text:=p_request->>'publication_mode';kind_text:=p_request->>'kind';version_value:=(p_request->>'version')::integer;
 if mode_text='staff'then
  if kind_text='administration'then raise exception 'configuration_record_invalid'using errcode='23514';end if;
  perform public.controlled_stock_uuid(p_request->'publisher_actor_id');
  perform public.controlled_stock_uuid(p_request->'publisher_session_id');
  perform public.controlled_stock_uuid(p_request->'authorization_id');
 elsif mode_text in('owner_bootstrap','owner_recovery')then
  if kind_text<>'administration'or p_request->'publisher_actor_id'is distinct from 'null'::jsonb
   or p_request->'publisher_session_id'is distinct from 'null'::jsonb
   or p_request->'authorization_id'is distinct from 'null'::jsonb
   or p_request->'publisher_name'is distinct from '"Database owner (postgres)"'::jsonb
   or(mode_text='owner_bootstrap'and version_value<>1)
   or(mode_text='owner_recovery'and version_value<=1)then
   raise exception 'configuration_record_invalid'using errcode='23514';end if;
 else raise exception 'configuration_record_invalid'using errcode='23514';end if;
 if kind_text='policy'then
  -- Stored helper already established exact UTC civil spelling and range.
  effective_value:=left(p_request#>>'{body,effective_from}',26)::timestamp;
  if effective_value<published_value then raise exception 'configuration_record_invalid'using errcode='23514';end if;
 end if;
 if p_request->>'record_hash'is distinct from public.controlled_stock_hash(p_request-'record_hash')then
  raise exception 'configuration_record_invalid'using errcode='23514';end if;
 return p_request;
exception when check_violation or invalid_text_representation or invalid_datetime_format
 or datetime_field_overflow or numeric_value_out_of_range then
 raise exception 'configuration_record_invalid'using errcode='23514';
end

controlled_review_v3.validate_stored_con.source:
declare caller_copy jsonb;effective_text text;effective_value timestamp;calendar_pair jsonb;
begin
 if jsonb_typeof(p_request)is distinct from 'object'or octet_length(p_request::text)>131072 then
  raise exception 'stored_configuration_invalid'using errcode='23514';end if;
 perform public.controlled_stock_keys(p_request,array['schema_version','kind','scope','version','predecessor_id','predecessor_hash','enabled','body','approval_reference','calendar_observation']);
 caller_copy:=p_request-'calendar_observation';
 if p_request->'kind'='"policy"'::jsonb then
  if jsonb_typeof(p_request->'body')is distinct from 'object'
   or jsonb_typeof(p_request#>'{body,effective_from}')is distinct from 'string'then
   raise exception 'stored_configuration_invalid'using errcode='23514';end if;
  effective_text:=p_request#>>'{body,effective_from}';
  if effective_text!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}Z$'then
   raise exception 'stored_configuration_invalid'using errcode='23514';end if;
  effective_value:=left(effective_text,26)::timestamp;
  if not isfinite(effective_value)or effective_value<timestamp '2026-01-01 00:00:00'
   or effective_value>=timestamp '2101-01-01 00:00:00'
   or to_char(effective_value,'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')<>effective_text then
   raise exception 'stored_configuration_invalid'using errcode='23514';end if;
  -- Validation-only shape adapter; never the original saved publication request.
  caller_copy:=jsonb_set(caller_copy,'{body,effective_from}',jsonb_build_object('mode','at','at',effective_text),false);
 end if;
 if p_request->'kind'='"calendar"'::jsonb then
  if jsonb_typeof(p_request->'calendar_observation')is distinct from 'object'then
   raise exception 'stored_configuration_invalid'using errcode='23514';end if;
 else
  if p_request->'calendar_observation'is distinct from 'null'::jsonb then
   raise exception 'stored_configuration_invalid'using errcode='23514';end if;
 end if;
 if octet_length(caller_copy::text)>131072 then raise exception 'stored_configuration_invalid'using errcode='23514';end if;
 perform controlled_review_v3.validate_configuration(caller_copy);
 if p_request->'kind'='"calendar"'::jsonb then
  calendar_pair:=jsonb_build_object('calendar',p_request->'body','observation',p_request->'calendar_observation');
  if octet_length(calendar_pair::text)>131072 then raise exception 'stored_configuration_invalid'using errcode='23514';end if;
  perform controlled_review_v3.validate_calendar_observation(calendar_pair);
 end if;
 return p_request;
exception when check_violation or invalid_text_representation or invalid_datetime_format
 or datetime_field_overflow or numeric_value_out_of_range then
 raise exception 'stored_configuration_invalid'using errcode='23514';
end

public.execute_controlled_stock_action_v.source:
declare request_value jsonb;actor_value uuid;operation_value uuid;result_value jsonb;
begin
 if session_user<>'authenticator'or current_user<>'postgres'or pg_catalog.pg_my_temp_schema()<>0 then
  raise exception 'source_clinical_origin_invalid'using errcode='42501';end if;
  perform controlled_review_v3.read_practice_preflight();
  perform controlled_review_v3.read_relation_preflight();
  perform controlled_review_v3.ops_admin_preflight();
 request_value:=controlled_review_v3.protocol_operation_request(p_request);
 actor_value:=(request_value->>'actor_id')::uuid;operation_value:=(request_value->>'operation_id')::uuid;
 perform controlled_review_v3.protocol_identity(actor_value);
 perform pg_advisory_xact_lock_shared(90271040,0);
 perform controlled_review_v3.protocol_identity(actor_value);
 perform controlled_review_v3.required();
 result_value:=public.execute_controlled_stock_action(actor_value,operation_value);
 perform controlled_review_v3.protocol_identity(actor_value);
 if pg_catalog.pg_my_temp_schema()<>0 then raise exception 'source_clinical_origin_invalid'using errcode='42501';end if;
 return result_value;
end

